INSERT INTO curriculum_oa (grade_level, subject, code, description) VALUES
  ('1° Básico', 'Artes Visuales', 'OA1', 'Expresar y crear trabajos de arte a partir de la observación del: entorno natural: paisaje, animales y plantas · entorno cultural: vida cotidiana y familiar · entorno artístico: obras de arte local, chileno, latinoamericano y del resto del mundo'),
  ('1° Básico', 'Artes Visuales', 'OA2', 'Experimentar y aplicar elementos del lenguaje visual en sus trabajos de arte: · línea (gruesa, delgada, recta, ondulada e irregular) · color (puro, mezclado, fríos y cálidos) · textura (visual y táctil)'),
  ('1° Básico', 'Artes Visuales', 'OA3', 'Expresar emociones e ideas en sus trabajos de arte a partir de la experimentación con: · materiales de modelado, de reciclaje, naturales, papeles, cartones, pegamentos, lápices, pinturas, textiles e imágenes digitales · herramientas para dibujar, pintar, cortar, modelar, unir y tecnológicas (pincel, tijera, esteca, computador, entre otras) · procedimientos de dibujo, pintura, collage, escultura, dibujo digital y otros'),
  ('1° Básico', 'Artes Visuales', 'OA4', 'Observar y comunicar oralmente sus primeras impresiones de lo que sienten y piensan de obras de arte por variados medios. (Observar anualmente al menos 10 obras de arte local o chileno, 10 latinoamericanas y 10 de arte universal).'),
  ('1° Básico', 'Artes Visuales', 'OA5', 'Explicar sus preferencias frente al trabajo de arte personal y de sus pares, usando elementos del lenguaje visual.'),
  ('1° Básico', 'Ciencias Naturales', 'OA1', 'Reconocer y observar, por medio de la exploración, que los seres vivos crecen, responden a estímulos del medio, se reproducen y necesitan agua, alimento y aire para vivir, comparándolos con las cosas no vivas.'),
  ('1° Básico', 'Ciencias Naturales', 'OA2', 'Observar y comparar animales de acuerdo a características como tamaño, cubierta corporal, estructuras de desplazamiento y hábitat, entre otras.'),
  ('1° Básico', 'Ciencias Naturales', 'OA3', 'Observar e identificar, por medio de la exploración, las estructuras principales de las plantas: hojas, flores, tallos y raíces.'),
  ('1° Básico', 'Ciencias Naturales', 'OA4', 'Observar y clasificar semillas, frutos, flores y tallos a partir de criterios como tamaño, forma, textura y color, entre otros.'),
  ('1° Básico', 'Ciencias Naturales', 'OA5', 'Reconocer y comparar diversas plantas y animales de nuestro país, considerando las características observables y proponiendo medidas para su cuidado. C uer p o h u m an o y s alud'),
  ('1° Básico', 'Ciencias Naturales', 'OA6', 'Identificar y describir la ubicación y la función de los sentidos, proponiendo medidas para protegerlos y para prevenir situaciones de riesgo.'),
  ('1° Básico', 'Ciencias Naturales', 'OA7', 'Describir, dar ejemplos y practicar hábitos de vida saludable para mantener el cuerpo sano y prevenir enfermedades (actividad física, aseo del cuerpo, lavado de alimentos y alimentación saludable, entre otros).'),
  ('1° Básico', 'Ciencias Naturales', 'OA8', 'Explorar y describir los diferentes tipos de materiales en diversos objetos, clasificándolos según sus propiedades (goma-flexible, plástico-impermeable) e identificando su uso en la vida cotidiana.'),
  ('1° Básico', 'Ciencias Naturales', 'OA9', 'Observar y describir los cambios que se producen en los materiales al aplicarles fuerza, luz, calor y agua.'),
  ('1° Básico', 'Ciencias Naturales', 'OA10', 'Diseñar instrumentos tecnológicos simples, considerando diversos materiales y sus propiedades para resolver problemas cotidianos.'),
  ('1° Básico', 'Ciencias Naturales', 'OA11', 'Describir y registrar el ciclo diario y las diferencias entre el día y la noche, a partir de la observación del Sol, la Luna, las estrellas y la luminosidad del cielo, entre otras, y sus efectos en los seres vivos y el ambiente.'),
  ('1° Básico', 'Ciencias Naturales', 'OA12', 'Describir y comunicar los cambios del ciclo de las estaciones y sus efectos en los seres vivos y el ambiente.'),
  ('1° Básico', 'Educación Física', 'OA1', 'Demostrar habilidades motrices básicas de locomoción, manipulación y estabilidad en una variedad de juegos y actividades físicas, como saltar con dos pies en una dirección, caminar y correr alternadamente, lanzar y recoger un balón, caminar sobre una línea manteniendo el control del cuerpo, realizar suspensiones, giros y rodadas o volteos.'),
  ('1° Básico', 'Educación Física', 'OA2', 'Ejecutar acciones motrices en relación a sí mismo, a un objeto o un compañero, usando diferentes categorías de ubicación espacial y temporal, como derecha, izquierda, adelante, atrás, arriba, abajo, adentro, afuera, entre, al lado, antes, durante, después, rápido y lento.'),
  ('1° Básico', 'Educación Física', 'OA3', 'Practicar una amplia gama de juegos con y sin oposición, con y sin colaboración, de persecución, individuales y colectivos.'),
  ('1° Básico', 'Educación Física', 'OA4', 'Ejecutar habilidades motrices básicas en diferentes entornos, como las plazas activas, el patio del colegio, parques, playas, entre otros.'),
  ('1° Básico', 'Educación Física', 'OA5', 'Ejecutar movimientos corporales, expresando sensaciones, ideas, estados de ánimo y emociones en variados espacios y a diferentes ritmos.'),
  ('1° Básico', 'Educación Física', 'OA6', 'Ejecutar actividades físicas de intensidad moderada a vigorosa que incrementen la condición física, por medio de juegos y circuitos.'),
  ('1° Básico', 'Educación Física', 'OA7', 'Practicar en su vida cotidiana de forma guiada actividades físicas de intensidad moderada a vigorosa por medio de juegos tradicionales y actividades lúdicas.'),
  ('1° Básico', 'Educación Física', 'OA8', 'Reconocer las sensaciones y respuestas corporales provocadas por la práctica de actividad física, como cambios del color de la piel, sudor, agitación, ritmo de respiración, cansancio y dificultad al hablar.'),
  ('1° Básico', 'Educación Física', 'OA9', 'Practicar actividades físicas en forma segura, demostrando la adquisición de hábitos de higiene, posturales y de vida saludable, como lavarse las manos y la cara después de la clase, mantener una correcta postura y comer una colación saludable antes y luego de la práctica de actividad física.'),
  ('1° Básico', 'Educación Física', 'OA10', 'Practicar juegos o actividades motrices para aprender a trabajar en equipo, asumiendo diferentes roles (respetar al otro, recoger los materiales solicitados o liderar si se le asigna ese rol).'),
  ('1° Básico', 'Educación Física', 'OA11', 'Practicar actividades físicas, demostrando comportamientos seguros, como: · realizar un calentamiento mediante un juego · escuchar y seguir instrucciones · utilizar implementos bajo supervisión · mantener su posición dentro de los límites establecidos para la actividad'),
  ('1° Básico', 'Historia, Geografía y Cs. Sociales', 'OA1', 'Nombrar y secuenciar días de la semana y meses del año, utilizando calendarios, e identificar el año en curso.'),
  ('1° Básico', 'Historia, Geografía y Cs. Sociales', 'OA2', 'Secuenciar acontecimientos y actividades de la vida cotidiana, personal y familiar, utilizando categorías relativas de ubicación temporal, como antes, después; ayer, hoy, mañana; día, noche; este año, el año pasado, el año próximo.'),
  ('1° Básico', 'Historia, Geografía y Cs. Sociales', 'OA3', 'Registrar y comunicar información sobre elementos que forman parte de su identidad personal (nombre, fecha de nacimiento, lugar de procedencia, ascendencias, gustos, intereses, amigos y otros) para reconocer sus características individuales.'),
  ('1° Básico', 'Historia, Geografía y Cs. Sociales', 'OA4', 'Obtener y comunicar aspectos de la historia de su familia y sus características, como costumbres, tradiciones, ritos, fiestas, recuerdos y roles que desempeñan los distintos miembros de su grupo familiar, mediante la formulación de preguntas a adultos de su entorno cercano.'),
  ('1° Básico', 'Historia, Geografía y Cs. Sociales', 'OA5', 'Reconocer los símbolos representativos de Chile (como la bandera, el escudo y el himno nacional), describir costumbres, actividades y la participación de hombres y mujeres respecto de conmemoraciones nacionales (como Fiestas Patrias, Día del Descubrimiento de dos mundos y Combate Naval de Iquique) y reconocer en ellos un elemento de unidad e identidad nacional.'),
  ('1° Básico', 'Historia, Geografía y Cs. Sociales', 'OA6', 'Conocer expresiones culturales locales y nacionales (como comidas, flores y animales típicos, música y juegos, entre otros), describir fiestas y tradiciones importantes de nivel local (como Fiesta de La Tirana, Fiesta de San Pedro, Fiesta de Cuasimodo, carreras a la chilena, el rodeo, la vendimia y la fundación del pueblo o de la ciudad, entre otras) y reconocer estas expresiones como elementos de unidad e identidad local y/o nacional.'),
  ('1° Básico', 'Historia, Geografía y Cs. Sociales', 'OA7', 'Conocer sobre la vida de hombres y mujeres que han contribuido a la sociedad chilena en diversos ámbitos; por ejemplo, los fundadores de las ciudades, los exploradores, las personas que han fundado o creado instituciones, las personas que se han destacado por su emprendimiento y su solidaridad, los deportistas, los científicos, los artistas y los grandes poetas, entre otros.'),
  ('1° Básico', 'Historia, Geografía y Cs. Sociales', 'OA8', 'Reconocer que los mapas y los planos son formas de representar lugares.'),
  ('1° Básico', 'Historia, Geografía y Cs. Sociales', 'OA9', 'Identificar a Chile en mapas, incluyendo la cordillera de los Andes, el océano Pacífico, la ciudad de Santiago, su región, su capital y su localidad.'),
  ('1° Básico', 'Historia, Geografía y Cs. Sociales', 'OA10', 'Observar y describir paisajes de su entorno local, utilizando vocabulario geográfico adecuado (país, ciudad, camino, pueblo, construcciones, cordillera, mar, vegetación y desierto) y categorías de ubicación relativa (derecha, izquierda, delante, detrás, entre otros).'),
  ('1° Básico', 'Historia, Geografía y Cs. Sociales', 'OA11', 'Identificar trabajos y productos de su familia y su localidad y cómo estos aportan a su vida diaria, reconociendo la importancia de todos los trabajos, tanto remunerados como no remunerados.'),
  ('1° Básico', 'Historia, Geografía y Cs. Sociales', 'OA12', 'Conocer cómo viven otros niños en diferentes partes del mundo por medio de imágenes y relatos, ubicando en un globo terráqueo o mapamundi los países donde habitan y comparando su idioma, vestimenta, comida, fiestas, costumbres y principales tareas con las de niños chilenos.'),
  ('1° Básico', 'Historia, Geografía y Cs. Sociales', 'OA13', 'Mostrar actitudes y realizar acciones concretas en su entorno cercano (familia, escuela y comunidad) que reflejen: · respeto al otro (ejemplos: escuchar atentamente al otro, tratar con cortesía a los demás, etc.) · empatía (ejemplos: ayudar a los demás cuando sea necesario, no discriminar a otros por su aspecto o costumbres, etc.) · responsabilidad (ejemplos: asumir encargos en su casa y en la sala de clases, cuidar sus pertenencias y la de los demás, cuidar los espacios comunes, etc.)'),
  ('1° Básico', 'Historia, Geografía y Cs. Sociales', 'OA14', 'Explicar y aplicar algunas normas para la buena convivencia y para la seguridad y el autocuidado en su familia, en la escuela y en la vía pública.'),
  ('1° Básico', 'Historia, Geografía y Cs. Sociales', 'OA15', 'Identificar la labor que cumplen, en beneficio de la comunidad, instituciones como la escuela, la municipalidad, el hospital o la posta, Carabineros de Chile, y las personas que trabajan en ellas.'),
  ('1° Básico', 'Lenguaje y Comunicación', 'OA1', 'Reconocer que los textos escritos transmiten mensajes y que son escritos por alguien para cumplir un propósito.'),
  ('1° Básico', 'Lenguaje y Comunicación', 'OA2', 'Reconocer que las palabras son unidades de significado separadas por espacios en el texto escrito.'),
  ('1° Básico', 'Lenguaje y Comunicación', 'OA3', 'Identificar los sonidos que componen las palabras (conciencia fonológica), reconociendo, separando y combinando sus fonemas y sílabas.'),
  ('1° Básico', 'Lenguaje y Comunicación', 'OA4', 'Leer palabras aisladas y en contexto, aplicando su conocimiento de la correspondencia letra- sonido en diferentes combinaciones: sílaba directa, indirecta o compleja, y dígrafos rr-ll-ch-qu.'),
  ('1° Básico', 'Lenguaje y Comunicación', 'OA5', 'Leer textos breves en voz alta para adquirir fluidez: · pronunciando cada palabra con precisión, aunque se autocorrijan en algunas ocasiones · respetando el punto seguido y el punto aparte · leyendo palabra a palabra'),
  ('1° Básico', 'Lenguaje y Comunicación', 'OA6', 'Comprender textos, aplicando estrategias de comprensión lectora; por ejemplo: · relacionar la información del texto con sus experiencias y conocimientos · visualizar lo que describe el texto'),
  ('1° Básico', 'Lenguaje y Comunicación', 'OA7', 'Leer independientemente y familiarizarse con un amplio repertorio de literatura para aumentar su conocimiento del mundo y desarrollar su imaginación; por ejemplo: · poemas · historias breves · textos con una estructura predecible'),
  ('1° Básico', 'Lenguaje y Comunicación', 'OA8', 'Demostrar comprensión de narraciones que aborden temas que les sean familiares: · extrayendo información explícita e implícita · respondiendo preguntas simples, oralmente o por escrito, sobre los textos (qué, quién, dónde, cuándo, por qué) · recreando personajes por medio de distintas expresiones artísticas, como títeres, dramatizaciones, dibujos o esculturas · describiendo con sus palabras las ilustraciones del texto y relacionándolas con la historia 1º básico 309 stableciendo relaciones entre el texto y sus propias experiencias mitiendo una opinión sobre un aspecto de la lectura'),
  ('1° Básico', 'Lenguaje y Comunicación', 'OA9', 'Leer habitualmente y disfrutar los mejores poemas de autor y de la tradición oral adecuados a su edad.'),
  ('1° Básico', 'Lenguaje y Comunicación', 'OA10', 'Leer independientemente y comprender textos no literarios escritos con oraciones simples (cartas, notas, instrucciones y artículos informativos) para entretenerse y ampliar su conocimiento del mundo: · extrayendo información explícita e implícita · formulando una opinión sobre algún aspecto de la lectura'),
  ('1° Básico', 'Lenguaje y Comunicación', 'OA11', 'Desarrollar el gusto por la lectura, explorando libros y sus ilustraciones.'),
  ('1° Básico', 'Lenguaje y Comunicación', 'OA12', 'Asistir habitualmente a la biblioteca para elegir, escuchar, leer y explorar textos de su interés.'),
  ('1° Básico', 'Lenguaje y Comunicación', 'OA13', 'Experimentar con la escritura para comunicar hechos, ideas y sentimientos, entre otros.'),
  ('1° Básico', 'Lenguaje y Comunicación', 'OA14', 'Escribir oraciones completas para transmitir mensajes.'),
  ('1° Básico', 'Lenguaje y Comunicación', 'OA15', 'Escribir con letra clara, separando las palabras con un espacio para que puedan ser leídas por otros con facilidad.'),
  ('1° Básico', 'Lenguaje y Comunicación', 'OA16', 'Incorporar de manera pertinente en la escritura el vocabulario nuevo extraído de textos escuchados o leídos.'),
  ('1° Básico', 'Lenguaje y Comunicación', 'OA17', 'Comprender y disfrutar versiones completas de obras de la literatura, narradas o leídas por un adulto, como: · cuentos folclóricos y de autor · poemas · fábulas · leyendas'),
  ('1° Básico', 'Lenguaje y Comunicación', 'OA18', 'Comprender textos orales (explicaciones, instrucciones, relatos, anécdotas, etc.) para obtener información y desarrollar su curiosidad por el mundo: · estableciendo conexiones con sus propias experiencias · visualizando lo que se describe en el texto · formulando preguntas para obtener información adicional y aclarar dudas · respondiendo preguntas abiertas · formulando una opinión sobre lo escuchado'),
  ('1° Básico', 'Lenguaje y Comunicación', 'OA19', 'Desarrollar la curiosidad por las palabras o expresiones que desconocen y adquirir el hábito de averiguar su significado.'),
  ('1° Básico', 'Lenguaje y Comunicación', 'OA20', 'Disfrutar de la experiencia de asistir a obras de teatro infantiles o representaciones para ampliar sus posibilidades de expresión, desarrollar su creatividad y familiarizarse con el género.'),
  ('1° Básico', 'Lenguaje y Comunicación', 'OA21', 'Participar activamente en conversaciones grupales sobre textos leídos o escuchados en clases o temas de su interés: · expresando sus ideas u opiniones · demostrando interés ante lo escuchado · respetando turnos'),
  ('1° Básico', 'Lenguaje y Comunicación', 'OA22', 'Interactuar de acuerdo con las convenciones sociales en diferentes situaciones: · presentarse a sí mismo y a otros · saludar · preguntar · expresar opiniones, sentimientos e ideas · situaciones que requieren el uso de fórmulas de cortesía, como por favor, gracias, perdón, permiso'),
  ('1° Básico', 'Lenguaje y Comunicación', 'OA23', 'Expresarse de manera coherente y articulada sobre temas de su interés: · presentando información o narrando un evento relacionado con el tema · incorporando frases descriptivas que ilustren lo dicho · utilizando un vocabulario variado · pronunciando adecuadamente y usando un volumen audible · manteniendo una postura adecuada'),
  ('1° Básico', 'Lenguaje y Comunicación', 'OA24', 'Incorporar de manera pertinente en sus intervenciones orales el vocabulario nuevo extraído de textos escuchados o leídos.'),
  ('1° Básico', 'Lenguaje y Comunicación', 'OA25', 'Desempeñar diferentes roles para desarrollar su lenguaje y autoestima, y aprender a trabajar en equipo.'),
  ('1° Básico', 'Lenguaje y Comunicación', 'OA26', 'Recitar con entonación y expresión poemas, rimas, canciones, trabalenguas y adivinanzas para fortalecer la confianza en sí mismos, aumentar el vocabulario y desarrollar su capacidad expresiva.'),
  ('1° Básico', 'Matemática', 'OA1', 'Contar números del 0 al 100 de 1 en 1, de 2 en 2, de 5 en 5 y de 10 en 10, hacia adelante y hacia atrás, empezando por cualquier número menor que 100.'),
  ('1° Básico', 'Matemática', 'OA2', 'Identificar el orden de los elementos de una serie, utilizando números ordinales del primero (1º) al décimo (10º).'),
  ('1° Básico', 'Matemática', 'OA3', 'Leer números del 0 al 20 y representarlos en forma concreta, pictórica y simbólica.'),
  ('1° Básico', 'Matemática', 'OA4', 'Comparar y ordenar números del 0 al 20 de menor a mayor y/o viceversa, utilizando material concreto y/o usando software educativo.'),
  ('1° Básico', 'Matemática', 'OA5', 'Estimar cantidades hasta 20 en situaciones concretas, usando un referente.'),
  ('1° Básico', 'Matemática', 'OA6', 'Componer y descomponer números del 0 a 20 de manera aditiva, en forma concreta, pictórica y simbólica.'),
  ('1° Básico', 'Matemática', 'OA7', 'Describir y aplicar estrategias de cálculo mental para las adiciones y las sustracciones hasta 20: · conteo hacia adelante y atrás · completar 10 · dobles'),
  ('1° Básico', 'Matemática', 'OA8', 'Determinar las unidades y decenas en números del 0 al 20, agrupando de a 10, de manera concreta, pictórica y simbólica.'),
  ('1° Básico', 'Matemática', 'OA9', 'Demostrar que comprenden la adición y la sustracción de números del 0 al 20 progresivamente, de 0 a 5, de 6 a 10, de 11 a 20 con dos sumandos: · usando un lenguaje cotidiano para describir acciones desde su propia experencia · representando adiciones y sustracciones con material concreto y pictórico, de manera manual y/o usando software educativo · representando el proceso en forma simbólica · resolviendo problemas en contextos familiares · creando problemas matemáticos y resolviéndolos'),
  ('1° Básico', 'Matemática', 'OA10', 'Demostrar que la adición y la sustracción son operaciones inversas, de manera concreta, pictórica y simbólica.'),
  ('1° Básico', 'Matemática', 'OA11', 'Reconocer, describir, crear y continuar patrones repetitivos (sonidos, figuras, ritmos...) y patrones numéricos hasta el 20, crecientes y decrecientes, usando material concreto, pictórico y simbólico, de manera manual y/o por medio de software educativo.'),
  ('1° Básico', 'Matemática', 'OA12', 'Describir y registrar la igualdad y la desigualdad como equilibrio y desequilibrio, usando una balanza en forma concreta, pictórica y simbólica del 0 al 20, usando el símbolo igual (=).'),
  ('1° Básico', 'Matemática', 'OA13', 'Describir la posición de objetos y personas con relación a sí mismos y a otros objetos y personas, usando un lenguaje común (como derecha e izquierda).'),
  ('1° Básico', 'Matemática', 'OA14', 'Identificar en el entorno figuras 3D y figuras 2D y relacionarlas, usando material concreto.'),
  ('1° Básico', 'Matemática', 'OA15', 'Identificar y dibujar líneas rectas y curvas.'),
  ('1° Básico', 'Matemática', 'OA16', 'Usar unidades no estandarizadas de tiempo para comparar la duración de eventos cotidianos.'),
  ('1° Básico', 'Matemática', 'OA17', 'Usar un lenguaje cotidiano para secuenciar eventos en el tiempo: días de la semana, meses del año y algunas fechas significativas.'),
  ('1° Básico', 'Matemática', 'OA18', 'Identificar y comparar la longitud de objetos, usando palabras como largo y corto.'),
  ('1° Básico', 'Matemática', 'OA19', 'Recolectar y registrar datos para responder preguntas estadísticas sobre sí mismo y el entorno, usando bloques, tablas de conteo y pictogramas.'),
  ('1° Básico', 'Matemática', 'OA20', 'Construir, leer e interpretar pictogramas.'),
  ('1° Básico', 'Música', 'OA1', 'Escuchar cualidades del sonido (altura, timbre, intensidad, duración) y elementos del lenguaje musical (pulsos, acentos, patrones, secciones), y representarlos de distintas formas.'),
  ('1° Básico', 'Música', 'OA2', 'Expresar sensaciones, emociones e ideas que les sugieren el sonido y la música escuchada, usando diversos medios expresivos (verbal, corporal, musical, visual).'),
  ('1° Básico', 'Música', 'OA3', 'Escuchar música en forma abundante de diversos contextos y culturas, poniendo énfasis en: · Tradición escrita (docta) - piezas instrumentales y vocales de corta duración (por ejemplo, piezas del Álbum para la juventud de R. Schumann, piezas de Juguetería de P. Bisquert) · Tradición oral (folclor, música de pueblos originarios) - canciones, rondas, bailes y versos rítmicos · Popular (jazz, rock, fusión, etc.) - música infantil (por ejemplo canciones como El Negro Cirilo y videos como Los Gorrioncitos de Tikitiklip). (Escuchar apreciativamente al menos 20 músicas variadas de corta duración.)'),
  ('1° Básico', 'Música', 'OA4', 'Cantar al unísono y tocar instrumentos de percusión convencionales y no convencionales.'),
  ('1° Básico', 'Música', 'OA5', 'Explorar e improvisar ideas musicales con diversos medios sonoros (la voz, instrumentos convencionales y no convencionales, entre otros), usando las cualidades del sonido y elementos del lenguaje musical.'),
  ('1° Básico', 'Música', 'OA6', 'Presentar su trabajo musical, en forma individual y grupal, compartiendo con el curso y la comunidad.'),
  ('1° Básico', 'Música', 'OA7', 'Identificar y describir experiencias musicales y sonoras en su propia vida.'),
  ('1° Básico', 'Orientación', 'OA1', 'Observar, describir y valorar sus características personales, sus habilidades e intereses.'),
  ('1° Básico', 'Orientación', 'OA2', 'Identificar emociones experimentadas por ellos y por los demás (por ejemplo, pena, rabia, miedo, alegría) y distinguir diversas formas de expresarlas.'),
  ('1° Básico', 'Orientación', 'OA3', 'Observar, describir y valorar las expresiones de afecto y cariño, que dan y reciben, en los ámbitos familiar, escolar y social (por ejemplo, compartir tiempo, escuchar a los demás, dar y recibir ayuda).'),
  ('1° Básico', 'Orientación', 'OA4', 'Identificar y practicar, en forma guiada, conductas protectoras y de autocuidado en relación a: · rutinas de higiene · actividades de descanso, recreación y actividad física · hábitos de alimentación · resguardo del cuerpo y la intimidad · la entrega de información personal'),
  ('1° Básico', 'Orientación', 'OA5', 'Manifestar actitudes de solidaridad y respeto, que favorezcan la convivencia, como: · utilizar formas de buen trato (por ejemplo, saludar, despedirse, pedir por favor) · actuar en forma respetuosa (por ejemplo, escuchar, respetar turnos, rutinas y pertenencias) · compartir con los pares (por ejemplo, jugar juntos, prestarse útiles, ayudar al que lo necesita)'),
  ('1° Básico', 'Orientación', 'OA6', 'Identificar conflictos que surgen entre pares y practicar formas de solucionarlos como escuchar al otro, ponerse en su lugar, buscar un acuerdo, reconciliarse.'),
  ('1° Básico', 'Orientación', 'OA7', 'Reconocer, describir y valorar sus grupos de pertenencia (familia, curso, pares), las personas que los componen y sus características y participar activamente en ellos (por ejemplo, ayudando en el orden de la casa y sala de clases).'),
  ('1° Básico', 'Orientación', 'OA8', 'Practicar hábitos y actitudes que favorezcan el proceso de aprendizaje, como: · traer y cuidar los útiles escolares · mantener el orden de la sala de clases y materiales · identificar los nuevos aprendizajes adquiridos para incentivar la motivación'),
  ('1° Básico', 'Tecnología', 'OA1', 'Crear diseños de objetos tecnológicos, representando sus ideas a través de dibujos a mano alzada o modelos concretos, desde sus propias experiencias y tópicos de otras asignaturas, con orientación del profesor.'),
  ('1° Básico', 'Tecnología', 'OA2', 'Distinguir las tareas para elaborar un objeto tecnológico, identificando los materiales y las herramientas necesarias en cada una de ellas para lograr el resultado deseado.'),
  ('1° Básico', 'Tecnología', 'OA3', 'Elaborar un objeto tecnológico según las indicaciones del profesor, seleccionando y experimentando con: · técnicas y herramientas para medir, cortar, plegar, unir, pegar, pintar, entre otras · materiales como papeles, fibras, plásticos, desechos, entre otros'),
  ('1° Básico', 'Tecnología', 'OA4', 'Probar y explicar los resultados de los trabajos propios y de otros, de forma individual o en equipos, dialogando sobre sus ideas e identificando lo que podría hacerse de otra manera. dibujo para crear y representar ideas por medio de imágenes, docente. r una variedad de software educativos (simuladores, libros digitaos y creativos, entre otros) para lograr aprendizajes significativos y una interacción apropiada con las TIC.'),
  ('2° Básico', 'Artes Visuales', 'OA1', 'Expresar y crear trabajos de arte a partir de la observación del: entorno natural: figura humana y paisajes chilenos · entorno cultural: personas y patrimonio cultural de Chile · entorno artístico: obras de arte local, chileno, latinoamericano y del resto del mundo'),
  ('2° Básico', 'Artes Visuales', 'OA2', 'Experimentar y aplicar elementos de lenguaje visual (incluidos los del nivel anterior) en sus trabajos de arte: · línea (vertical, horizontal, diagonal, espiral y quebrada) · color (primarios y secundarios) · formas (geométricas)'),
  ('2° Básico', 'Artes Visuales', 'OA3', 'Expresar emociones e ideas en sus trabajos de arte, a partir de la experimentación con: · materiales de modelado, de reciclaje, naturales, papeles, cartones, pegamentos, lápices, pinturas, textiles e imágenes digitales · herramientas para dibujar, pintar, cortar, modelar, unir y tecnológicas (pincel, tijera, mirete, computador, entre otras) · procedimientos de dibujo, pintura, collage, escultura, dibujo digital, entre otros'),
  ('2° Básico', 'Artes Visuales', 'OA4', 'Comunicar y explicar sus impresiones de lo que sienten y piensan de obras de arte por variados medios. (Observar anualmente al menos 10 obras de arte local o chileno, 10 latinoamericanas y 10 de arte universal).'),
  ('2° Básico', 'Artes Visuales', 'OA5', 'Explicar sus preferencias frente al trabajo de arte personal y de sus pares, usando elementos del lenguaje visual.'),
  ('2° Básico', 'Ciencias Naturales', 'OA1', 'Observar, describir y clasificar los vertebrados en mamíferos, aves, reptiles, anfibios y peces, a partir de características como cubierta corporal, presencia de mamas y estructuras para la respiración, entre otras.'),
  ('2° Básico', 'Ciencias Naturales', 'OA2', 'Observar, describir y clasificar, por medio de la exploración, las características de los animales sin columna vertebral, como insectos, arácnidos, crustáceos, entre otros, y compararlos con los vertebrados.'),
  ('2° Básico', 'Ciencias Naturales', 'OA3', 'Observar y comparar las características de las etapas del ciclo de vida de distintos animales (mamíferos, aves, insectos y anfibios), relacionándolas con su hábitat.'),
  ('2° Básico', 'Ciencias Naturales', 'OA4', 'Observar y comparar las características de distintos hábitat, identificando la luminosidad, la humedad y la temperatura necesarias para la supervivencia de los animales que habitan en él.'),
  ('2° Básico', 'Ciencias Naturales', 'OA5', 'Observar e identificar algunos animales nativos que se encuentran en peligro de extinción, así como el deterioro de su hábitat, proponiendo medidas para protegerlos.'),
  ('2° Básico', 'Ciencias Naturales', 'OA6', 'Identificar y comunicar los efectos de la actividad humana sobre los animales y su hábitat. C uer p o h u m an o y s alud'),
  ('2° Básico', 'Ciencias Naturales', 'OA7', 'Identificar la ubicación y explicar la función de algunas partes del cuerpo que son fundamentales para vivir: corazón, pulmones, estómago, esqueleto y músculos.'),
  ('2° Básico', 'Ciencias Naturales', 'OA8', 'Explicar la importancia de la actividad física para el desarrollo de los músculos y el fortalecimiento del corazón, proponiendo formas de ejercitarla e incorporarla en sus hábitos diarios.'),
  ('2° Básico', 'Ciencias Naturales', 'OA9', 'Observar y describir, por medio de la investigación experimental, algunas características del agua, como: · escurrir · adaptarse a la forma del recipiente · disolver algunos sólidos, como el azúcar y la sal nsparente e inodora rse y congelarse con los cambios de temperatura'),
  ('2° Básico', 'Ciencias Naturales', 'OA10', 'Identificar y comparar, por medio de la exploración, los estados sólido, líquido y gaseoso del agua.'),
  ('2° Básico', 'Ciencias Naturales', 'OA11', 'Describir el ciclo del agua en la naturaleza, reconociendo que el agua es un recurso preciado y proponiendo acciones cotidianas para su cuidado.'),
  ('2° Básico', 'Ciencias Naturales', 'OA12', 'Reconocer y describir algunas características del tiempo atmosférico, como precipitaciones (lluvia, granizo, nieve), viento y temperatura ambiente, entre otras, y sus cambios a lo largo del año.'),
  ('2° Básico', 'Ciencias Naturales', 'OA13', 'Medir algunas características del tiempo atmosférico, construyendo y/o usando algunos instrumentos tecnológicos útiles para su localidad, como termómetro, pluviómetro o veleta.'),
  ('2° Básico', 'Ciencias Naturales', 'OA14', 'Describir la relación de los cambios del tiempo atmosférico con las estaciones del año y sus efectos sobre los seres vivos y el ambiente.'),
  ('2° Básico', 'Educación Física', 'OA1', 'Demostrar habilidades motrices básicas de locomoción, manipulación y estabilidad en diferentes direcciones, alturas y niveles, como saltar de forma continua en un pie y luego en el otro, botear un balón mientras camina, mantener el equilibrio sobre una base a una pequeña altura, realizar suspensiones, giros y rodadas o volteos.'),
  ('2° Básico', 'Educación Física', 'OA2', 'Ejecutar acciones motrices que presenten una solución a un problema, por ejemplo, agrupaciones, representaciones de símbolos, letras, números o figuras geométricas.'),
  ('2° Básico', 'Educación Física', 'OA3', 'Practicar una amplia gama de juegos con y sin oposición, con y sin colaboración, de persecución, individuales y colectivos.'),
  ('2° Básico', 'Educación Física', 'OA4', 'Ejecutar habilidades motrices básicas en diferentes entornos, como plazas activas, patio del colegio, playa, entre otros, utilizando referencias (rutas, mapas, símbolos, etc.) guiados por el profesor.'),
  ('2° Básico', 'Educación Física', 'OA5', 'Ejecutar movimientos corporales, expresando sensaciones, ideas, estados de ánimo y emociones en variados espacios y a diferentes ritmos e intensidades.'),
  ('2° Básico', 'Educación Física', 'OA6', 'Ejecutar actividades físicas de intensidad moderada a vigorosa que incrementen la condición física por medio de juegos y circuitos.'),
  ('2° Básico', 'Educación Física', 'OA7', 'Ejecutar e incorporar a su vida cotidiana juegos y actividades físicas de intensidad moderada a vigorosa (cinco veces por semana), como juegos tradicionales, saltar la cuerda y realizar caminatas al aire libre.'),
  ('2° Básico', 'Educación Física', 'OA8', 'Describir las sensaciones y respuestas corporales provocadas por la práctica de actividad física, como cambios del color de la piel, sudor, agitación, ritmo de respiración, cansancio y dificultad al hablar.'),
  ('2° Básico', 'Educación Física', 'OA9', 'Practicar actividades físicas en forma segura, demostrando la adquisición de hábitos de higiene, posturales y de vida saludable, como lavarse las manos y la cara después de la clase, mantener una correcta postura y comer una colación saludable antes y luego de la práctica de actividad física.'),
  ('2° Básico', 'Educación Física', 'OA10', 'Practicar juegos o actividades motrices para aprender a trabajar en equipo, asumiendo diferentes roles (respetar al otro, recoger los materiales solicitados o liderar si se le asigna ese rol).'),
  ('2° Básico', 'Educación Física', 'OA11', 'Practicar actividades físicas, demostrando comportamientos seguros, como: · realizar un calentamiento mediante un juego · escuchar y seguir instrucciones · utilizar implementos bajo supervisión · mantener su posición dentro de los límites establecidos para la actividad'),
  ('2° Básico', 'Historia, Geografía y Cs. Sociales', 'OA1', 'Describir los modos de vida de algunos pueblos originarios de Chile en el período precolombino, incluyendo ubicación geográfica, medio natural en que habitaban, vida nómade o sedentaria, roles de hombres y mujeres, herramientas y tecnología, principales actividades, vivienda, costumbres, idioma, creencias, alimentación y fiestas, entre otros.'),
  ('2° Básico', 'Historia, Geografía y Cs. Sociales', 'OA2', 'Comparar el modo de vida y expresiones culturales de pueblos indígenas presentes en Chile actual (como mapuche, aimara, rapa nui) con respecto al periodo precolombino, identificando aspectos de su cultura que se han mantenido hasta el presente y aspectos que han cambiado.'),
  ('2° Básico', 'Historia, Geografía y Cs. Sociales', 'OA3', 'Distinguir los diversos aportes a la sociedad chilena proveniente de los pueblos originarios (palabras, alimentos, tradiciones, cultura, etc.) y de los españoles (idioma, religión, alimentos, cultura, etc.) y reconocer nuestra sociedad como mestiza.'),
  ('2° Básico', 'Historia, Geografía y Cs. Sociales', 'OA4', 'Reconocer y dar ejemplos de la influencia y los aportes de inmigrantes de distintas naciones europeas, orientales, árabes y latinoamericanas a la diversidad de la sociedad chilena, a lo largo de su historia.'),
  ('2° Básico', 'Historia, Geografía y Cs. Sociales', 'OA5', 'Reconocer diversas expresiones del patrimonio cultural del país y de su región, como manifestaciones artísticas, tradiciones folclóricas, leyendas y tradiciones orales, costumbres familiares, creencias, idioma, construcciones, comidas típicas, fiestas, monumentos y sitios históricos.'),
  ('2° Básico', 'Historia, Geografía y Cs. Sociales', 'OA6', 'Leer y dibujar planos simples de su entorno, utilizando puntos de referencia, categorías de posición relativa y simbología pictórica.'),
  ('2° Básico', 'Historia, Geografía y Cs. Sociales', 'OA7', 'Ubicar Chile, Santiago, la propia región y su capital en el globo terráqueo o en mapas, y describir la ubicación relativa de países limítrofes y de otros países de América del Sur, utilizando los puntos cardinales.'),
  ('2° Básico', 'Historia, Geografía y Cs. Sociales', 'OA8', 'Clasificar y caracterizar algunos paisajes de Chile según su ubicación en la zona norte, centro y sur del país, observando imágenes, y utilizando diversas fuentes y un vocabulario geográfico adecuado (océano, río, cordillera de los Andes y de la Costa, desierto, valle, costa, volcán, archipiélago, isla, fiordo, lago, ciudad y pueblo, entre otros).'),
  ('2° Básico', 'Historia, Geografía y Cs. Sociales', 'OA9', 'Reconocer diversas expresiones del patrimonio natural de Chile y de su región, como paisajes, flora y fauna característica, y parques nacionales, entre otros.'),
  ('2° Básico', 'Historia, Geografía y Cs. Sociales', 'OA10', 'Ubicar en mapas las zonas habitadas por algunos pueblos originarios de Chile, distinguiendo zonas norte, centro y sur.'),
  ('2° Básico', 'Historia, Geografía y Cs. Sociales', 'OA11', 'Relacionar las principales características geográficas (disponibilidad de agua, temperatura y vegetación) de las zonas habitadas por algunos pueblos originarios de Chile, con los recursos que utilizaron para satisfacer sus necesidades de alimentación, abrigo y vivienda.'),
  ('2° Básico', 'Historia, Geografía y Cs. Sociales', 'OA12', 'Mostrar actitudes y realizar acciones concretas en su entorno cercano (familia, escuela y comunidad) que reflejen: · respeto al otro (interactuar con cortesía, cuidar espacios comunes, respetar la propiedad de los demás, etc.) · responsabilidad (ejemplos: cumplir con sus deberes escolares, asumir encargos en el hogar y dentro de la sala de clases, etc.) · tolerancia (ejemplos: respetar opiniones diversas, no discriminar a otros por su aspecto o costumbres, etc.) · empatía (ejemplos: integrar a los demás en sus juegos y actividades, ayudar a los otros, etc.)'),
  ('2° Básico', 'Historia, Geografía y Cs. Sociales', 'OA13', 'Mantener una conducta honesta en la vida cotidiana, en los juegos y en el trabajo escolar, hablando con la verdad, respetando las reglas de los juegos sin hacer trampa y reconociendo sus errores y sus acciones, entre otros.'),
  ('2° Básico', 'Historia, Geografía y Cs. Sociales', 'OA14', 'Conocer, proponer, aplicar y explicar la importancia de algunas normas necesarias para: · cuidarse, cuidar a otros y evitar situaciones de riesgo (como seguridad vial, vías de evacuación, adaptaciones para discapacitados, zonas de silencio, etc.) · organizar un ambiente propicio al aprendizaje y acogedor para todos (por ejemplo, respetar los turnos, cuidar el espacio y las pertenencias comunes y de sus pares, etc.) · cuidar el patrimonio y el medioambiente'),
  ('2° Básico', 'Historia, Geografía y Cs. Sociales', 'OA15', 'Identificar la labor que cumplen en beneficio de la comunidad servicios como los medios de transporte y de comunicación y el mercado, y algunas instituciones encargadas de proteger nuestro patrimonio cultural y natural.'),
  ('2° Básico', 'Historia, Geografía y Cs. Sociales', 'OA16', 'Practicar y proponer acciones para cuidar y respetar los espacios públicos dentro y fuera de la escuela (como baños, patios, salas de clase, plazas, parques, playas y calles, entre otros), reconociendo que pertenecen y benefician a todos y que, por lo tanto, su cuidado es responsabilidad de todos los miembros de la comunidad.'),
  ('2° Básico', 'Lenguaje y Comunicación', 'OA1', 'Leer textos significativos que incluyan palabras con hiatos y diptongos, con grupos consonánticos y con combinación ce-ci, que-qui, ge-gi, gue-gui, güegüi.'),
  ('2° Básico', 'Lenguaje y Comunicación', 'OA2', 'Leer en voz alta para adquirir fluidez: · pronunciando cada palabra con precisión, aunque se autocorrijan en contadas ocasiones · respetando el punto seguido y el punto aparte · sin detenerse en cada palabra'),
  ('2° Básico', 'Lenguaje y Comunicación', 'OA3', 'Comprender textos, aplicando estrategias de comprensión lectora; por ejemplo: · relacionar la información del texto con sus experiencias y conocimientos · visualizar lo que describe el texto · hacer preguntas mientras se lee'),
  ('2° Básico', 'Lenguaje y Comunicación', 'OA4', 'Leer independientemente y familiarizarse con un amplio repertorio de literatura para aumentar su conocimiento del mundo y desarrollar su imaginación; por ejemplo: · poemas · cuentos folclóricos y de autor · fábulas · leyendas · otros'),
  ('2° Básico', 'Lenguaje y Comunicación', 'OA5', 'Demostrar comprensión de las narraciones leídas: · extrayendo información explícita e implícita · reconstruyendo la secuencia de las acciones en la historia · identificando y describiendo las características físicas y los sentimientos de los distintos personajes · recreando, por medio de distintas expresiones (dibujos, modelos tridimensionales u otras), el ambiente en el que ocurre la acción · estableciendo relaciones entre el texto y sus propias experiencias · emitiendo una opinión sobre un aspecto de la lectura'),
  ('2° Básico', 'Lenguaje y Comunicación', 'OA6', 'Leer habitualmente y disfrutar los mejores poemas de autor y de la tradición oral adecuados a su edad. 2º básico 313'),
  ('2° Básico', 'Lenguaje y Comunicación', 'OA7', 'Leer independientemente y comprender textos no literarios (cartas, notas, instrucciones y artículos informativos) para entretenerse y ampliar su conocimiento del mundo: · extrayendo información explícita e implícita · comprendiendo la información que aportan las ilustraciones y los símbolos a un texto · formulando una opinión sobre algún aspecto de la lectura'),
  ('2° Básico', 'Lenguaje y Comunicación', 'OA8', 'Desarrollar el gusto por la lectura, leyendo habitualmente diversos textos.'),
  ('2° Básico', 'Lenguaje y Comunicación', 'OA9', 'Asistir habitualmente a la biblioteca para encontrar información y elegir libros, cuidando el material en favor del uso común.'),
  ('2° Básico', 'Lenguaje y Comunicación', 'OA10', 'Buscar información sobre un tema en una fuente dada por el docente (página de internet, sección del diario, capítulo de un libro, etc.), para llevar a cabo una investigación.'),
  ('2° Básico', 'Lenguaje y Comunicación', 'OA11', 'Desarrollar la curiosidad por las palabras o expresiones que desconocen y adquirir el hábito de averiguar su significado.'),
  ('2° Básico', 'Lenguaje y Comunicación', 'OA12', 'Escribir frecuentemente, para desarrollar la creatividad y expresar sus ideas, textos como poemas, diarios de vida, anécdotas, cartas, recados, etc.'),
  ('2° Básico', 'Lenguaje y Comunicación', 'OA13', 'Escribir creativamente narraciones (experiencias personales, relatos de hechos, cuentos, etc.) que tengan inicio, desarrollo y desenlace.'),
  ('2° Básico', 'Lenguaje y Comunicación', 'OA14', 'Escribir artículos informativos para comunicar información sobre un tema.'),
  ('2° Básico', 'Lenguaje y Comunicación', 'OA15', 'Escribir con letra clara, separando las palabras con un espacio para que puedan ser leídas por otros con facilidad.'),
  ('2° Básico', 'Lenguaje y Comunicación', 'OA16', 'Planificar la escritura, generando ideas a partir de: · observación de imágenes · conversaciones con sus pares o el docente sobre experiencias personales y otros temas'),
  ('2° Básico', 'Lenguaje y Comunicación', 'OA17', 'Escribir, revisar y editar sus textos para satisfacer un propósito y transmitir sus ideas con claridad. Durante este proceso: · organizan las ideas en oraciones que comienzan con mayúscula y terminan con punto · utilizan un vocabulario variado · mejoran la redacción del texto a partir de sugerencias de los pares y el docente · corrigen la concordancia de género y número, la ortografía y la presentación'),
  ('2° Básico', 'Lenguaje y Comunicación', 'OA18', 'Incorporar de manera pertinente en la escritura el vocabulario nuevo extraído de textos escuchados o leídos.'),
  ('2° Básico', 'Lenguaje y Comunicación', 'OA19', 'Comprender la función de los artículos, sustantivos y adjetivos en textos orales y escritos, y reemplazarlos o combinarlos de diversas maneras para enriquecer o precisar sus producciones.'),
  ('2° Básico', 'Lenguaje y Comunicación', 'OA20', 'Identificar el género y el número de las palabras para asegurar la concordancia en sus escritos.'),
  ('2° Básico', 'Lenguaje y Comunicación', 'OA21', 'Escribir correctamente para facilitar la comprensión por parte del lector, usando de manera apropiada: · combinaciones ce-ci, que-qui, ge-gi, gue-gui, güe-güi · r-rr-nr · mayúsculas al iniciar una oración y al escribir sustantivos propios · punto al finalizar una oración · signos de interrogación y exclamación al inicio y al final de preguntas y exclamaciones'),
  ('2° Básico', 'Lenguaje y Comunicación', 'OA22', 'Comprender y disfrutar versiones completas de obras de la literatura, narradas o leídas por un adulto, como: · cuentos folclóricos y de autor · poemas · fábulas · leyendas'),
  ('2° Básico', 'Lenguaje y Comunicación', 'OA23', 'Comprender textos orales (explicaciones, instrucciones, relatos, anécdotas, etc.) para obtener información y desarrollar su curiosidad por el mundo: · estableciendo conexiones con sus propias experiencias · identificando el propósito · formulando preguntas para obtener información adicional y aclarar dudas · respondiendo preguntas sobre información explícita e implícita · formulando una opinión sobre lo escuchado icación 2º básico 315'),
  ('2° Básico', 'Lenguaje y Comunicación', 'OA24', 'Disfrutar de la experiencia de asistir a obras de teatro infantiles o representaciones para ampliar sus posibilidades de expresión, desarrollar su creatividad y familiarizarse con el género.'),
  ('2° Básico', 'Lenguaje y Comunicación', 'OA25', 'Participar activamente en conversaciones grupales sobre textos leídos o escuchados en clases o temas de su interés: · manteniendo el foco de la conversación · expresando sus ideas u opiniones · formulando preguntas para aclarar dudas · demostrando interés ante lo escuchado · mostrando empatía frente a situaciones expresadas por otros · respetando turnos'),
  ('2° Básico', 'Lenguaje y Comunicación', 'OA26', 'Interactuar de acuerdo con las convenciones sociales en diferentes situaciones: · presentarse a sí mismo y a otros · saludar · preguntar · expresar opiniones, sentimientos e ideas · situaciones que requieren el uso de fórmulas de cortesía, como por favor, gracias, perdón, permiso'),
  ('2° Básico', 'Lenguaje y Comunicación', 'OA27', 'Expresarse de manera coherente y articulada sobre temas de su interés: · presentando información o narrando un evento relacionado con el tema · incorporando frases descriptivas que ilustren lo dicho · utilizando un vocabulario variado · pronunciando adecuadamente y usando un volumen audible · manteniendo una postura adecuada'),
  ('2° Básico', 'Lenguaje y Comunicación', 'OA28', 'Incorporar de manera pertinente en sus intervenciones orales el vocabulario nuevo extraído de textos escuchados o leídos.'),
  ('2° Básico', 'Lenguaje y Comunicación', 'OA29', 'Desempeñar diferentes roles para desarrollar su lenguaje y autoestima, y aprender a trabajar en equipo.'),
  ('2° Básico', 'Lenguaje y Comunicación', 'OA30', 'Recitar con entonación y expresión poemas, rimas, canciones, trabalenguas y adivinanzas para fortalecer la confianza en sí mismos, aumentar el vocabulario y desarrollar su capacidad expresiva.'),
  ('2° Básico', 'Matemática', 'OA1', 'Contar números del 0 al 1 000 de 2 en 2, de 5 en 5, de 10 en 10 y de 100 en 100, hacia adelante y hacia atrás, empezando por cualquier número menor que 1 000.'),
  ('2° Básico', 'Matemática', 'OA2', 'Leer números del 0 al 100 y representarlos en forma concreta, pictórica y simbólica.'),
  ('2° Básico', 'Matemática', 'OA3', 'Comparar y ordenar números del 0 al 100 de menor a mayor y viceversa, usando material concreto y monedas nacionales de manera manual y/o por medio de software educativo.'),
  ('2° Básico', 'Matemática', 'OA4', 'Estimar cantidades hasta 100 en situaciones concretas, usando un referente.'),
  ('2° Básico', 'Matemática', 'OA5', 'Componer y descomponer números del 0 a 100 de manera aditiva, en forma concreta, pictórica y simbólica.'),
  ('2° Básico', 'Matemática', 'OA6', 'Describir y aplicar estrategias de cálculo mental para adiciones y sustracciones hasta 20: · completar 10 · usar dobles y mitades · “uno más uno menos” · “dos más dos menos” · usar la reversibilidad de las operaciones'),
  ('2° Básico', 'Matemática', 'OA7', 'Identificar las unidades y decenas en números del 0 al 100, representando las cantidades de acuerdo a su valor posicional, con material concreto, pictórico y simbólico.'),
  ('2° Básico', 'Matemática', 'OA8', 'Demostrar y explicar de manera concreta, pictórica y simbólica el efecto de sumar y restar 0 a un número.'),
  ('2° Básico', 'Matemática', 'OA9', 'Demostrar que comprende la adición y la sustracción en el ámbito del 0 al 100: · usando un lenguaje cotidiano y matemático para describir acciones desde su propia experiencia · resolviendo problemas con una variedad de representaciones concretas y pictóricas, de manera manual y/o usando software educativo · registrando el proceso en forma simbólica · aplicando los resultados de las adiciones y las sustracciones de los números del 0 a 20 sin realizar cálculos · aplicando el algoritmo de la adición y la sustracción sin considerar reserva · creando problemas matemáticos en contextos familiares y resolviéndolos'),
  ('2° Básico', 'Matemática', 'OA10', 'Demostrar que comprende la relación entre la adición y la sustracción al usar la “familia de operaciones” en cálculos aritméticos y la resolución de problemas'),
  ('2° Básico', 'Matemática', 'OA11', 'Demostrar que comprende la multiplicación: usando representaciones concretas y pictóricas · expresando una multiplicación como una adición de sumandos iguales · usando la distributividad como estrategia para construir las tablas del 2, del 5 y · del 10 resolviendo problemas que involucren las tablas del 2, del 5 y del 10. ú'),
  ('2° Básico', 'Matemática', 'OA12', 'Crear, representar y continuar una variedad de patrones numéricos y completar los elementos faltantes, de manera manual y/o usando software educativo.'),
  ('2° Básico', 'Matemática', 'OA13', 'Demostrar, explicar y registrar la igualdad y la desigualdad en forma concreta y pictórica del 0 al 20, usando el símbolo igual (=) y los símbolos no igual (>, <).'),
  ('2° Básico', 'Matemática', 'OA14', 'Representar y describir la posición de objetos y personas con relación a sí mismos y a otros objetos y personas, incluyendo derecha e izquierda y usando material concreto y dibujos.'),
  ('2° Básico', 'Matemática', 'OA15', 'Describir, comparar y construir figuras 2D (triángulos, cuadrados, rectángulos y círculos) con material concreto.'),
  ('2° Básico', 'Matemática', 'OA16', 'Describir, comparar y construir figuras 3D (cubos, paralelepípedos, esferas y conos) con diversos materiales.'),
  ('2° Básico', 'Matemática', 'OA17', 'Identificar días, semanas, meses y fechas en el calendario.'),
  ('2° Básico', 'Matemática', 'OA18', 'Leer horas y medias horas en relojes digitales, en el contexto de la resolución de problemas.'),
  ('2° Básico', 'Matemática', 'OA19', 'Determinar la longitud de objetos, usando unidades de medidas no estandarizadas y unidades estandarizadas (cm y m), en el contexto de la resolución de problemas.'),
  ('2° Básico', 'Matemática', 'OA20', 'Recolectar y registrar datos para responder preguntas estadísticas sobre juegos 21 con monedas y dados, usando bloques y tablas de conteo y pictogramas. Registrar en tablas y gráficos de barra simple, resultados de juegos aleatorios con dados y monedas.'),
  ('2° Básico', 'Matemática', 'OA22', 'Construir, leer e interpretar pictogramas con escala y gráficos de barra simple.'),
  ('2° Básico', 'Música', 'OA1', 'Escuchar cualidades del sonido (altura, timbre, intensidad, duración) y elementos del lenguaje musical (pulsos, acentos, patrones, secciones), y representarlos de distintas formas.'),
  ('2° Básico', 'Música', 'OA2', 'Expresar sensaciones, emociones e ideas que les sugieren el sonido y la música escuchada, usando diversos medios expresivos (verbal, corporal, musical, visual).'),
  ('2° Básico', 'Música', 'OA3', 'Escuchar música en forma abundante de diversos contextos y culturas, poniendo énfasis en: · Tradición escrita (docta) - piezas instrumentales y /o vocales de corta duración (por ejemplo, danzas medievales, selección del Cuaderno de A.M. Bach, selección del ballet Cascanueces de P.I. Tchaikowsky) · Tradición oral (folclor, música de pueblos originarios) - canciones, rondas, bailes y versos rítmicos · Popular (jazz, rock, fusión, etc.) - música infantil (por ejemplo, canciones como La Elefanta Fresia y música de películas como El Libro de la Selva y El Rey León) (Escuchar apreciativamente al menos 20 músicas variadas de corta duración).'),
  ('2° Básico', 'Música', 'OA4', 'Cantar al unísono y tocar instrumentos de percusión convencionales y no convencionales.'),
  ('2° Básico', 'Música', 'OA5', 'Explorar e improvisar ideas musicales con diversos medios sonoros (la voz, instrumentos convencionales y no convencionales, entre otros), usando las cualidades del sonido y elementos del lenguaje musical.'),
  ('2° Básico', 'Música', 'OA6', 'Presentar su trabajo musical, en forma individual y grupal, compartiendo con el curso y la comunidad.'),
  ('2° Básico', 'Música', 'OA7', 'Identificar y describir experiencias musicales y sonoras en su propia vida.'),
  ('2° Básico', 'Orientación', 'OA1', 'Observar, describir y valorar sus características personales, sus habilidades e intereses.'),
  ('2° Básico', 'Orientación', 'OA2', 'Identificar emociones experimentadas por ellos y por los demás (por ejemplo, pena, rabia, miedo, alegría) y distinguir diversas formas de expresarlas.'),
  ('2° Básico', 'Orientación', 'OA3', 'Observar, describir y valorar las expresiones de afecto y cariño, que dan y reciben, en los ámbitos familiar, escolar y social (por ejemplo, compartir tiempo, escuchar a los demás, dar y recibir ayuda).'),
  ('2° Básico', 'Orientación', 'OA4', 'Identificar y practicar, en forma guiada, conductas protectoras y de autocuidado en relación a: · rutinas de higiene · actividades de descanso, recreación y actividad física · hábitos de alimentación · resguardo del cuerpo y la intimidad · la entrega de información personal'),
  ('2° Básico', 'Orientación', 'OA5', 'Manifestar actitudes de solidaridad y respeto, que favorezcan la convivencia, como: · utilizar formas de buen trato (por ejemplo, saludar, despedirse, pedir por favor) · actuar en forma respetuosa (por ejemplo, escuchar, respetar turnos, rutinas y pertenencias) · compartir con los pares (por ejemplo, jugar juntos, prestarse útiles, ayudar al que lo necesita)'),
  ('2° Básico', 'Orientación', 'OA6', 'Identificar conflictos que surgen entre pares y practicar formas de solucionarlos como escuchar al otro, ponerse en su lugar, buscar un acuerdo, reconciliarse.'),
  ('2° Básico', 'Orientación', 'OA7', 'Reconocer, describir y valorar sus grupos de pertenencia (familia, curso, pares), las personas que los componen y sus características y participar activamente en ellos (por ejemplo, ayudando en el orden de la casa y sala de clases).'),
  ('2° Básico', 'Orientación', 'OA8', 'Practicar hábitos y actitudes que favorezcan el proceso de aprendizaje, como: · traer y cuidar los útiles escolares · mantener el orden de la sala de clases y materiales · identificar los nuevos aprendizajes adquiridos para incentivar la motivación'),
  ('2° Básico', 'Tecnología', 'OA1', 'Crear diseños de objetos tecnológicos, representando sus ideas a través de dibujos a mano alzada o modelos concretos, desde ámbitos cercanos y tópicos de otras asignaturas, con orientación del profesor.'),
  ('2° Básico', 'Tecnología', 'OA2', 'Organizar las tareas para elaborar un objeto tecnológico, distinguiendo las acciones, los materiales y las herramientas necesarias para lograr el resultado deseado.'),
  ('2° Básico', 'Tecnología', 'OA3', 'Elaborar un objeto tecnológico según las indicaciones del profesor, seleccionando y experimentando con: · técnicas y herramientas para medir, cortar, plegar, unir, pegar, pintar, entre otras · materiales como papeles, fibras, plásticos, desechos, entre otros'),
  ('2° Básico', 'Tecnología', 'OA4', 'Probar y explicar los resultados de los trabajos propios y de otros, de forma individual o en equipos, dialogando sobre sus ideas y señalando cómo podría mejorar el trabajo en el futuro. dibujo para crear y representar diferentes ideas por medio de de textos para crear, editar y guardar información.'),
  ('2° Básico', 'Tecnología', 'OA7', 'Usar internet para acceder y extraer información siguiendo las indicaciones del profesor y considerando la seguridad de la fuente.'),
  ('3° Básico', 'Artes Visuales', 'OA1', 'Crear trabajos de arte con un propósito expresivo personal y basados en la observación del: · entorno natural: animales, plantas y fenómenos naturales · entorno cultural: creencias de distintas culturas (mitos, seres imaginarios, dioses, fiestas, tradiciones, otros) · entorno artístico: arte de la Antigüedad y movimientos artísticos como fauvismo, expresionismo y art nouveau'),
  ('3° Básico', 'Artes Visuales', 'OA2', 'Aplicar elementos del lenguaje visual (incluidos los de niveles anteriores) en sus trabajos de arte, con diversos propósitos expresivos y creativos: · color (frío, cálido y expresivo) · textura (en plano y volumen) · forma (real y recreada'),
  ('3° Básico', 'Artes Visuales', 'OA3', 'Crear trabajos de arte a partir de experiencias, intereses y temas del entorno natural y artístico, demostrando manejo de: · materiales de modelado, de reciclaje, naturales, papeles, cartones, pegamentos, lápices, pinturas, textiles e imágenes digitales · herramientas para dibujar, pintar, cortar, modelar, unir y tecnológicas (pincel, tijera, mirete, computador, cámara fotográfica, entre otras) · procedimientos de dibujo, pintura, grabado, escultura, técnicas mixtas, artesanía, fotografía, entre otros'),
  ('3° Básico', 'Artes Visuales', 'OA4', 'Describir sus observaciones de obras de arte y objetos, usando elementos del lenguaje visual y expresando lo que sienten y piensan. (Observar anualmente al menos 15 obras de arte y artesanía local y chilena, 15 latinoamericanas y 15 de arte universal).'),
  ('3° Básico', 'Artes Visuales', 'OA5', 'Describir fortalezas y aspectos a mejorar en el trabajo de arte personal y de sus pares, usando criterios de uso de materiales, procedimientos técnicos y propósito expresivo.'),
  ('3° Básico', 'Ciencias Naturales', 'OA1', 'Observar y describir, por medio de la investigación experimental, las necesidades de las plantas y su relación con la raíz, el tallo y las hojas.'),
  ('3° Básico', 'Ciencias Naturales', 'OA2', 'Observar, registrar e identificar variadas plantas de nuestro país, incluyendo vegetales autóctonos y cultivos principales a nivel nacional y regional.'),
  ('3° Básico', 'Ciencias Naturales', 'OA3', 'Observar y describir algunos cambios de las plantas con flor durante su ciclo de vida (germinación, crecimiento, reproducción, formación de la flor y del fruto), reconociendo la importancia de la polinización y de la dispersión de la semilla.'),
  ('3° Básico', 'Ciencias Naturales', 'OA4', 'Describir la importancia de las plantas para los seres vivos, el ser humano y el medioambiente (por ejemplo: alimentación, aire para respirar, productos derivados, ornamentación, uso medicinal), proponiendo y comunicando medidas de cuidado.'),
  ('3° Básico', 'Ciencias Naturales', 'OA5', 'Explicar la importancia de usar adecuadamente los recursos, proponiendo acciones y construyendo instrumentos tecnológicos para reutilizarlos, reducirlos y reciclarlos en la casa y en la escuela. C uer p o h u m an o y s alud'),
  ('3° Básico', 'Ciencias Naturales', 'OA6', 'Clasificar los alimentos, distinguiendo sus efectos sobre la salud, y proponer hábitos alimenticios saludables.'),
  ('3° Básico', 'Ciencias Naturales', 'OA7', 'Proponer, comunicar y ejercitar buenas prácticas de higiene en la manipulación de alimentos para prevenir enfermedades.'),
  ('3° Básico', 'Ciencias Naturales', 'OA8', 'Distinguir fuentes naturales y artificiales de luz, como el Sol, las ampolletas y el fuego, entre otras.'),
  ('3° Básico', 'Ciencias Naturales', 'OA9', 'Investigar experimentalmente y explicar algunas características de la luz; por ejemplo: viaja en línea recta, se refleja, puede ser separada en colores.'),
  ('3° Básico', 'Ciencias Naturales', 'OA10', 'Investigar experimentalmente y explicar las características del sonido; por ejemplo: viaja en todas las direcciones, se absorbe o se refleja, se transmite por medio de distintos materiales, tiene tono e intensidad.'),
  ('3° Básico', 'Ciencias Naturales', 'OA11', 'Describir las características de algunos de los componentes del Sistema Solar (Sol, planetas, lunas, cometas y asteroides) en relación con su tamaño, localización, apariencia y distancia relativa a la Tierra, entre otros.'),
  ('3° Básico', 'Ciencias Naturales', 'OA12', 'Explicar, por medio de modelos, los movimientos de rotación y traslación, considerando sus efectos en la Tierra.'),
  ('3° Básico', 'Ciencias Naturales', 'OA13', 'Diseñar y construir modelos tecnológicos para explicar eventos del Sistema Solar, como la sucesión de las fases de la Luna y los eclipses de Luna y de Sol, entre otros.'),
  ('3° Básico', 'Educación Física', 'OA1', 'Demostrar capacidad para ejecutar de forma combinada las habilidades motrices básicas de locomoción, manipulación y estabilidad en diferentes direcciones, alturas y niveles, como correr y lanzar un objeto con una mano, caminar sobre una línea y realizar un giro de 180° en un pie.'),
  ('3° Básico', 'Educación Física', 'OA2', 'Ejecutar acciones motrices que presenten una solución a un problema, reconociendo diversos criterios (tiempo, espacio y números de personas), por ejemplo, juegos de uno contra uno, juegos en grupos reducidos y juegos con superioridad numérica.'),
  ('3° Básico', 'Educación Física', 'OA3', 'Practicar juegos pre-deportivos con reglas y espacios adaptados, aplicando los principios generales de juego, como avanzar y retroceder en bloque, recuperar el balón, acompañar la jugada y la visión periférica.'),
  ('3° Básico', 'Educación Física', 'OA4', 'Ejecutar actividades físicas y/o lúdicas en diferentes entornos, aplicando medidas para conservar limpios y ordenados los espacios, por ejemplo: · jugar en plazas activas · jugar un partido en la plaza o la playa · realizar caminatas en el entorno natural · andar en bicicleta en un parque o en un camino rural'),
  ('3° Básico', 'Educación Física', 'OA5', 'Ejecutar movimientos o elementos de danzas tradicionales de forma coordinada, utilizando actividades rítmicas y lúdicas de forma individual o grupal.'),
  ('3° Básico', 'Educación Física', 'OA6', 'Ejecutar actividades físicas de intensidad moderada a vigorosa que desarrollen la condición física por medio de la práctica de ejercicios de resistencia cardiovascular, fuerza, flexibilidad y velocidad, mejorando sus resultados personales.'),
  ('3° Básico', 'Educación Física', 'OA7', 'Practicar de manera regular y autónoma actividades físicas de intensidad moderada a vigorosa, como saltar la cuerda y caminar hasta el colegio.'),
  ('3° Básico', 'Educación Física', 'OA8', 'Describir y registrar las respuestas corporales provocadas por la práctica de actividad física, como aumento de la frecuencia cardiaca y respiratoria.'),
  ('3° Básico', 'Educación Física', 'OA9', 'Practicar actividades físicas en forma segura, demostrando la adquisición de hábitos de higiene, posturales y de vida saludable, como utilizar protección solar, lavarse y cambiarse de ropa después de la clase, hidratarse con agua, comer una colación saludable después de la práctica de actividad física.'),
  ('3° Básico', 'Educación Física', 'OA10', 'Practicar actividades físicas y /o juegos colectivos con responsabilidad y honestidad, cumpliendo las reglas, los roles asignados y los principios de un juego limpio.'),
  ('3° Básico', 'Educación Física', 'OA11', 'Practicar actividades físicas, demostrando comportamientos seguros, como: · participar en actividades de calentamiento en forma apropiada · escuchar y seguir instrucciones · mantener su posición dentro de los límites establecidos para la actividad · asegurar que el espacio está libre de obstáculos'),
  ('3° Básico', 'Historia, Geografía y Cs. Sociales', 'OA1', 'Reconocer aspectos de la vida cotidiana de la civilización griega de la Antigüedad e identificar algunos elementos de su legado a sociedades y culturas del presente; entre ellos, la organización democrática, el desarrollo de la historia, el teatro como forma de expresión, el arte y la escultura, la arquitectura, la mitología, la geometría y la filosofía, la creación del alfabeto y los juegos olímpicos.'),
  ('3° Básico', 'Historia, Geografía y Cs. Sociales', 'OA2', 'Reconocer aspectos de la vida cotidiana de la civilización romana de la Antigüedad e identificar algunos elementos de su legado a sociedades y culturas del presente; entre ellos, el idioma, el derecho y las leyes, el arte y las obras arquitectónicas.'),
  ('3° Básico', 'Historia, Geografía y Cs. Sociales', 'OA3', 'Explicar, con ejemplos concretos, cómo diferentes culturas y pueblos (como griegos y romanos de la Antigüedad) han enfrentado de distintas maneras el desafío de desarrollarse y satisfacer las necesidades comunes a todos los seres humanos.'),
  ('3° Básico', 'Historia, Geografía y Cs. Sociales', 'OA4', 'Comparar modos de vida de la Antigüedad con el propio, considerando costumbres, trabajos y oficios, creencias, vestimentas y características de las ciudades, entre otros.'),
  ('3° Básico', 'Historia, Geografía y Cs. Sociales', 'OA5', 'Investigar sobre algún tema de su interés con relación a las civilizaciones estudiadas (como los héroes, los dioses, las ciudades, las viviendas, la vestimenta, las herramientas tecnológicas y la esclavitud, entre otros) por medio de diferentes fuentes (libros, fuentes gráficas, TICs) y comunicar lo aprendido.'),
  ('3° Básico', 'Historia, Geografía y Cs. Sociales', 'OA6', 'Ubicar personas, lugares y elementos en una cuadrícula, utilizando líneas de referencia y puntos cardinales.'),
  ('3° Básico', 'Historia, Geografía y Cs. Sociales', 'OA7', 'Distinguir hemisferios, círculo del Ecuador, trópicos, polos, continentes y océanos del planeta en mapas y globos terráqueos.'),
  ('3° Básico', 'Historia, Geografía y Cs. Sociales', 'OA8', 'Identificar y ubicar en mapas las principales zonas climáticas del mundo, y dar ejemplos de distintos paisajes que pueden encontrarse en estas zonas y de cómo las personas han elaborado diferentes estrategias para habitarlos.'),
  ('3° Básico', 'Historia, Geografía y Cs. Sociales', 'OA9', 'Caracterizar el entorno geográfico de las civilizaciones estudiadas, utilizando vocabulario geográfico adecuado (continente, valle, montaña, océano, río, archipiélago, mares, península, ciudad, construcciones y monumentos, entre otros).'),
  ('3° Básico', 'Historia, Geografía y Cs. Sociales', 'OA10', 'Reconocer algunos factores geográficos que influyeron en el desarrollo de las civilizaciones estudiadas (ubicación, relieve y clima, recursos naturales disponibles, importancia del mar Egeo y sus islas para Grecia e importancia del mar Mediterráneo para Roma, entre otros).'),
  ('3° Básico', 'Historia, Geografía y Cs. Sociales', 'OA11', 'Asumir sus deberes y responsabilidades como estudiante y en situaciones de la vida cotidiana, como cumplir con sus deberes escolares, colaborar en el orden y en la limpieza de los espacios que comparte con su familia, escuela y comunidad, cuidar sus pertenencias y las de los demás, preocuparse de su salud e higiene y ayudar en su casa.'),
  ('3° Básico', 'Historia, Geografía y Cs. Sociales', 'OA12', 'Mostrar actitudes y realizar acciones concretas en su entorno cercano (familia, escuela y comunidad) que reflejen valores y virtudes ciudadanas, como: · la tolerancia y el respeto al otro (ejemplos: respetar las opiniones distintas a las propias, mostrar disposición al diálogo, respetar expresiones de diversidad, como diferentes costumbres, creencias, origen étnico, nacionalidad, etc.) · la empatía (ejemplos: demostrar cortesía con los demás, escuchar al otro, ayudar a quien lo necesite, etc.)'),
  ('3° Básico', 'Historia, Geografía y Cs. Sociales', 'OA13', 'Mantener una conducta honesta en la vida cotidiana, en los juegos y en el trabajo escolar, hablando con la verdad, respetando las reglas de los juegos sin hacer trampa y reconociendo sus errores y sus acciones, entre otros.'),
  ('3° Básico', 'Historia, Geografía y Cs. Sociales', 'OA14', 'Reconocer que los niños tienen derechos que les permiten recibir un cuidado especial por parte de la sociedad con el fin de que puedan aprender, crecer y desarrollarse, y dar ejemplos de cómo la sociedad les garantiza estos derechos.'),
  ('3° Básico', 'Historia, Geografía y Cs. Sociales', 'OA15', 'Investigar y comunicar sus resultados sobre algunas instituciones públicas y privadas (como Junaeb, Sernac, SII, Banco Estado, instituciones de previsión y salud, universidades, Hogar de Cristo y fundaciones, entre otras), identificando el servicio que prestan en la comunidad y los diferentes trabajos que realizan las personas que se desempeñan en ellas.'),
  ('3° Básico', 'Historia, Geografía y Cs. Sociales', 'OA16', 'Participar responsable y activamente en su hogar (encargos, celebraciones, cuidado de las cosas) y en la escuela (campañas solidarias, celebraciones, deportes y juegos), cumpliendo compromisos y responsabilidades adquiridos.'),
  ('3° Básico', 'Lenguaje y Comunicación', 'OA1', 'Leer en voz alta de manera fluida variados textos apropiados a su edad: · pronunciando cada palabra con precisión · respetando la coma, el punto y los signos de exclamación e interrogación · leyendo con velocidad adecuada para el nivel'),
  ('3° Básico', 'Lenguaje y Comunicación', 'OA2', 'Comprender textos, aplicando estrategias de comprensión lectora; por ejemplo: · relacionar la información del texto con sus experiencias y conocimientos · releer lo que no fue comprendido · visualizar lo que describe el texto · recapitular · formular preguntas sobre lo leído y responderlas · subrayar información relevante en un texto'),
  ('3° Básico', 'Lenguaje y Comunicación', 'OA3', 'Leer y familiarizarse con un amplio repertorio de literatura para aumentar su conocimiento del mundo y desarrollar su imaginación; por ejemplo: · poemas · cuentos folclóricos y de autor · fábulas · leyendas · mitos · novelas · historietas · otros'),
  ('3° Básico', 'Lenguaje y Comunicación', 'OA4', 'Profundizar su comprensión de las narraciones leídas: · extrayendo información explícita e implícita · reconstruyendo la secuencia de las acciones en la historia · describiendo a los personajes · describiendo el ambiente en que ocurre la acción · expresando opiniones fundamentadas sobre hechos y situaciones del texto · emitiendo una opinión sobre los personajes'),
  ('3° Básico', 'Lenguaje y Comunicación', 'OA5', 'Comprender poemas adecuados al nivel e interpretar el lenguaje figurado presente en ellos. 3º básico 319'),
  ('3° Básico', 'Lenguaje y Comunicación', 'OA6', 'Leer independientemente y comprender textos no literarios (cartas, biografías, relatos históricos, instrucciones, libros y artículos informativos, noticias, etc.) para ampliar su conocimiento del mundo y formarse una opinión: · extrayendo información explícita e implícita · utilizando los organizadores de textos expositivos (títulos, subtítulos, índice y glosario) para encontrar información específica · comprendiendo la información que aportan las ilustraciones, los símbolos y los pictogramas a un texto · formulando una opinión sobre algún aspecto de la lectura · fundamentando su opinión con información del texto o sus conocimientos previos'),
  ('3° Básico', 'Lenguaje y Comunicación', 'OA7', 'Desarrollar el gusto por la lectura, leyendo habitualmente diversos textos.'),
  ('3° Básico', 'Lenguaje y Comunicación', 'OA8', 'Asistir habitualmente a la biblioteca para satisfacer diversos propósitos (encontrar información, elegir libros, estudiar o trabajar), cuidando el material en favor del uso común.'),
  ('3° Básico', 'Lenguaje y Comunicación', 'OA9', 'Buscar información sobre un tema en libros, internet, diarios, revistas, enciclopedias, atlas, etc., para llevar a cabo una investigación.'),
  ('3° Básico', 'Lenguaje y Comunicación', 'OA10', 'Determinar el significado de palabras desconocidas, usando claves contextuales o el conocimiento de raíces (morfemas de base), prefijos y sufijos.'),
  ('3° Básico', 'Lenguaje y Comunicación', 'OA11', 'Determinar el significado de palabras desconocidas, usando el orden alfabético para encontrarlas en un diccionario infantil o ilustrado.'),
  ('3° Básico', 'Lenguaje y Comunicación', 'OA12', 'Escribir frecuentemente, para desarrollar la creatividad y expresar sus ideas, textos como poemas, diarios de vida, cuentos, anécdotas, cartas, comentarios sobre sus lecturas, etc.'),
  ('3° Básico', 'Lenguaje y Comunicación', 'OA13', 'Escribir creativamente narraciones (experiencias personales, relatos de hechos, cuentos, etc.) que incluyan: · una secuencia lógica de eventos · inicio, desarrollo y desenlace · conectores adecuados'),
  ('3° Básico', 'Lenguaje y Comunicación', 'OA14', 'Escribir artículos informativos para comunicar información sobre un tema: · organizando las ideas en párrafos · desarrollando las ideas mediante información que explica el tema'),
  ('3° Básico', 'Lenguaje y Comunicación', 'OA15', 'Escribir cartas, instrucciones, afiches, reportes de una experiencia, entre otros, para lograr diferentes propósitos: · usando un formato adecuado · transmitiendo el mensaje con claridad'),
  ('3° Básico', 'Lenguaje y Comunicación', 'OA16', 'Escribir con letra clara para que pueda ser leída por otros con facilidad.'),
  ('3° Básico', 'Lenguaje y Comunicación', 'OA17', 'Planificar la escritura: · estableciendo propósito y destinatario · generando ideas a partir de conversaciones, investigaciones, lluvia de ideas u otra estrategia'),
  ('3° Básico', 'Lenguaje y Comunicación', 'OA18', 'Escribir, revisar y editar sus textos para satisfacer un propósito y transmitir sus ideas con claridad. Durante este proceso: · organizan las ideas en párrafos separados con punto aparte · utilizan conectores apropiados · utilizan un vocabulario variado · mejoran la redacción del texto a partir de sugerencias de los pares y el docente · corrigen la ortografía y la presentación'),
  ('3° Básico', 'Lenguaje y Comunicación', 'OA19', 'Incorporar de manera pertinente en la escritura el vocabulario nuevo extraído de textos escuchados o leídos.'),
  ('3° Básico', 'Lenguaje y Comunicación', 'OA20', 'Comprender la función de los artículos, sustantivos y adjetivos en textos orales y escritos, y reemplazarlos o combinarlos de diversas maneras para enriquecer o precisar sus producciones.'),
  ('3° Básico', 'Lenguaje y Comunicación', 'OA21', 'Comprender la función de los pronombres en textos orales y escritos, y usarlos para ampliar las posibilidades de referirse a un sustantivo en sus producciones.'),
  ('3° Básico', 'Lenguaje y Comunicación', 'OA22', 'Escribir correctamente para facilitar la comprensión por parte del lector, aplicando lo aprendido en años anteriores y usando de manera apropiada: · mayúsculas al iniciar una oración y al escribir sustantivos propios · punto al finalizar una oración y punto aparte al finalizar un párrafo · plurales de palabras terminadas en z · palabras con ge-gi, je-ji · palabras terminadas en cito-cita · coma en enumeración aje y Comunicación 3º básico 321'),
  ('3° Básico', 'Lenguaje y Comunicación', 'OA23', 'Comprender y disfrutar versiones completas de obras de la literatura, narradas o leídas por un adulto, como: · cuentos folclóricos y de autor · poemas · fábulas · mitos y leyendas'),
  ('3° Básico', 'Lenguaje y Comunicación', 'OA24', 'Comprender textos orales (explicaciones, instrucciones, noticias, documentales, películas, relatos, anécdotas, etc.) para obtener información y desarrollar su curiosidad por el mundo: · estableciendo conexiones con sus propias experiencias · identificando el propósito · formulando preguntas para obtener información adicional, aclarar dudas y profundizar la comprensión · estableciendo relaciones entre distintos textos · respondiendo preguntas sobre información explícita e implícita · formulando una opinión sobre lo escuchado'),
  ('3° Básico', 'Lenguaje y Comunicación', 'OA25', 'Disfrutar de la experiencia de asistir a obras de teatro infantiles o representaciones para ampliar sus posibilidades de expresión, desarrollar su creatividad y familiarizarse con el género.'),
  ('3° Básico', 'Lenguaje y Comunicación', 'OA26', 'Participar activamente en conversaciones grupales sobre textos leídos o escuchados en clases o temas de su interés: · manteniendo el foco de la conversación · expresando sus ideas u opiniones · formulando preguntas para aclarar dudas · demostrando interés ante lo escuchado · mostrando empatía frente a situaciones expresadas por otros · respetando turnos'),
  ('3° Básico', 'Lenguaje y Comunicación', 'OA27', 'Interactuar de acuerdo con las convenciones sociales en diferentes situaciones: · presentarse a sí mismo y a otros · saludar · preguntar · expresar opiniones, sentimientos e ideas · situaciones que requieren el uso de fórmulas de cortesía, como por favor, gracias, perdón, permiso'),
  ('3° Básico', 'Lenguaje y Comunicación', 'OA29', 'Incorporar de manera pertinente en sus intervenciones orales el vocabulario nuevo extraído de textos escuchados o leídos.'),
  ('3° Básico', 'Lenguaje y Comunicación', 'OA30', 'Caracterizar distintos personajes para desarrollar su lenguaje y autoestima, y aprender a trabajar en equipo.'),
  ('3° Básico', 'Lenguaje y Comunicación', 'OA31', 'Recitar poemas con entonación y expresión para fortalecer la confianza en sí mismos, aumentar el vocabulario y desarrollar su capacidad expresiva.'),
  ('3° Básico', 'Matemática', 'OA1', 'Contar números del 0 al 1 000 de 5 en 5, de 10 en 10, de 100 en 100: empezando por cualquier número natural menor que 1.000 · de 3 en 3, de 4 en 4..., empezando por cualquier múltiplo del número correspondiente'),
  ('3° Básico', 'Matemática', 'OA2', 'Leer números hasta 1.000 y representarlos en forma concreta, pictórica y simbólica.'),
  ('3° Básico', 'Matemática', 'OA3', 'Comparar y ordenar números naturales hasta 1.000, utilizando la recta numérica o la tabla posicional de manera manual y/o por medio de software educativo.'),
  ('3° Básico', 'Matemática', 'OA4', 'Describir y aplicar estrategias de cálculo mental para las adiciones y las sustracciones hasta 100: · por descomposición · completar hasta la decena más cercana · usar dobles · sumar en vez de restar · aplicar la asociatividad'),
  ('3° Básico', 'Matemática', 'OA5', 'Identificar y describir las unidades, las decenas y las centenas en números del 0 al 1.000, representando las cantidades de acuerdo a su valor posicional, con material concreto, pictórico y simbólico.'),
  ('3° Básico', 'Matemática', 'OA6', 'Demostrar que comprenden la adición y la sustracción de números del 0 al 1.000: · usando estrategias personales con y sin material concreto · creando y resolviendo problemas de adición y sustracción que involucren operaciones combinadas, en forma concreta, pictórica y simbólica, de manera manual y/o por medio de software educativo · aplicando los algoritmos con y sin reserva, progresivamente, en la adición de hasta cuatro sumandos y en la sustracción de hasta un sustraendo'),
  ('3° Básico', 'Matemática', 'OA7', 'Demostrar que comprenden la relación entre la adición y la sustracción, usando la “familia de operaciones” en cálculos aritméticos y en la resolución de problemas.'),
  ('3° Básico', 'Matemática', 'OA8', 'Demostrar que comprenden las tablas de multiplicar hasta el 10 de manera progresiva: · usando representaciones concretas y pictóricas · expresando una multiplicación como una adición de sumandos iguales · usando la distributividad como estrategia para construir las tablas hasta el 10 ando los resultados de las tablas de multiplicación hasta 10 · 10, sin realizar los viendo problemas que involucren las tablas aprendidas hasta el 10'),
  ('3° Básico', 'Matemática', 'OA9', 'Demostrar que comprenden la división en el contexto de las tablas7 de hasta 10 · 10: · representando y explicando la división como repartición y agrupación en partes iguales, con material concreto y pictórico · creando y resolviendo problemas en contextos que incluyan la repartición y la agrupación · expresando la división como una sustracción repetida · describiendo y aplicando la relación inversa entre la división y la multiplicación · aplicando los resultados de las tablas de multiplicación hasta 10 · 10, sin realizar cálculos'),
  ('3° Básico', 'Matemática', 'OA10', 'Resolver problemas rutinarios en contextos cotidianos, que incluyan dinero e involucren las cuatro operaciones (no combinadas). 1 1 1 2 3'),
  ('3° Básico', 'Matemática', 'OA11', 'Demostrar que comprenden las fracciones de uso común: , , , , : 4 3 2 3 4 · explicando que una fracción representa la parte de un todo8, de manera concreta, pictórica, simbólica, de forma manual y/o con software educativo · describiendo situaciones en las cuales se puede usar fracciones · comparando fracciones de un mismo todo, de igual denominador'),
  ('3° Básico', 'Matemática', 'OA12', 'Generar, describir y registrar patrones numéricos, usando una variedad de estrategias en tablas del 100, de manera manual y/o con software educativo.'),
  ('3° Básico', 'Matemática', 'OA13', 'Resolver ecuaciones de un paso que involucren adiciones y sustracciones y un símbolo geométrico que represente un número desconocido, en forma pictórica y simbólica del 0 al 100.'),
  ('3° Básico', 'Matemática', 'OA14', 'Describir la localización de un objeto en un mapa simple o en una cuadrícula.'),
  ('3° Básico', 'Matemática', 'OA15', 'Demostrar que comprenden la relación que existe entre figuras 3D y figuras 2D: construyendo una figura 3D a partir de una red (plantilla) · desplegando la figura 3D ú'),
  ('3° Básico', 'Matemática', 'OA16', 'Describir cubos, paralelepípedos, esferas, conos, cilindros y pirámides de acuerdo a la forma de sus caras y el número de aristas y vértices.'),
  ('3° Básico', 'Matemática', 'OA17', 'Reconocer en el entorno figuras 2D que están trasladadas, reflejadas y rotadas.'),
  ('3° Básico', 'Matemática', 'OA18', 'Demostrar que comprenden el concepto de ángulo: identificando ejemplos de ángulos en el entorno · estimando la medida de ángulos, usando como referente ángulos de 45º y de 90o · 3º básico 237'),
  ('3° Básico', 'Matemática', 'OA19', 'Leer e interpretar líneas de tiempo y calendarios.'),
  ('3° Básico', 'Matemática', 'OA20', 'Leer y registrar el tiempo en horas, medias horas, cuartos de hora y minutos en relojes análogos y digitales.'),
  ('3° Básico', 'Matemática', 'OA21', 'Demostrar que comprenden el perímetro de una figura regular e irregular: midiendo y registrando el perímetro de figuras del entorno en el contexto de la · resolución de problemas determinando el perímetro de un cuadrado y de un rectángulo ú'),
  ('3° Básico', 'Matemática', 'OA22', 'Demostrar que comprende la medición del peso (g y kg): comparando y ordenando dos o más objetos a partir de su peso de manera informal · usando modelos para explicar la relación que existe entre gramos y kilogramos · estimando el peso de objetos de uso cotidiano, usando referentes · midiendo y registrando el peso de objetos en números y en fracciones de uso · común, en el contexto de la resolución de problemas'),
  ('3° Básico', 'Matemática', 'OA23', 'Realizar encuestas, clasificar y organizar los datos obtenidos en tablas y visualizarlos en gráficos de barra.'),
  ('3° Básico', 'Matemática', 'OA24', 'Registrar y ordenar datos obtenidos de juegos aleatorios con dados y monedas, encontrando el menor, el mayor y estimando el punto medio entre ambos.'),
  ('3° Básico', 'Matemática', 'OA25', 'Construir, leer e interpretar pictogramas y gráficos de barra simple con escala, de acuerdo a información recolectada o dada.'),
  ('3° Básico', 'Matemática', 'OA26', 'Representar datos usando diagramas de puntos.'),
  ('3° Básico', 'Música', 'OA1', 'Escuchar cualidades del sonido (altura, timbre, intensidad, duración) y elementos del lenguaje musical (pulsos, acentos, patrones, reiteraciones, contrastes, variaciones, dinámica, tempo, preguntas-respuestas, secciones, A-AB-BA), y representarlos de distintas formas.'),
  ('3° Básico', 'Música', 'OA2', 'Expresar, mostrando grados crecientes de elaboración, sensaciones, emociones e ideas que les sugiere la música, escuchada, usando diversos medios expresivos (verbal, corporal, musical, visual).'),
  ('3° Básico', 'Música', 'OA3', 'Escuchar música en forma abundante de diversos contextos y culturas, poniendo énfasis en: · Tradición escrita (docta) - música inspirada en raíces folclóricas de Chile y el mundo (por ejemplo, Chile en cuatro cuerdas de G. Soublette, Danzas Eslavas de A. Dvorak) - música descriptiva (por ejemplo, El Carnaval de los Animales de C. Saint- Saens, extractos de La Suite Gran Cañón de F. Gofré) · Tradición oral (folclor, música de pueblos originarios) - canciones, bailes, festividades, tradiciones de Chile y del mundo (por ejemplo, El chuico y la damajuana de V. Parra, música de la Tirana, El Pavo) · Popular (jazz, rock, fusión, etc.) - fusión con raíces folclóricas (por ejemplo, Los Jaivas y Congreso) (Escuchar apreciativamente al menos 20 músicas de corta duración.)'),
  ('3° Básico', 'Música', 'OA4', 'Cantar (al unísono y cánones simples, entre otros) y tocar instrumentos de percusión y melódicos (metalófono, flauta dulce u otros).'),
  ('3° Básico', 'Música', 'OA5', 'Improvisar y crear ideas musicales con diversos medios sonoros con un propósito, utilizando las cualidades del sonido y elementos del lenguaje musical.'),
  ('3° Básico', 'Música', 'OA6', 'Presentar su trabajo musical al curso y la comunidad, en forma individual y grupal, con compromiso y responsabilidad. r y describir experiencias musicales y sonoras en su propia vida y en la celebraciones, reuniones, festividades, situaciones cotidianas u otros).'),
  ('3° Básico', 'Música', 'OA8', 'Reflexionar sobre sus fortalezas y las áreas en que pueden mejorar su audición, su interpretación y su creación.'),
  ('3° Básico', 'Orientación', 'OA1', 'Observar, describir y valorar sus características, habilidades y fortalezas (en lo familiar, afectivo, académico y social, entre otros) y proponerse acciones concretas para los aspectos que requiera superar.'),
  ('3° Básico', 'Orientación', 'OA2', 'Identificar y aceptar sus propias emociones y las de los demás, y practicar estrategias personales de manejo emocional (por ejemplo, esperar un tiempo, escuchar al otro y considerar su impacto en los demás).'),
  ('3° Básico', 'Orientación', 'OA3', 'Reconocer y valorar la sexualidad como expresión de amor, vínculo e intimidad entre dos personas y como gestora de su propia vida.'),
  ('3° Básico', 'Orientación', 'OA4', 'Identificar y practicar, en forma guiada, conductas protectoras y de autocuidado en relación a: · rutinas de higiene · actividades de descanso, recreación y actividad física · hábitos de alimentación · resguardo del cuerpo y la intimidad · la entrega de información personal · situaciones de potencial abuso · consumo de drogas'),
  ('3° Básico', 'Orientación', 'OA5', 'Manifestar actitudes de solidaridad y respeto, que favorezcan la convivencia, como: · actuar en forma empática (poniéndose en el lugar del otro) · utilizar un buen trato (por ejemplo, saludar, despedirse, pedir por favor) · evitar y rechazar toda forma de violencia y discriminación, ya sea por etnia, género, religión, nacionalidad, etc. · respetar el derecho de todos a expresar opiniones y ser diferente · prestar ayuda especialmente a quien lo necesite · respetar el ambiente de aprendizaje'),
  ('3° Básico', 'Orientación', 'OA6', 'Resolver conflictos entre pares en forma guiada y aplicar estrategias diversas de resolución de problemas, tales como escuchar, describir los sentimientos del otro y buscar un acuerdo que satisfaga a ambas partes.'),
  ('3° Básico', 'Orientación', 'OA7', 'Participar en forma guiada en la comunidad escolar y en la organización del curso: · proponiendo y aceptando iniciativas, y asumiendo responsabilidades · respetando los derechos de los demás en la distribución de roles y responsabilidades'),
  ('3° Básico', 'Orientación', 'OA8', 'Manifestar hábitos y actitudes de esfuerzo e interés que favorezcan el aprendizaje, como: · asistir puntualmente a clases y cumplir a tiempo con los trabajos pedidos · organizar su tiempo y sus útiles · respetar el estudio y el trabajo de otros · evitar el plagio y la copia · preguntar y buscar información sobre temas de su interés · desarrollar actividades en relación a sus propios intereses'),
  ('3° Básico', 'Tecnología', 'OA1', 'Crear diseños de objetos o sistemas tecnológicos simples para resolver problemas: · desde diversos ámbitos tecnológicos y tópicos de otras asignaturas · representando sus ideas a través de dibujos a mano alzada, modelos concretos o usando TIC · explorando y combinando productos existentes'),
  ('3° Básico', 'Tecnología', 'OA2', 'Planificar la elaboración de un objeto tecnológico, incorporando la secuencia de acciones, materiales, herramientas, técnicas y medidas de seguridad necesarias para lograr el resultado deseado.'),
  ('3° Básico', 'Tecnología', 'OA3', 'Elaborar un objeto tecnológico para resolver problemas, seleccionando y demostrando dominio de: · técnicas y herramientas para medir, marcar, cortar, plegar, unir, pegar, pintar, entre otras · materiales como papeles, cartones, fibras, plásticos, cerámicos, desechos, entre otros'),
  ('3° Básico', 'Tecnología', 'OA7', 'Usar internet y buscadores para localizar, extraer y almacenar información, considerando la seguridad de la fuente.'),
  ('4° Básico', 'Artes Visuales', 'OA1', 'Crear trabajos de arte con un propósito expresivo personal y basados en la observación del: · entorno natural: naturaleza y paisaje americano · entorno cultural: América y sus tradiciones (cultura precolombina, tradiciones y artesanía americana) · entorno artístico: arte precolombino y de movimientos artísticos como muralismo mexicano, naif y surrealismo en Chile, Latinoamérica y en el resto del mundo'),
  ('4° Básico', 'Artes Visuales', 'OA2', 'Aplicar elementos del lenguaje visual (incluidos los de niveles anteriores) en sus trabajos de arte, con diversos propósitos expresivos y creativos: · líneas de contorno · color (tono y matiz) · forma (figurativa y no figurativa)'),
  ('4° Básico', 'Artes Visuales', 'OA3', 'Crear trabajos de arte a partir de experiencias, intereses y temas del entorno natural, cultural y artístico, demostrando manejo de: · materiales de modelado, de reciclaje, naturales, papeles, cartones, pegamentos, lápices, pinturas, textiles e imágenes digitales · herramientas para dibujar, pintar, cortar, unir, modelar y tecnológicas (pincel, tijera, mirete, computador, cámara fotográfica, entre otras) · procedimientos de dibujo, pintura, grabado, escultura, técnicas mixtas, artesanía, fotografía, entre otros'),
  ('4° Básico', 'Artes Visuales', 'OA4', 'Describir sus observaciones de obras de arte y objetos, usando elementos del lenguaje visual y expresando lo que sienten y piensan. (Observar anualmente al menos 15 obras de arte y artesanía local y chilena, 15 de arte latinoamericano y 15 de arte universal).'),
  ('4° Básico', 'Artes Visuales', 'OA5', 'Describir fortalezas y aspectos a mejorar en el trabajo de arte personal y de sus pares, aplicando criterios de uso de materiales, procedimientos técnicos y propósito expresivo.'),
  ('4° Básico', 'Ciencias Naturales', 'OA1', 'Reconocer, por medio de la exploración, que un ecosistema está compuesto por elementos vivos (animales, plantas, etc.) y no vivos (piedras, agua, tierra, etc.) que interactúan entre sí.'),
  ('4° Básico', 'Ciencias Naturales', 'OA2', 'Observar y comparar adaptaciones de plantas y animales para sobrevivir en los ecosistemas en relación con su estructura y conducta; por ejemplo: cubierta corporal, camuflaje, tipo de hojas, hibernación, entre otras.'),
  ('4° Básico', 'Ciencias Naturales', 'OA3', 'Dar ejemplos de cadenas alimentarias, identificando la función de los organismos productores, consumidores y descomponedores, en diferentes ecosistemas de Chile.'),
  ('4° Básico', 'Ciencias Naturales', 'OA4', 'Analizar los efectos de la actividad humana en ecosistemas de Chile, proponiendo medidas para protegerlos (parques nacionales y vedas, entre otras). C uer p o h u m an o y s alud'),
  ('4° Básico', 'Ciencias Naturales', 'OA5', 'Identificar y describir, usando modelos, estructuras del sistema esquelético y algunas de sus funciones, como protección (costillas y cráneo), soporte (vértebras y columna vertebral) y movimiento (pelvis y fémur).'),
  ('4° Básico', 'Ciencias Naturales', 'OA6', 'Explicar, con apoyo de modelos, el movimiento del cuerpo, considerando la acción coordinada de músculos, huesos, tendones y articulación (ejemplo: brazo y pierna), y describir los beneficios de la actividad física para el sistema músculo-esquelético.'),
  ('4° Básico', 'Ciencias Naturales', 'OA7', 'Identificar estructuras del sistema nervioso y describir algunas de sus funciones, como conducción de información (médula espinal y nervios) y elaboración y control (cerebro).'),
  ('4° Básico', 'Ciencias Naturales', 'OA8', 'Investigar en diversas fuentes y comunicar los efectos que produce el consumo excesivo de alcohol en la salud humana (como descoordinación, confusión y lentitud, entre otras).'),
  ('4° Básico', 'Ciencias Naturales', 'OA9', 'Demostrar, por medio de la investigación experimental, que la materia tiene masa y ocupa espacio, usando materiales del entorno.'),
  ('4° Básico', 'Ciencias Naturales', 'OA10', 'Comparar los tres estados de la materia (sólido, líquido y gaseoso) en relación con criterios como la capacidad de fluir y cambiar de forma y volumen, entre otros.'),
  ('4° Básico', 'Ciencias Naturales', 'OA11', 'Medir la masa, el volumen y la temperatura de la materia (en estados sólido, líquido y gaseoso), utilizando instrumentos y unidades de medida apropiados.'),
  ('4° Básico', 'Ciencias Naturales', 'OA12', 'Demostrar, por medio de la investigación experimental, los efectos de la aplicación de fuerzas sobre objetos, considerando cambios en la forma, la rapidez y la dirección del movimiento, entre otros.'),
  ('4° Básico', 'Ciencias Naturales', 'OA13', 'Identificar, por medio de la investigación experimental, diferentes tipos de fuerzas y sus efectos en situaciones concretas: · fuerza de roce (arrastrando objetos) · peso (fuerza de gravedad) · fuerza magnética (en imanes)'),
  ('4° Básico', 'Ciencias Naturales', 'OA14', 'Diseñar y construir objetos tecnológicos que usen la fuerza, para resolver problemas cotidianos.'),
  ('4° Básico', 'Ciencias Naturales', 'OA15', 'Describir, por medio de modelos, que la Tierra tiene una estructura de capas (corteza, manto y núcleo) con características distintivas en cuanto a su composición, rigidez y temperatura.'),
  ('4° Básico', 'Ciencias Naturales', 'OA16', 'Explicar los cambios de la superficie de la Tierra a partir de la interacción de sus capas y los movimientos de las placas tectónicas (sismos, tsunamis y erupciones volcánicas).'),
  ('4° Básico', 'Ciencias Naturales', 'OA17', 'Proponer medidas de prevención y seguridad ante riesgos naturales en la escuela, la calle y el hogar, para desarrollar una cultura preventiva.'),
  ('4° Básico', 'Educación Física', 'OA1', 'Demostrar control en la ejecución de las habilidades motrices básicas de locomoción, manipulación y estabilidad en diferentes direcciones, alturas y niveles, por ejemplo, atrapar un objeto con una mano a diferentes alturas, desplazarse boteando un objeto en zig-zag y saltar, caminar sobre una base a una pequeña altura y realizar un giro de 360° en un solo pie.'),
  ('4° Básico', 'Educación Física', 'OA2', 'Ejecutar juegos colectivos y crear estrategias con el apoyo del docente para resolver problemas en relación al tiempo, el espacio y el número de personas, por ejemplo, dar cinco pases sin que el equipo rival lo intercepte o sin que el objeto caiga.'),
  ('4° Básico', 'Educación Física', 'OA3', 'Practicar juegos pre-deportivos con reglas y espacios adaptados, aplicando los principios generales de juego, como acoplarse en ataque y replegarse en defensa, utilizar el campo de juego a lo largo y ancho o reconocer el espacio del adversario.'),
  ('4° Básico', 'Educación Física', 'OA4', 'Ejecutar actividades físicas y/o lúdicas en diferentes entornos, aplicando medidas para conservar limpios y ordenados los espacios, como: · jugar en plazas activas · jugar un partido en la plaza o la playa · realizar caminatas en el entorno natural · andar en bicicleta en un parque o en un camino rural'),
  ('4° Básico', 'Educación Física', 'OA5', 'Ejecutar movimientos o elementos de danzas tradicionales de forma coordinada, utilizando actividades rítmicas y lúdicas de forma individual o grupal.'),
  ('4° Básico', 'Educación Física', 'OA6', 'Ejecutar actividades físicas de intensidad moderada a vigorosa que desarrollen la condición física por medio de la práctica de ejercicios de resistencia cardiovascular, fuerza, flexibilidad y velocidad, mejorando sus resultados personales.'),
  ('4° Básico', 'Educación Física', 'OA7', 'Practicar de manera regular y autónoma actividades físicas de intensidad moderada a vigorosa, como saltar la cuerda y caminar hasta el colegio.'),
  ('4° Básico', 'Educación Física', 'OA8', 'Medir y registrar las respuestas corporales provocadas por la actividad física mediante el pulso o utilizando escalas de percepción de esfuerzo.'),
  ('4° Básico', 'Educación Física', 'OA9', 'Practicar actividades físicas en forma segura, demostrando la adquisición de hábitos de higiene, posturales y de vida saludable, como utilizar protección solar, lavarse y cambiarse de ropa después de la clase, hidratarse con agua, comer una colación saludable después de la práctica de actividad física.'),
  ('4° Básico', 'Educación Física', 'OA10', 'Practicar actividades físicas y /o juegos colectivos con responsabilidad y honestidad, cumpliendo las reglas y los roles asignados, respetando las decisiones de la autoridad y organizar equitativamente los equipos.'),
  ('4° Básico', 'Educación Física', 'OA11', 'Practicar actividades físicas, demostrando comportamientos seguros, como: · realizar un calentamiento en forma apropiada · utilizar de manera adecuada los materiales y las instalaciones para evitar el riesgo personal y de otros · escuchar y seguir instrucciones · asegurar que el espacio está libre de obstáculos'),
  ('4° Básico', 'Historia, Geografía y Cs. Sociales', 'OA1', 'Describir la civilización maya, considerando ubicación geográfica, organización política, actividades económicas, formas de cultivo y alimentos, organización de la sociedad, roles y oficios de hombres y mujeres, religión y ritos, desarrollo de la astronomía y la matemática, sistemas de escritura, guerras y sacrificios humanos, construcciones, costumbres y vida cotidiana, entre otros.'),
  ('4° Básico', 'Historia, Geografía y Cs. Sociales', 'OA2', 'Describir la civilización azteca, considerando ubicación geográfica, organización política y extensión, la ciudad de Tenochtitlán, formas de cultivo y alimentos, religión y ritos, avances tecnológicos, organización de la sociedad, roles y oficios de hombres y mujeres, construcciones, costumbres y vida cotidiana, entre otros.'),
  ('4° Básico', 'Historia, Geografía y Cs. Sociales', 'OA3', 'Describir la civilización inca, considerando ubicación geográfica, organización política, sistema de caminos y correos, religión y ritos, avances tecnológicos, organización de la sociedad, roles y oficios de hombres y mujeres, formas de cultivo y alimentos, construcciones, costumbres y vida cotidiana, entre otros.'),
  ('4° Básico', 'Historia, Geografía y Cs. Sociales', 'OA4', 'Analizar y comparar las principales características de las civilizaciones americanas (mayas, aztecas e incas).'),
  ('4° Básico', 'Historia, Geografía y Cs. Sociales', 'OA5', 'Investigar en diversas fuentes (imágenes, medios audiovisuales, TICs, gráficos, textos y otras) sobre algunos temas relacionados con el presente de los pueblos indígenas americanos; por ejemplo, el protagonismo que tienen hoy, la influencia de las civilizaciones maya, azteca e inca sobre la cultura y la sociedad de los países actuales situados donde ellos se desarrollaron, y su influencia en las comidas y en la lengua que empleamos en la actualidad, entre otros.'),
  ('4° Básico', 'Historia, Geografía y Cs. Sociales', 'OA6', 'Ubicar lugares en un mapa, utilizando coordenadas geográficas como referencia (paralelos y meridianos).'),
  ('4° Básico', 'Historia, Geografía y Cs. Sociales', 'OA7', 'Distinguir recursos naturales renovables y no renovables, reconocer el carácter limitado de los recursos naturales y la necesidad de cuidarlos, e identificar recursos presentes en objetos y bienes cotidianos.'),
  ('4° Básico', 'Historia, Geografía y Cs. Sociales', 'OA8', 'Describir distintos paisajes del continente americano, considerando climas, ríos, población, idiomas, países y grandes ciudades, entre otros, y utilizando vocabulario geográfico adecuado.'),
  ('4° Básico', 'Historia, Geografía y Cs. Sociales', 'OA9', 'Reconocer y ubicar los principales recursos naturales de América, considerando su distribución geográfica, su uso, y la importancia de cuidarlos en el marco de un desarrollo sostenible.'),
  ('4° Básico', 'Historia, Geografía y Cs. Sociales', 'OA10', 'Comparar, mediante la observación en imágenes, mapas y otras fuentes, paisajes de su región con paisajes de América, distinguiendo distintas formas de adaptación y transformación de la población a su ambiente natural.'),
  ('4° Básico', 'Historia, Geografía y Cs. Sociales', 'OA11', 'Distinguir algunos actores de la organización política y democrática de Chile, como Presidente, ministros, senadores, diputados y alcaldes, considerando las instituciones en las que ejercen y cómo son nombrados o elegidos.'),
  ('4° Básico', 'Historia, Geografía y Cs. Sociales', 'OA12', 'Reconocer sus principales derechos en situaciones de la vida cotidiana, como el derecho a la educación, a contar con alimentación, vivienda, recreo y servicios médicos adecuados, a expresarse, a ser protegido contra el abandono y la crueldad, y a no trabajar antes de la edad apropiada, y dar ejemplos de cómo se pueden ejercer y proteger esos derechos.'),
  ('4° Básico', 'Historia, Geografía y Cs. Sociales', 'OA13', 'Mantener una conducta honesta en la vida cotidiana, en los juegos y en el trabajo escolar, hablando con la verdad, respetando las reglas de los juegos sin hacer trampa, evitando la copia y el plagio y reconociendo sus errores y sus acciones, entre otros.'),
  ('4° Básico', 'Historia, Geografía y Cs. Sociales', 'OA14', 'Demostrar respeto por todas las personas mediante acciones en su vida diaria, sin discriminar por condiciones físicas, sociales, económicas, étnicas o culturales.'),
  ('4° Básico', 'Historia, Geografía y Cs. Sociales', 'OA15', 'Participar en su comunidad, tomando parte en elecciones para una directiva del curso, asignando roles y funciones a cada cargo, y considerando la importancia de mantener una buena convivencia y una organización del curso que favorezca el trabajo escolar.'),
  ('4° Básico', 'Historia, Geografía y Cs. Sociales', 'OA16', 'Resolver conflictos, aplicando estrategias como determinar la causa del problema, proponer posibles soluciones, dialogar, buscar un punto de vista común y votar, entre otras, demostrando respeto y empatía por las partes involucradas para mejorar la convivencia en el curso y en la comunidad escolar.'),
  ('4° Básico', 'Historia, Geografía y Cs. Sociales', 'OA17', 'Diseñar y participar activamente en un proyecto grupal que solucione un problema de la comunidad escolar; por ejemplo, reciclaje de la basura, exceso de ruido, organización de turnos, leer o entretener a alumnos más pequeños, etc.'),
  ('4° Básico', 'Historia, Geografía y Cs. Sociales', 'OA18', 'Opinar y argumentar con fundamentos sobre temas de la asignatura u otros.'),
  ('4° Básico', 'Lenguaje y Comunicación', 'OA1', 'Leer en voz alta de manera fluida variados textos apropiados a su edad: · pronunciando las palabras con precisión · respetando los signos de puntuación · leyendo con entonación adecuada · leyendo con velocidad adecuada para el nivel'),
  ('4° Básico', 'Lenguaje y Comunicación', 'OA2', 'Comprender textos, aplicando estrategias de comprensión lectora; por ejemplo: · relacionar la información del texto con sus experiencias y conocimientos · releer lo que no fue comprendido · visualizar lo que describe el texto · recapitular · formular preguntas sobre lo leído y responderlas · subrayar información relevante en un texto'),
  ('4° Básico', 'Lenguaje y Comunicación', 'OA3', 'Leer y familiarizarse con un amplio repertorio de literatura para aumentar su conocimiento del mundo y desarrollar su imaginación; por ejemplo: · poemas · cuentos folclóricos y de autor · fábulas · leyendas · mitos · novelas · historietas · otros'),
  ('4° Básico', 'Lenguaje y Comunicación', 'OA4', 'Profundizar su comprensión de las narraciones leídas: · extrayendo información explícita e implícita · determinando las consecuencias de hechos o acciones · describiendo y comparando a los personajes · describiendo los diferentes ambientes que aparecen en un texto · reconociendo el problema y la solución en una narración · expresando opiniones fundamentadas sobre actitudes y acciones de los personajes · comparando diferentes textos escritos por un mismo autor'),
  ('4° Básico', 'Lenguaje y Comunicación', 'OA5', 'Comprender poemas adecuados al nivel e interpretar el lenguaje figurado presente en ellos. 4º básico 325'),
  ('4° Básico', 'Lenguaje y Comunicación', 'OA6', 'Leer independientemente y comprender textos no literarios (cartas, biografías, relatos históricos, instrucciones, libros y artículos informativos, noticias, etc.) para ampliar su conocimiento del mundo y formarse una opinión: · extrayendo información explícita e implícita · utilizando los organizadores de textos expositivos (títulos, subtítulos, índice y glosario) para encontrar información específica · comprendiendo la información entregada por textos discontinuos, como imágenes, gráficos, tablas, mapas o diagramas · interpretando expresiones en lenguaje figurado · comparando información · respondiendo preguntas como ¿por qué sucede?, ¿cuál es la consecuencia de?, ¿qué sucedería si...? · formulando una opinión sobre algún aspecto de la lectura · fundamentando su opinión con información del texto o sus conocimientos previos'),
  ('4° Básico', 'Lenguaje y Comunicación', 'OA7', 'Desarrollar el gusto por la lectura, leyendo habitualmente diversos textos.'),
  ('4° Básico', 'Lenguaje y Comunicación', 'OA8', 'Asistir habitualmente a la biblioteca para satisfacer diversos propósitos (encontrar información, elegir libros, estudiar, trabajar o investigar), cuidando el material en favor del uso común.'),
  ('4° Básico', 'Lenguaje y Comunicación', 'OA9', 'Buscar y clasificar información sobre un tema en internet, libros, diarios, revistas, enciclopedias, atlas, etc., para llevar a cabo una investigación.'),
  ('4° Básico', 'Lenguaje y Comunicación', 'OA10', 'Aplicar estrategias para determinar el significado de palabras nuevas: · claves del texto (para determinar qué acepción es pertinente según el contexto) · raíces y afijos · preguntar a otro · diccionarios, enciclopedias e internet'),
  ('4° Básico', 'Lenguaje y Comunicación', 'OA11', 'Escribir frecuentemente, para desarrollar la creatividad y expresar sus ideas, textos como poemas, diarios de vida, cuentos, anécdotas, cartas, comentarios sobre sus lecturas, noticias, etc.'),
  ('4° Básico', 'Lenguaje y Comunicación', 'OA12', 'Escribir creativamente narraciones (experiencias personales, relatos de hechos, cuentos, etc.) que incluyan: · una secuencia lógica de eventos · inicio, desarrollo y desenlace · conectores adecuados · descripciones · un lenguaje expresivo para desarrollar la acción'),
  ('4° Básico', 'Lenguaje y Comunicación', 'OA13', 'Escribir artículos informativos para comunicar información sobre un tema: · presentando el tema en una oración · desarrollando una idea central por párrafo · utilizando sus propias palabras'),
  ('4° Básico', 'Lenguaje y Comunicación', 'OA14', 'Escribir cartas, instrucciones, afiches, reportes de una experiencia o noticias, entre otros, para lograr diferentes propósitos: · usando un formato adecuado · transmitiendo el mensaje con claridad'),
  ('4° Básico', 'Lenguaje y Comunicación', 'OA15', 'Escribir con letra clara para que pueda ser leída por otros con facilidad.'),
  ('4° Básico', 'Lenguaje y Comunicación', 'OA16', 'Planificar la escritura: · estableciendo propósito y destinatario · generando ideas a partir de conversaciones, investigaciones, lluvia de ideas u otra estrategia'),
  ('4° Básico', 'Lenguaje y Comunicación', 'OA17', 'Escribir, revisar y editar sus textos para satisfacer un propósito y transmitir sus ideas con claridad. Durante este proceso: · organizan las ideas en párrafos separados con punto aparte · utilizan conectores apropiados · emplean un vocabulario preciso y variado · adecuan el registro al propósito del texto y al destinatario · mejoran la redacción del texto a partir de sugerencias de los pares y el docente · corrigen la ortografía y la presentación'),
  ('4° Básico', 'Lenguaje y Comunicación', 'OA18', 'Incorporar de manera pertinente en la escritura el vocabulario nuevo extraído de textos escuchados o leídos.'),
  ('4° Básico', 'Lenguaje y Comunicación', 'OA19', 'Comprender la función de los adverbios en textos orales y escritos, y reemplazarlos o combinarlos para enriquecer o precisar sus producciones.'),
  ('4° Básico', 'Lenguaje y Comunicación', 'OA20', 'Comprender la función de los verbos en textos orales y escritos, y usarlos manteniendo la concordancia con el sujeto.'),
  ('4° Básico', 'Lenguaje y Comunicación', 'OA21', 'Escribir correctamente para facilitar la comprensión por parte del lector, aplicando todas las reglas de ortografía literal y puntual aprendidas en años anteriores, además de: · palabras con b-v · palabras con h de uso frecuente aje y Comunicación 4º básico 327 · escritura de ay, hay, ahí · acentuación de palabras agudas, graves, esdrújulas y sobreesdrújulas'),
  ('4° Básico', 'Lenguaje y Comunicación', 'OA22', 'Comprender y disfrutar versiones completas de obras de la literatura, narradas o leídas por un adulto, como: · cuentos folclóricos y de autor · poemas · mitos y leyendas · capítulos de novelas'),
  ('4° Básico', 'Lenguaje y Comunicación', 'OA23', 'Comprender textos orales (explicaciones, instrucciones, noticias, documentales, películas, testimonios, relatos, etc.) para obtener información y desarrollar su curiosidad por el mundo: · estableciendo conexiones con sus propias experiencias · identificando el propósito · formulando preguntas para obtener información adicional, aclarar dudas y profundizar la comprensión · estableciendo relaciones entre distintos textos · respondiendo preguntas sobre información explícita e implícita · formulando una opinión sobre lo escuchado'),
  ('4° Básico', 'Lenguaje y Comunicación', 'OA24', 'Disfrutar de la experiencia de asistir a obras de teatro infantiles o representaciones para ampliar sus posibilidades de expresión, desarrollar su creatividad y familiarizarse con el género.'),
  ('4° Básico', 'Lenguaje y Comunicación', 'OA25', 'Participar activamente en conversaciones grupales sobre textos leídos o escuchados en clases o temas de su interés: · manteniendo el foco de la conversación · expresando sus ideas u opiniones y fundamentándolas · formulando preguntas para aclarar dudas y verificar la comprensión · demostrando interés ante lo escuchado · mostrando empatía frente a situaciones expresadas por otros · respetando turnos'),
  ('4° Básico', 'Lenguaje y Comunicación', 'OA26', 'Interactuar de acuerdo con las convenciones sociales en diferentes situaciones: · presentarse a sí mismo y a otros · saludar · preguntar · expresar opiniones, sentimientos e ideas · situaciones que requieren el uso de fórmulas de cortesía, como por favor, gracias, perdón, permiso'),
  ('4° Básico', 'Lenguaje y Comunicación', 'OA28', 'Incorporar de manera pertinente en sus intervenciones orales el vocabulario nuevo extraído de textos escuchados o leídos.'),
  ('4° Básico', 'Lenguaje y Comunicación', 'OA29', 'Caracterizar distintos personajes para desarrollar su lenguaje y autoestima, y aprender a trabajar en equipo.'),
  ('4° Básico', 'Lenguaje y Comunicación', 'OA30', 'Recitar poemas con entonación y expresión para fortalecer la confianza en sí mismos, aumentar el vocabulario y desarrollar su capacidad expresiva.'),
  ('4° Básico', 'Matemática', 'OA1', 'Representar y describir números del 0 al 10 000: contándolos de 10 en 10, de 100 en 100, de 1 000 en 1 000 · leyéndolos y escribiéndolos · representándolos en forma concreta, pictórica y simbólica · comparándolos y ordenándolos en la recta numérica o la tabla posicional · identificando el valor posicional de los dígitos hasta la decena de mil · componiendo y descomponiendo números naturales hasta 10 000 en forma aditiva, de acuerdo a su valor posicional'),
  ('4° Básico', 'Matemática', 'OA2', 'Describir y aplicar estrategias de cálculo mental para determinar las multiplicaciones hasta 10 · 10 y sus divisiones correspondientes: · conteo hacia delante y atrás · doblar y dividir por 2 · por descomposición · usar el doble del doble'),
  ('4° Básico', 'Matemática', 'OA3', 'Demostrar que comprenden la adición y la sustracción de números hasta 1 000: · usando estrategias personales para realizar estas operaciones · descomponiendo los números involucrados · estimando sumas y diferencias · resolviendo problemas rutinarios y no rutinarios que incluyan adiciones y sustracciones · aplicando los algoritmos en la adición de hasta cuatro sumandos y en la sustracción de hasta un sustraendo'),
  ('4° Básico', 'Matemática', 'OA4', 'Fundamentar y aplicar las propiedades del 0 y del 1 para la multiplicación y la propiedad del 1 para la división.'),
  ('4° Básico', 'Matemática', 'OA5', 'Demostrar que comprenden la multiplicación de números de tres dígitos por números de un dígito: · usando estrategias con o sin material concreto · utilizando las tablas de multiplicación · estimando productos · usando la propiedad distributiva de la multiplicación respecto de la suma · aplicando el algoritmo de la multiplicación · resolviendo problemas rutinarios'),
  ('4° Básico', 'Matemática', 'OA6', 'Demostrar que comprenden la división con dividendos de dos dígitos y divisores de un dígito: · usando estrategias para dividir, con o sin material concreto · utilizando la relación que existe entre la división y la multiplicación · estimando el cociente · aplicando la estrategia por descomposición del dividendo · aplicando el algoritmo de la división'),
  ('4° Básico', 'Matemática', 'OA7', 'Resolver problemas rutinarios y no rutinarios en contextos cotidianos que incluyen dinero, seleccionando y utilizando la operación apropiada.'),
  ('4° Básico', 'Matemática', 'OA8', 'Demostrar que comprende las fracciones con denominadores 100, 12, 10, 8, 6, 5, 4, 3, 2: · explicando que una fracción representa la parte de un todo o de un grupo de elementos y un lugar en la recta numérica · describiendo situaciones en las cuales se puede usar fracciones · mostrando que una fracción puede tener representaciones diferentes · comparando y ordenando fracciones (por ejemplo: 1 , 1 , 1 , 1 , 1 ) con 100 8 5 4 2 material concreto y pictórico'),
  ('4° Básico', 'Matemática', 'OA9', 'Resolver adiciones y sustracciones de fracciones con igual denominador (denominadores 100, 12, 10, 8, 6, 5, 4, 3, 2) de manera concreta y pictórica en el contexto de la resolución de problemas.'),
  ('4° Básico', 'Matemática', 'OA10', 'Identificar, escribir y representar fracciones propias y los números mixtos hasta el 5 de manera concreta, pictórica y simbólica, en el contexto de la resolución de problemas.'),
  ('4° Básico', 'Matemática', 'OA11', 'Describir y representar decimales (décimos y centésimos): representándolos en forma concreta, pictórica y simbólica, de manera manual · y/o con software educativo comparándolos y ordenándolos hasta la centésima ú'),
  ('4° Básico', 'Matemática', 'OA12', 'Resolver adiciones y sustracciones de decimales, empleando el valor posicional hasta la centésima en el contexto de la resolución de problemas.'),
  ('4° Básico', 'Matemática', 'OA13', 'Identificar y describir patrones numéricos en tablas que involucren una operación, de manera manual y/o usando software educativo.'),
  ('4° Básico', 'Matemática', 'OA14', 'Resolver ecuaciones e inecuaciones de un paso que involucren adiciones y sustracciones, comprobando los resultados en forma pictórica y simbólica del 0 al 100 y aplicando las relaciones inversas entre la adición y la sustracción. 4º básico 243'),
  ('4° Básico', 'Matemática', 'OA15', 'Describir la localización absoluta de un objeto en un mapa simple con coordenadas informales (por ejemplo: con letras y números) y la localización relativa con relación a otros objetos.'),
  ('4° Básico', 'Matemática', 'OA16', 'Determinar las vistas de figuras 3D desde el frente, desde el lado y desde arriba.'),
  ('4° Básico', 'Matemática', 'OA17', 'Demostrar que comprenden una línea de simetría: identificando figuras simétricas 2D · creando figuras simétricas 2D · dibujando una o más líneas de simetría en figuras 2D · usando software geométrico ú'),
  ('4° Básico', 'Matemática', 'OA18', 'Trasladar, rotar y reflejar figuras 2D.'),
  ('4° Básico', 'Matemática', 'OA19', 'Construir ángulos con el transportador y compararlos.'),
  ('4° Básico', 'Matemática', 'OA20', 'Leer y registrar diversas mediciones del tiempo en relojes análogos y digitales, usando los conceptos A.M., P.M. y 24 horas.'),
  ('4° Básico', 'Matemática', 'OA21', 'Realizar conversiones entre unidades de tiempo en el contexto de la resolución de problemas: el número de segundos en un minuto, el número de minutos en una hora, el número de días en un mes y el número de meses en un año.'),
  ('4° Básico', 'Matemática', 'OA22', 'Medir longitudes con unidades estandarizadas (m, cm) y realizar transformaciones entre estas unidades (m a cm y viceversa) en el contexto de la resolución de problemas.'),
  ('4° Básico', 'Matemática', 'OA23', 'Demostrar que comprenden el concepto de área de un rectángulo y de un cuadrado: · reconociendo que el área de una superficie se mide en unidades cuadradas · seleccionando y justificando la elección de la unidad estandarizada (cm2 y m2) · determinando y registrando el área en cm2 y m2 en contextos cercanos · construyendo diferentes rectángulos para un área dada (cm2 y m2), para mostrar que distintos rectángulos pueden tener la misma área · usando software geométrico'),
  ('4° Básico', 'Matemática', 'OA24', 'Demostrar que comprenden el concepto de volumen de un cuerpo: seleccionando una unidad no estandarizada para medir el volumen de un cuerpo · reconociendo que el volumen se mide en unidades de cubo · midiendo y registrando el volumen en unidades de cubo · usando software geométrico ú'),
  ('4° Básico', 'Matemática', 'OA25', 'Realizar encuestas, analizar los datos y comparar con los resultados de muestras aleatorias, usando tablas y gráficos.'),
  ('4° Básico', 'Matemática', 'OA26', 'Realizar experimentos aleatorios lúdicos y cotidianos, y tabular y representar mediante gráficos de manera manual y/o con software educativo.'),
  ('4° Básico', 'Matemática', 'OA27', 'Leer e interpretar pictogramas y gráficos de barra simple con escala y comunicar sus conclusiones.'),
  ('4° Básico', 'Música', 'OA1', 'Escuchar cualidades del sonido (altura, timbre, intensidad, duración) y elementos del lenguaje musical (pulsos, acentos, patrones, reiteraciones, contrastes, variaciones, dinámica, tempo, preguntas-respuestas, secciones, A-AB-ABA), y representarlos de distintas formas.'),
  ('4° Básico', 'Música', 'OA2', 'Expresar, mostrando grados crecientes de elaboración, sensaciones, emociones e ideas que les sugiere la música escuchada, usando diversos medios expresivos (verbal, corporal, musical, visual).'),
  ('4° Básico', 'Música', 'OA3', 'Escuchar música en forma abundante de diversos contextos y culturas, poniendo énfasis en: · Tradición escrita (docta) - música para variadas agrupaciones instrumentales (por ejemplo, Entreacte de J. Ibert, Marcha Turca de L. V. Beethoven, Sinfonía Turangalila de O. Messiaen) - música descriptiva (por ejemplo, El tren de Caipira de H. Villalobos, Cuadros de una Exposición de M. Mussorsky, Los Peces de J. Amenábar) · Tradición oral (folclor, música de pueblos originarios) · Popular (jazz, rock, fusión, etc.) - música de diversas agrupaciones instrumentales (por ejemplo, canciones como El Rock del Mundial, música de películas como The Yellow Submarine, musicales como Jesucristo Superestrella) (Escuchar apreciativamente al menos 20 músicas cariadas de corta duración.)'),
  ('4° Básico', 'Música', 'OA4', 'Cantar (al unísono y cánones simples, entre otros) y tocar instrumentos de percusión y melódicos (metalófono, flauta dulce u otros) y/o armónicos (guitarra, teclado, otros).'),
  ('4° Básico', 'Música', 'OA5', 'Improvisar y crear ideas musicales con diversos medios sonoros con un propósito dado, utilizando las cualidades del sonido y elementos del lenguaje musical.'),
  ('4° Básico', 'Música', 'OA6', 'Presentar su trabajo musical al curso y la comunidad, en forma individual y grupal, con compromiso y responsabilidad. r y describir experiencias musicales y sonoras en su propia vida y en la celebraciones, reuniones, festividades, situaciones cotidianas u otros).'),
  ('4° Básico', 'Música', 'OA8', 'Reflexionar sobre sus fortalezas y las áreas en que pueden mejorar su audición, su interpretación y su creación.'),
  ('4° Básico', 'Orientación', 'OA1', 'Observar, describir y valorar sus características, habilidades y fortalezas (en lo familiar, afectivo, académico y social, entre otros) y proponerse acciones concretas para los aspectos que requiera superar.'),
  ('4° Básico', 'Orientación', 'OA2', 'Identificar y aceptar sus propias emociones y las de los demás y practicar estrategias personales de manejo emocional (por ejemplo, esperar un tiempo, escuchar al otro y considerar su impacto en los demás).'),
  ('4° Básico', 'Orientación', 'OA3', 'Reconocer y valorar la sexualidad como expresión de amor, vínculo e intimidad entre dos personas y como gestora de su propia vida.'),
  ('4° Básico', 'Orientación', 'OA4', 'Reconocer y valorar el proceso de desarrollo afectivo y sexual, describiendo los cambios físicos y afectivos que ocurren en la pubertad y respetar los diferentes ritmos de desarrollo entre sus pares.'),
  ('4° Básico', 'Orientación', 'OA5', 'Identificar y practicar en forma autónoma conductas protectoras y de autocuidado en relación a: · rutinas de higiene · actividades de descanso, recreación y actividad física · hábitos de alimentación · resguardo del cuerpo y la intimidad · la entrega de información personal · situaciones de potencial abuso · consumo de drogas'),
  ('4° Básico', 'Orientación', 'OA6', 'Manifestar actitudes de solidaridad y respeto, que favorezcan la convivencia, como: actuar en forma empática (poniéndose en el lugar del otro) · utilizar un buen trato (por ejemplo, saludar, despedirse, pedir por favor) · evitar y rechazar toda forma de violencia y discriminación, ya sea por etnias, género, religión, nacionalidad, etc. · respetar el derecho de todos a expresar opiniones y ser diferente · prestar ayuda especialmente a quien lo necesite · respetar el ambiente de aprendizaje'),
  ('4° Básico', 'Orientación', 'OA7', 'Resolver conflictos entre pares en forma guiada y aplicando estrategias diversas de resolución de problemas, tales como escuchar, describir los sentimientos del otro y buscar un acuerdo que satisfaga a ambas partes.'),
  ('4° Básico', 'Orientación', 'OA8', 'Participar en forma guiada en la comunidad escolar y en la organización del curso: · proponiendo y aceptando iniciativas, y asumiendo responsabilidades · estableciendo acuerdos a través del diálogo y de la toma de decisiones democráticas · respetando los derechos de los demás en la distribución de roles y responsabilidades'),
  ('4° Básico', 'Orientación', 'OA9', 'Manifestar hábitos y actitudes de esfuerzo e interés que favorezcan el aprendizaje, como: · asistir puntualmente a clases y cumplir a tiempo con los trabajos pedidos · organizar su tiempo y sus útiles · respetar el estudio y el trabajo de otros · evitar el plagio y la copia · preguntar y buscar información sobre temas de su interés · desarrollar actividades en relación a sus propios intereses'),
  ('4° Básico', 'Tecnología', 'OA1', 'Crear diseños de objetos o sistemas tecnológicos simples para resolver problemas: · desde diversos ámbitos tecnológicos y tópicos de otras asignaturas · representando sus ideas a través de dibujos a mano alzada, dibujo técnico o usando TIC · explorando y transformando productos existentes'),
  ('4° Básico', 'Tecnología', 'OA2', 'Planificar la elaboración de un objeto tecnológico, incorporando la secuencia de acciones, materiales, herramientas, técnicas y medidas de seguridad necesarias para lograr el resultado deseado, y discutiendo las implicancias ambientales de los recursos utilizados.'),
  ('4° Básico', 'Tecnología', 'OA3', 'Elaborar un objeto tecnológico para resolver problemas, seleccionando y demostrando dominio de: · técnicas y herramientas para medir, marcar, cortar, unir, pintar, perforar, serrar, plegar y pegar, entre otras · materiales como papeles, cartones, maderas, fibras, plásticos, cerámicos, desechos, entre otros'),
  ('4° Básico', 'Tecnología', 'OA4', 'Probar y evaluar la calidad de los trabajos propios o de otros, de forma individual o en equipos, aplicando criterios de funcionamiento, técnicos, medioambientales y de seguridad, y dialogando sobre sus resultados e ideas de mejoramiento. ra organizar y comunicar ideas e información con diferentes nte: resentación para mostrar imágenes, diagramas y textos, · hojas de cálculo para ordenar datos y elaborar gráficos simples'),
  ('4° Básico', 'Tecnología', 'OA6', 'Usar procesador de textos para crear, editar, dar formato, incorporar elementos de diseño y guardar un documento.'),
  ('4° Básico', 'Tecnología', 'OA7', 'Usar internet y buscadores para localizar, extraer, evaluar y almacenar información, considerando la seguridad de la fuente.'),
  ('5° Básico', 'Artes Visuales', 'OA1', 'Crear trabajos de arte y diseños a partir de sus propias ideas y de la observación del: · entorno cultural: Chile, su paisaje y sus costumbres en el pasado y en el presente · entorno artístico: impresionismo y postimpresionismo; y diseño en Chile, Latinoamérica y del resto del mundo'),
  ('5° Básico', 'Artes Visuales', 'OA2', 'Aplicar y combinar elementos del lenguaje visual (incluidos los de niveles anteriores) en trabajos de arte y diseños con diferentes propósitos expresivos y creativos: · color (complementario) · formas (abiertas y cerradas) · luz y sombra'),
  ('5° Básico', 'Artes Visuales', 'OA3', 'Crear trabajos de arte y diseños a partir de diferentes desafíos y temas del entorno cultural y artístico, demostrando dominio en el uso de: · materiales de modelado, de reciclaje, naturales, papeles, cartones, pegamentos, lápices, pinturas, textiles e imágenes digitales · herramientas para dibujar, pintar, cortar, unir, modelar y tecnológicas (brocha, sierra de calar, esteca, cámara de video y proyector multimedia, entre otros) · procedimientos de pintura, escultura, construcción, fotografía, video, diseño gráfico digital, entre otros'),
  ('5° Básico', 'Artes Visuales', 'OA4', 'Analizar e interpretar obras de arte y diseño en relación con la aplicación del lenguaje visual, contextos, materiales, estilos u otros. (Observar anualmente al menos 50 obras de arte y diseño chileno, latinoamericano y universal).'),
  ('5° Básico', 'Artes Visuales', 'OA5', 'Describir y comparar trabajos de arte y diseños personales y de sus pares, considerando: · fortalezas y aspectos a mejorar · uso de materiales y procedimientos · aplicación de elementos del lenguaje visual · propósitos expresivos'),
  ('5° Básico', 'Ciencias Naturales', 'OA1', 'Reconocer y explicar que los seres vivos están formados por una o más células y que estas se organizan en tejidos, órganos y sistemas.'),
  ('5° Básico', 'Ciencias Naturales', 'OA2', 'Identificar y describir, por medio de modelos, las estructuras básicas del sistema digestivo (boca, esófago, estómago, hígado, intestino delgado, intestino grueso, recto y ano) y sus funciones en la digestión, la absorción de alimentos y la eliminación de desechos.'),
  ('5° Básico', 'Ciencias Naturales', 'OA3', 'Explicar, por medio de modelos, la respiración (inspiración-espiración-intercambio de oxígeno y dióxido de carbono), identificando las estructuras básicas del sistema respiratorio (nariz, tráquea, bronquios, alvéolos, pulmones).'),
  ('5° Básico', 'Ciencias Naturales', 'OA4', 'Explicar la función de transporte del sistema circulatorio (sustancias alimenticias, oxígeno y dióxido de carbono), identificando sus estructuras básicas (corazón, vasos sanguíneos y sangre). C uer p o h u m an o y s alud'),
  ('5° Básico', 'Ciencias Naturales', 'OA5', 'Analizar el consumo de alimento diario (variedad, tamaño y frecuencia de porciones), reconociendo los alimentos para el crecimiento, la reparación, el desarrollo y el movimiento del cuerpo.'),
  ('5° Básico', 'Ciencias Naturales', 'OA6', 'Investigar en diversas fuentes y comunicar los efectos nocivos que produce el cigarrillo (humo del tabaco) en los sistemas respiratorio y circulatorio.'),
  ('5° Básico', 'Ciencias Naturales', 'OA7', 'Investigar e identificar algunos microorganismos beneficiosos y dañinos para la salud (bacterias, virus y hongos), y proponer medidas de cuidado e higiene del cuerpo.'),
  ('5° Básico', 'Ciencias Naturales', 'OA8', 'Reconocer los cambios que experimenta la energía eléctrica al pasar de una forma a otra (eléctrica a calórica, sonora, lumínica, etc.) e investigar los principales aportes de científicos en su estudio a lo largo del tiempo.'),
  ('5° Básico', 'Ciencias Naturales', 'OA9', 'Construir un circuito eléctrico simple (cable, ampolleta, interruptor y pila), usarlo para resolver problemas cotidianos y explicar su funcionamiento.'),
  ('5° Básico', 'Ciencias Naturales', 'OA10', 'Observar y distinguir, por medio de la investigación experimental, los materiales conductores (cobre y aluminio) y aisladores (plásticos y goma) de electricidad, relacionándolos con la manipulación segura de artefactos tecnológicos y circuitos eléctricos domiciliarios.'),
  ('5° Básico', 'Ciencias Naturales', 'OA11', 'Explicar la importancia de la energía eléctrica en la vida cotidiana y proponer medidas para promover su ahorro y su uso responsable.'),
  ('5° Básico', 'Ciencias Naturales', 'OA12', 'Describir la distribución del agua dulce y salada en la Tierra, considerando océanos, glaciares, ríos y lagos, aguas subterráneas, nubes, vapor de agua, etc., y comparar sus volúmenes, reconociendo la escasez relativa de agua dulce.'),
  ('5° Básico', 'Ciencias Naturales', 'OA13', 'Analizar y describir las características de los océanos y lagos: · variación de temperatura, luminosidad y presión en relación con la profundidad · diversidad de flora y fauna · movimiento de las aguas, como olas, mareas, corrientes (El Niño y Humboldt)'),
  ('5° Básico', 'Ciencias Naturales', 'OA14', 'Investigar y explicar efectos positivos y negativos de la actividad humana en océanos, lagos, ríos, glaciares, entre otros, proponiendo acciones de protección de las reservas hídricas en Chile y comunicando sus resultados.'),
  ('5° Básico', 'Educación Física', 'OA1', 'Demostrar la aplicación de las habilidades motrices básicas adquiridas, en una variedad de actividades deportivas, por ejemplo, realizar un giro sobre una viga de equilibrio, lanzar un balón hacia la portería y correr una distancia determinada (por ejemplo, 50 u 80 metros), superando pequeños obstáculos.'),
  ('5° Básico', 'Educación Física', 'OA2', 'Ejecutar juegos colectivos y deportes, creando tácticas y estrategias y demostrando formas para resolver un problema en relación al espacio, el objeto y los adversarios, por ejemplo, dar tres pases en cinco segundos o dar tres pasos y dar un pase a un compañero.'),
  ('5° Básico', 'Educación Física', 'OA3', 'Practicar deportes individuales y colectivos con reglas y espacios adaptados en los que aplican estrategias defensivas y ofensivas, por ejemplo, reducir y ampliar espacios, obtener y mantener la posesión del balón y transportar el balón de forma controlada.'),
  ('5° Básico', 'Educación Física', 'OA4', 'Ejecutar actividades físicas y/o deportivas, utilizando diferentes entornos y aplicando medidas para conservar limpios y ordenados los espacios, ejemplo: · caminatas recreativas urbanas · bailes recreativos · cicletadas · juegos de balón en plazas y parques'),
  ('5° Básico', 'Educación Física', 'OA5', 'Demostrar la correcta ejecución de una danza nacional, utilizando pasos básicos y música folclórica de forma individual o grupal, por ejemplo, danzas de la zona norte, central, sur e Isla de Pascua.'),
  ('5° Básico', 'Educación Física', 'OA6', 'Ejecutar actividades físicas de intensidad moderada a vigorosa que desarrollen la condición física por medio de la práctica de ejercicios de resistencia cardiovascular, fuerza, flexibilidad y velocidad, estableciendo metas de superación personal.'),
  ('5° Básico', 'Educación Física', 'OA7', 'Practicar y planificar de forma regular actividades físicas y/o deportivas de intensidad moderada a vigorosa, como planificar un partido, participar en una caminata o corrida familiar e integrar talleres deportivos.'),
  ('5° Básico', 'Educación Física', 'OA8', 'Determinar la intensidad del esfuerzo físico de forma manual, mediante el pulso o utilizando escalas de percepción de esfuerzo.'),
  ('5° Básico', 'Educación Física', 'OA9', 'Practicar actividades físicas en forma segura, demostrando la adquisición de hábitos de higiene, posturales y de vida saludable, como utilizar una ropa distinta para la clase, mantener una correcta postura, utilizar protectores solares e hidratarse con agua antes, durante y después de la clase.'),
  ('5° Básico', 'Educación Física', 'OA10', 'Practicar actividades físicas y /o juegos colectivos, demostrando responsabilidad, liderazgo y respeto al participar, por ejemplo: conversar y plantear discrepancias, aceptar las diferencias individuales e intentar llegar a acuerdos, jugar en forma cooperativa, aceptar el resultado y manejar el triunfo.'),
  ('5° Básico', 'Educación Física', 'OA11', 'Practicar actividades físicas y/o deportivas, demostrando comportamientos seguros y un manejo adecuado de los materiales y los procedimientos, como: · realizar un calentamiento específico individual o grupal · usar ropa adecuada para la actividad · cuidar sus pertenencias · manipular de forma segura los implementos y las instalaciones Salud 133 Básico Sexto y Salud 6º básico 135 izaje'),
  ('5° Básico', 'Historia, Geografía y Cs. Sociales', 'OA1', 'Explicar los viajes de descubrimiento de Cristóbal Colón, de Hernando de Magallanes y de algún otro explorador, considerando sus objetivos, las rutas recorridas, los avances tecnológicos que facilitaron la navegación, las dificultades y los desafíos que enfrentaron las tripulaciones y el contexto europeo general en que se desarrollaron.'),
  ('5° Básico', 'Historia, Geografía y Cs. Sociales', 'OA2', 'Describir el proceso de conquista de América y de Chile, incluyendo a los principales actores (Corona española, Iglesia católica y hombres y mujeres protagonistas, entre otros), algunas expediciones y conflictos bélicos, y la fundación de ciudades como expresión de la voluntad de los españoles de quedarse y expandirse, y reconocer en este proceso el surgimiento de una nueva sociedad.'),
  ('5° Básico', 'Historia, Geografía y Cs. Sociales', 'OA3', 'Analizar el impacto y las consecuencias que tuvo el proceso de conquista para Europa y para América, considerando diversos ámbitos.'),
  ('5° Básico', 'Historia, Geografía y Cs. Sociales', 'OA4', 'Investigar sobre los efectos de la conquista sobre los pueblos indígenas americanos, utilizando fuentes dadas por el docente.'),
  ('5° Básico', 'Historia, Geografía y Cs. Sociales', 'OA5', 'Describir algunas dimensiones de la vida colonial en Chile, como organización de la sociedad y grupos sociales, oficios y actividades económicas, costumbres y vida cotidiana, arte y celebraciones.'),
  ('5° Básico', 'Historia, Geografía y Cs. Sociales', 'OA6', 'Explicar aspectos centrales de la Colonia, como la dependencia de las colonias americanas de la metrópoli, el rol de la Iglesia católica y el surgimiento de una sociedad mestiza.'),
  ('5° Básico', 'Historia, Geografía y Cs. Sociales', 'OA7', 'Explicar y dar ejemplos de las distintas formas en las que españoles y mapuches se relacionaron en el período colonial, considerando resistencia mapuche y guerra de Arauco, mestizaje, formas de trabajo (como encomienda y esclavitud), evangelización, vida fronteriza y sistema de parlamentos.'),
  ('5° Básico', 'Historia, Geografía y Cs. Sociales', 'OA8', 'Identificar, en su entorno o en fotografías, elementos del patrimonio colonial de Chile que siguen presentes hoy, como edificios, obras de arte y costumbres, entre otros. iales 5º Básico 171'),
  ('5° Básico', 'Historia, Geografía y Cs. Sociales', 'OA9', 'Caracterizar las grandes zonas de Chile y sus paisajes (Norte Grande, Norte Chico, Zona Central, Zona Sur y Zona Austral), considerando ubicación, clima (temperatura y precipitaciones), relieve, hidrografía, población y recursos naturales, entre otros.'),
  ('5° Básico', 'Historia, Geografía y Cs. Sociales', 'OA10', 'Reconocer y ubicar en mapas recursos naturales significativos de Chile, como cobre, hierro, recursos marítimos y forestales, entre otros; diferenciar recursos renovables y no renovables y explicar la importancia de cuidarlos en el marco de un desarrollo sostenible.'),
  ('5° Básico', 'Historia, Geografía y Cs. Sociales', 'OA11', 'Analizar y dar ejemplos de diversas maneras en las que el trabajo de las personas, sus ideas y proyectos potencian y dan valor a los recursos naturales (por ejemplo: tecnología de riego, elaboración de vinos, uso de madera en la construcción, nuevas formas de explotación sustentable).'),
  ('5° Básico', 'Historia, Geografía y Cs. Sociales', 'OA12', 'Investigar, describir y ubicar los riesgos naturales que afectan a su localidad, como sismos, maremotos, inundaciones, derrumbes y volcanismo, e identificar formas en que la comunidad puede protegerse (construcciones antisísmicas, medidas de seguridad y evacuación en el hogar, en la escuela y en los distintos espacios públicos, entre otros).'),
  ('5° Básico', 'Historia, Geografía y Cs. Sociales', 'OA13', 'Reconocer que todas las personas son sujetos de derecho, que deben ser respetados por los pares, la comunidad y el Estado, y que esos derechos no dependen de características individuales, como etnia, sexo, lugar de nacimiento u otras.'),
  ('5° Básico', 'Historia, Geografía y Cs. Sociales', 'OA14', 'Reconocer que los derechos generan deberes y responsabilidades en las personas y en el Estado, lo que se manifiesta, por ejemplo, en que: · las personas deben respetar los derechos de los demás · todas las personas deben respetar las leyes · el Estado debe asegurar que las personas puedan ejercer sus derechos (a la educación, a la protección de la salud, a la libertad de expresión, a la propiedad privada y a la igualdad ante la ley, entre otros) · el Estado debe asegurar los derechos de las personas a participar en la vida pública, como el derecho a formar organizaciones de participación social (fundaciones, juntas de vecinos, etc.), a participar en partidos políticos y el derecho a sufragio, entre otros'),
  ('5° Básico', 'Historia, Geografía y Cs. Sociales', 'OA15', 'Reconocer que hay logros y beneficios que dependen del esfuerzo, el mérito y el comportamiento de cada persona (como las calificaciones, los premios deportivos, los premios por compañerismo, el aprecio y el reconocimiento por parte de sus pares, el liderazgo).'),
  ('5° Básico', 'Historia, Geografía y Cs. Sociales', 'OA16', 'Demostrar actitudes cívicas con acciones en su vida diaria, como: · actuar con honestidad y responsabilidad (ejemplos: respetar los acuerdos establecidos, respetar la autoría de música y películas, evitar el plagio escolar, etc.) · respetar a todas las personas (ejemplos: no discriminar por condiciones físicas, sociales, culturales o étnicas, escuchar respetuosamente opiniones distintas, respetar espacios y propiedad de los demás, etc.) · contribuir a la buena convivencia (ejemplos: buscar soluciones pacíficas para resolver problemas, mostrar empatía con los demás, etc.) · cuidar y valorar el patrimonio y el medioambiente (ejemplos: realizar campañas de información y cuidado de nuestro patrimonio, usar la energía de manera eficiente, etc.)'),
  ('5° Básico', 'Historia, Geografía y Cs. Sociales', 'OA17', 'Participar en su comunidad, tomando parte en elecciones para una directiva de curso, asignando roles y funciones a cada cargo, y demostrando que entienden las responsabilidades que lleva consigo el desempeño de un cargo y la importancia de elegir personas que se estimen idóneas, para mantener una buena convivencia y una organización del curso que permita el trabajo escolar.'),
  ('5° Básico', 'Historia, Geografía y Cs. Sociales', 'OA18', 'Diseñar y participar en un proyecto que solucione un problema de la comunidad escolar, considerando temas como voluntariado, gasto excesivo de agua y electricidad en la escuela, y cuidado del medioambiente, entre otros, y ateniéndose a un plan y a un presupuesto.'),
  ('5° Básico', 'Historia, Geografía y Cs. Sociales', 'OA19', 'Explicar formas en que un grupo de personas puede organizarse para resolver problemas, mejorar su calidad de vida y la de otros y lograr metas comunes; por ejemplo, fundaciones, voluntariado, empresas, agrupaciones y recolección de fondos para causas benéficas.'),
  ('5° Básico', 'Historia, Geografía y Cs. Sociales', 'OA20', 'Opinar y argumentar con fundamentos sobre temas de la asignatura u otros.'),
  ('5° Básico', 'Historia, Geografía y Cs. Sociales', 'OA21', 'Evaluar posibles soluciones frente a un problema o proyecto y justificar su elección.'),
  ('5° Básico', 'Historia, Geografía y Cs. Sociales', 'OA22', 'Informarse y opinar sobre temas relevantes y de su interés en el país y el mundo (política, medioambiente, deporte, arte y música, entre otros) por medio de periódicos y TIC.'),
  ('5° Básico', 'Lenguaje y Comunicación', 'OA1', 'Leer de manera fluida textos variados apropiados a su edad: · pronunciando las palabras con precisión · respetando la prosodia indicada por todos los signos de puntuación · decodificando de manera automática la mayoría de las palabras del texto'),
  ('5° Básico', 'Lenguaje y Comunicación', 'OA2', 'Comprender textos, aplicando estrategias de comprensión lectora; por ejemplo: · relacionar la información del texto con sus experiencias y conocimientos · releer lo que no fue comprendido · formular preguntas sobre lo leído y responderlas · identificar las ideas más importantes de acuerdo con el propósito del lector · organizar la información en esquemas o mapas conceptuales'),
  ('5° Básico', 'Lenguaje y Comunicación', 'OA3', 'Leer y familiarizarse con un amplio repertorio de literatura para aumentar su conocimiento del mundo, desarrollar su imaginación y reconocer su valor social y cultural; por ejemplo: · poemas · cuentos folclóricos y de autor · fábulas · leyendas · mitos · novelas · historietas · otros'),
  ('5° Básico', 'Lenguaje y Comunicación', 'OA4', 'Analizar aspectos relevantes de narraciones leídas para profundizar su comprensión: · interpretando el lenguaje figurado presente en el texto · expresando opiniones sobre las actitudes y acciones de los personajes y fundamentándolas con ejemplos del texto · determinando las consecuencias de hechos o acciones · describiendo el ambiente y las costumbres representadas en el texto · explicando las características físicas y sicológicas de los personajes que son relevantes para el desarrollo de la historia · comparando textos de autores diferentes y justificando su preferencia por alguno 5º básico 331'),
  ('5° Básico', 'Lenguaje y Comunicación', 'OA5', 'Analizar aspectos relevantes de diversos poemas para profundizar su comprensión: · explicando cómo el lenguaje poético que emplea el autor apela a los sentidos, sugiere estados de ánimo y crea imágenes en el lector · identificando personificaciones y comparaciones y explicando su significado dentro del poema · distinguiendo los elementos formales de la poesía (rima asonante y consonante, verso y estrofa)'),
  ('5° Básico', 'Lenguaje y Comunicación', 'OA6', 'Leer independientemente y comprender textos no literarios (cartas, biografías, relatos históricos, libros y artículos informativos, noticias, etc.) para ampliar su conocimiento del mundo y formarse una opinión: · extrayendo información explícita e implícita · haciendo inferencias a partir de la información del texto y de sus experiencias y conocimientos · relacionando la información de imágenes, gráficos, tablas, mapas o diagramas, con el texto en el cual están insertos · interpretando expresiones en lenguaje figurado · comparando información · formulando una opinión sobre algún aspecto de la lectura · fundamentando su opinión con información del texto o sus conocimientos previos'),
  ('5° Básico', 'Lenguaje y Comunicación', 'OA7', 'Evaluar críticamente la información presente en textos de diversa procedencia: · determinando quién es el emisor, cuál es su propósito y a quién dirige el mensaje · evaluando si un texto entrega suficiente información para responder una determinada pregunta o cumplir un propósito'),
  ('5° Básico', 'Lenguaje y Comunicación', 'OA8', 'Sintetizar y registrar las ideas principales de textos leídos para satisfacer propósitos como estudiar, hacer una investigación, recordar detalles, etc.'),
  ('5° Básico', 'Lenguaje y Comunicación', 'OA9', 'Desarrollar el gusto por la lectura, leyendo habitualmente diversos textos.'),
  ('5° Básico', 'Lenguaje y Comunicación', 'OA10', 'Asistir habitualmente a la biblioteca para satisfacer diversos propósitos (seleccionar textos, investigar sobre un tema, informarse sobre actualidad, etc.), adecuando su comportamiento y cuidando el material para permitir el trabajo y la lectura de los demás.'),
  ('5° Básico', 'Lenguaje y Comunicación', 'OA11', 'Buscar y seleccionar la información más relevante sobre un tema en internet, libros, diarios, revistas, enciclopedias, atlas, etc., para llevar a cabo una investigación.'),
  ('5° Básico', 'Lenguaje y Comunicación', 'OA12', 'Aplicar estrategias para determinar el significado de palabras nuevas: · claves del texto (para determinar qué acepción es pertinente según el contexto) · raíces y afijos · preguntar a otro · diccionarios, enciclopedias e internet'),
  ('5° Básico', 'Lenguaje y Comunicación', 'OA13', 'Escribir frecuentemente, para desarrollar la creatividad y expresar sus ideas, textos como poemas, diarios de vida, cuentos, anécdotas, cartas, blogs, etc.'),
  ('5° Básico', 'Lenguaje y Comunicación', 'OA14', 'Escribir creativamente narraciones (relatos de experiencias personales, noticias, cuentos, etc.) que: · tengan una estructura clara · utilicen conectores adecuados · incluyan descripciones y diálogo (si es pertinente) para desarrollar la trama, los personajes y el ambiente'),
  ('5° Básico', 'Lenguaje y Comunicación', 'OA15', 'Escribir artículos informativos para comunicar información sobre un tema: · presentando el tema en una oración · desarrollando una idea central por párrafo · agregando las fuentes utilizadas'),
  ('5° Básico', 'Lenguaje y Comunicación', 'OA16', 'Escribir frecuentemente para compartir impresiones sobre sus lecturas, desarrollando un tema relevante del texto leído y fundamentando sus comentarios con ejemplos.'),
  ('5° Básico', 'Lenguaje y Comunicación', 'OA17', 'Planificar sus textos: · estableciendo propósito y destinatario · generando ideas a partir de sus conocimientos e investigación · organizando las ideas que compondrán su escrito'),
  ('5° Básico', 'Lenguaje y Comunicación', 'OA18', 'Escribir, revisar y editar sus textos para satisfacer un propósito y transmitir sus ideas con claridad. Durante este proceso: · desarrollan las ideas, agregando información · emplean un vocabulario preciso y variado, y un registro adecuado · releen a medida que escriben · aseguran la coherencia y agregan conectores · editan, en forma independiente, aspectos de ortografía y presentación · utilizan las herramientas del procesador de textos para buscar sinónimos, corregir ortografía y gramática, y dar formato (cuando escriben en computador) municación 5º básico 333'),
  ('5° Básico', 'Lenguaje y Comunicación', 'OA19', 'Incorporar de manera pertinente en la escritura el vocabulario nuevo extraído de textos escuchados o leídos.'),
  ('5° Básico', 'Lenguaje y Comunicación', 'OA20', 'Distinguir matices entre sinónimos al leer, hablar y escribir para ampliar su comprensión y capacidad expresiva.'),
  ('5° Básico', 'Lenguaje y Comunicación', 'OA21', 'Conjugar correctamente los verbos regulares al utilizarlos en sus producciones escritas.'),
  ('5° Básico', 'Lenguaje y Comunicación', 'OA22', 'Escribir correctamente para facilitar la comprensión por parte del lector, aplicando las reglas ortográficas aprendidas en años anteriores, además de: · uso de c-s-z · raya para indicar diálogo · acento diacrítico y dierético · coma en frases explicativas'),
  ('5° Básico', 'Lenguaje y Comunicación', 'OA23', 'Comprender y disfrutar versiones completas de obras de la literatura, narradas o leídas por un adulto, como: · cuentos folclóricos y de autor · poemas · mitos y leyendas · capítulos de novelas'),
  ('5° Básico', 'Lenguaje y Comunicación', 'OA24', 'Comprender textos orales (explicaciones, instrucciones, noticias, documentales, entrevistas, testimonios, relatos, etc.) para obtener información y desarrollar su curiosidad por el mundo: · relacionando las ideas escuchadas con sus experiencias personales y sus conocimientos previos · extrayendo y registrando la información relevante · formulando preguntas al profesor o a los compañeros para comprender o elaborar una idea, o aclarar el significado de una palabra · comparando información dentro del texto o con otros textos · formulando y fundamentando una opinión sobre lo escuchado'),
  ('5° Básico', 'Lenguaje y Comunicación', 'OA25', 'Apreciar obras de teatro, películas o representaciones: · discutiendo aspectos relevantes de la historia · describiendo a los personajes según su manera de hablar y de comportarse'),
  ('5° Básico', 'Lenguaje y Comunicación', 'OA26', 'Dialogar para compartir y desarrollar ideas y buscar acuerdos: · manteniendo el foco en un tema · aceptando sugerencias · haciendo comentarios en los momentos adecuados · mostrando acuerdo o desacuerdo con respeto · fundamentando su postura'),
  ('5° Básico', 'Lenguaje y Comunicación', 'OA27', 'Interactuar de acuerdo con las convenciones sociales en diferentes situaciones: · presentarse a sí mismo y a otros · saludar · preguntar · expresar opiniones, sentimientos e ideas · otras situaciones que requieran el uso de fórmulas de cortesía, como por favor, gracias, perdón, permiso'),
  ('5° Básico', 'Lenguaje y Comunicación', 'OA28', 'Expresarse de manera clara y efectiva en exposiciones orales para comunicar temas de su interés: · presentando las ideas de manera coherente y cohesiva · fundamentando sus planteamientos con ejemplos y datos · organizando las ideas en introducción, desarrollo y cierre · utilizando un vocabulario variado y preciso y un registro formal, adecuado a la situación comunicativa · reemplazando algunas construcciones sintácticas familiares por otras más variadas · conjugando correctamente los verbos · pronunciando claramente y usando un volumen audible, entonación, pausas y énfasis adecuados · usando gestos y posturas acordes a la situación · usando material de apoyo (power point, papelógrafo, objetos, etc.) de manera efectiva'),
  ('5° Básico', 'Lenguaje y Comunicación', 'OA29', 'Incorporar de manera pertinente en sus intervenciones orales el vocabulario nuevo extraído de textos escuchados o leídos.'),
  ('5° Básico', 'Lenguaje y Comunicación', 'OA30', 'Producir textos orales planificados de diverso tipo para desarrollar su capacidad expresiva: · poemas · narraciones (contar una historia, describir una actividad, relatar noticias, testimonios, etc.) · dramatizaciones'),
  ('5° Básico', 'Matemática', 'OA1', 'Representar y describir números naturales de hasta más de 6 dígitos y menores que 1.000 millones: · identificando el valor posicional de los dígitos · componiendo y descomponiendo números naturales en forma estándar y expandida aproximando cantidades · comparando y ordenando números naturales en este ámbito numérico · dando ejemplos de estos números naturales en contextos reales'),
  ('5° Básico', 'Matemática', 'OA2', 'Aplicar estrategias de cálculo mental para la multiplicación: · anexar ceros cuando se multiplica por un múltiplo de 10 · doblar y dividir por 2 en forma repetida · usando las propiedades conmutativa, asociativa y distributiva'),
  ('5° Básico', 'Matemática', 'OA3', 'Demostrar que comprenden la multiplicación de números naturales de dos dígitos por números naturales de dos dígitos: · estimando productos · aplicando estrategias de cálculo mental · resolviendo problemas rutinarios y no rutinarios, aplicando el algoritmo'),
  ('5° Básico', 'Matemática', 'OA4', 'Demostrar que comprenden la división con dividendos de tres dígitos y divisores de un dígito: · interpretando el resto · resolviendo problemas rutinarios y no rutinarios que impliquen divisiones'),
  ('5° Básico', 'Matemática', 'OA5', 'Realizar cálculos que involucren las cuatro operaciones, aplicando las reglas relativas a paréntesis y la prevalencia de la multiplicación y la división por sobre la adición y la sustracción cuando corresponda. · usando la propiedad distributiva de la multiplicación respecto de la suma · aplicando el algoritmo de la multiplicación · resolviendo problemas rutinarios'),
  ('5° Básico', 'Matemática', 'OA6', 'Resolver problemas rutinarios y no rutinarios que involucren las cuatro operaciones y combinaciones de ellas: · que incluyan situaciones con dinero · usando la calculadora y el computador en ámbitos numéricos superiores al 10.000'),
  ('5° Básico', 'Matemática', 'OA7', 'Demostrar que comprenden las fracciones propias: · representándolas de manera concreta, pictórica y simbólica · creando grupos de fracciones equivalentes –simplificando y amplificando– de manera concreta, pictórica y simbólica, de forma manual y/o con software educativo · comparando fracciones propias con igual y distinto denominador de manera concreta, pictórica y simbólica'),
  ('5° Básico', 'Matemática', 'OA8', 'Demostrar que comprenden las fracciones impropias de uso común de denominadores 2, 3, 4, 5, 6, 8, 10, 12 y los números mixtos asociados: · usando material concreto y pictórico para representarlas, de manera manual y/o con software educativo · identificando y determinando equivalencias entre fracciones impropias y números mixtos · representando estas fracciones y estos números mixtos en la recta numérica'),
  ('5° Básico', 'Matemática', 'OA9', 'Resolver adiciones y sustracciones con fracciones propias con denominadores menores o iguales a 12: · de manera pictórica y simbólica · amplificando o simplificando'),
  ('5° Básico', 'Matemática', 'OA10', 'Determinar el decimal que corresponde a fracciones con denominador 2, 4, 5 y 10.'),
  ('5° Básico', 'Matemática', 'OA11', 'Comparar y ordenar decimales hasta la milésima.'),
  ('5° Básico', 'Matemática', 'OA12', 'Resolver adiciones y sustracciones de decimales, empleando el valor posicional hasta la milésima.'),
  ('5° Básico', 'Matemática', 'OA13', 'Resolver problemas rutinarios y no rutinarios, aplicando adiciones y sustracciones de fracciones propias o decimales hasta la milésima.'),
  ('5° Básico', 'Matemática', 'OA14', 'Descubrir alguna regla que explique una sucesión dada y que permita hacer predicciones.'),
  ('5° Básico', 'Matemática', 'OA15', 'Resolver problemas, usando ecuaciones e inecuaciones de un paso, que involucren adiciones y sustracciones, en forma pictórica y simbólica.'),
  ('5° Básico', 'Matemática', 'OA16', 'Identificar y dibujar puntos en el primer cuadrante del plano cartesiano, dadas sus coordenadas en números naturales.'),
  ('5° Básico', 'Matemática', 'OA17', 'Describir y dar ejemplos de aristas y caras de figuras 3D y lados de figuras 2D: que son paralelos · que se intersectan · que son perpendiculares · 5º básico 249'),
  ('5° Básico', 'Matemática', 'OA18', 'Demostrar que comprenden el concepto de congruencia, usando la traslación, la reflexión y la rotación en cuadrículas y mediante software geométrico.'),
  ('5° Básico', 'Matemática', 'OA19', 'Medir longitudes con unidades estandarizadas (m, cm, mm) en el contexto de la resolución de problemas.'),
  ('5° Básico', 'Matemática', 'OA20', 'Realizar transformaciones entre unidades de medidas de longitud: km a m, m a cm, cm a mm y viceversa, de manera manual y/o usando software educativo.'),
  ('5° Básico', 'Matemática', 'OA21', 'Diseñar y construir diferentes rectángulos, dados el perímetro, el área o ambos, y sacar conclusiones.'),
  ('5° Básico', 'Matemática', 'OA22', 'Calcular áreas de triángulos, de paralelogramos y de trapecios, y estimar áreas de figuras irregulares, aplicando las siguientes estrategias: · conteo de cuadrículas · comparación con el área de un rectángulo · completar figuras por traslación'),
  ('5° Básico', 'Matemática', 'OA23', 'Calcular el promedio de datos e interpretarlo en su contexto. 24 Describir la posibilidad de ocurrencia de un evento por sobre la base de un experimento aleatorio, empleando los términos seguro – posible - poco posible - imposible.'),
  ('5° Básico', 'Matemática', 'OA25', 'Comparar probabilidades de distintos eventos sin calcularlas.'),
  ('5° Básico', 'Matemática', 'OA26', 'Leer, interpretar y completar tablas, gráficos de barra simple y gráficos de línea y comunicar sus conclusiones.'),
  ('5° Básico', 'Matemática', 'OA27', 'Utilizar diagramas de tallo y hojas para representar datos provenientes de muestras aleatorias.'),
  ('5° Básico', 'Música', 'OA1', 'Describir la música escuchada e interpretada, basándose en los elementos del lenguaje musical (reiteraciones, contrastes, pulsos, acentos, patrones rítmicos y melódicos, diseños melódicos, variaciones, dinámica, tempo, secciones A-AB-ABA-otras, preguntas-respuestas y texturas) y su propósito expresivo.'),
  ('5° Básico', 'Música', 'OA2', 'Expresar, mostrando grados crecientes de elaboración y detalle, las sensaciones, emociones e ideas que les sugiere la música escuchada e interpretada, usando diversos medios expresivos (verbal, corporal, musical, visual).'),
  ('5° Básico', 'Música', 'OA3', 'Escuchar música en forma abundante de diversos contextos y culturas, poniendo énfasis en: · Tradición escrita (docta) - música de compositores americanos y del mundo (por ejemplo, Cantos de México de C. Chávez, Malambo de C. Guastavino, Cinema de E. Satie) · Tradición oral (folclor, música de pueblos originarios) - música americana y sus orígenes (por ejemplo, música africana, huaynos, joropos) · Popular (jazz, rock, fusión, etc.) - música de América (por ejemplo: tangos, jazz, cumbias) (Escuchar apreciativamente al menos 15 músicas variadas de corta y mediana duración).'),
  ('5° Básico', 'Música', 'OA4', 'Cantar al unísono y a más voces y tocar instrumentos de percusión, melódicos (metalófono, flauta dulce u otros) y/o armónicos (guitarra, teclado, otros).'),
  ('5° Básico', 'Música', 'OA5', 'Improvisar y crear ideas musicales con un propósito dado y con un adecuado dominio del lenguaje musical.'),
  ('5° Básico', 'Música', 'OA6', 'Presentar su trabajo musical al curso y la comunidad, en forma individual y grupal, con responsabilidad, dominio y musicalidad. relación entre las obras interpretadas y/o escuchadas, con elementos del que surgen.'),
  ('5° Básico', 'Música', 'OA8', 'Reflexionar sobre sus fortalezas y las áreas en que pueden mejorar la audición, la interpretación y la creación, propia y de los otros, con respeto y autocrítica.'),
  ('5° Básico', 'Orientación', 'OA1', 'Demostrar una valoración positiva de sí mismo reconociendo habilidades, fortalezas y aspectos que requiera superar.'),
  ('5° Básico', 'Orientación', 'OA2', 'Distinguir y describir emociones y reconocer y practicar formas apropiadas de expresarlas, considerando el posible impacto en sí mismo y en otros.'),
  ('5° Básico', 'Orientación', 'OA3', 'Reconocer y valorar el proceso de desarrollo afectivo y sexual, que aprecia en sí mismo y en los demás, describiendo los cambios físicos, afectivos y sociales que ocurren en la pubertad, considerando la manifestación de estos en las motivaciones, formas de relacionarse y expresar afecto a los demás.'),
  ('5° Básico', 'Orientación', 'OA4', 'Practicar en forma autónoma conductas protectoras y de autocuidado, como: · mantener una comunicación efectiva con la familia o adulto de su confianza · resguardar la intimidad (por ejemplo, evitar exponer información personal, fotos íntimas a través de redes sociales, protegerse de manifestaciones de índole sexual inapropiadas) · seleccionar y acudir a fuentes de información confiables (personas significativas, libros y páginas de internet especializadas) · realizar un uso seguro de redes sociales'),
  ('5° Básico', 'Orientación', 'OA5', 'Reconocer y describir causas y consecuencias del consumo de drogas (por ejemplo, tabaco, alcohol, marihuana), identificar factores que lo previenen y proponer estrategias para enfrentarlo, como mantener hábitos de vida saludable y aprender a manejar el stress.'),
  ('5° Básico', 'Orientación', 'OA6', 'Manifestar actitudes de solidaridad y respeto, que favorezcan la convivencia, como: · actuar en forma empática (poniéndose en el lugar del otro) · utilizar un buen trato (por ejemplo, saludar, despedirse, pedir por favor) · evitar y rechazar toda forma de violencia y discriminación, ya sea por etnia, género, religión, nacionalidad, etc. · respetar el derecho de todos a expresar opiniones y ser diferente · prestar ayuda especialmente a quien lo necesite · respetar el ambiente de aprendizaje'),
  ('5° Básico', 'Orientación', 'OA7', 'Practicar y planificar de forma regular actividades físicas y/o deportivas de intensidad moderada a vigorosa, como planificar un partido, participar en una caminata, corrida o cicletada familiar e integrar talleres deportivos.'),
  ('5° Básico', 'Orientación', 'OA8', 'Participar activa y colaborativamente en la comunidad escolar y en la organización del curso: · planificando y evaluando actividades encaminadas a un objetivo · organizándose para resolver problemas cotidianos de la comunidad · asumiendo y cumpliendo responsabilidades · participando en las elecciones de curso y aceptando los resultados · respetando los derechos de los demás, sin discriminar en la distribución de roles y responsabilidades, entre otros · estableciendo acuerdos a través del diálogo y la toma de decisiones democráticas · evaluando el cumplimiento de los acuerdos de curso'),
  ('5° Básico', 'Orientación', 'OA9', 'Practicar en forma autónoma y perseverante, hábitos y actitudes orientadas a favorecer el aprendizaje y a desarrollar sus intereses, tales como: · establecer metas de aprendizaje · estudiar con anticipación, organizando su tiempo · trabajar en forma colaborativa · respetar el estudio y el trabajo de otros · evitar el plagio y la copia · preguntar y buscar información sobre temas de su interés · desarrollar actividades en relación a sus propios intereses utilizaron las tipografías tipografía chilena diseñada en todas sus variantes. hilado de 106 g para uché de 250 g para portadas. cuadrado, con costura al'),
  ('5° Básico', 'Orientación', 'OA10', 'Practicar actividades físicas y/o juegos colectivos, demostrando responsabilidad, liderazgo y respeto al participar, por ejemplo: conversar y plantear discrepancias, aceptar las diferencias individuales e intentar llegar a acuerdos, jugar en forma cooperativa, aceptar el resultado y manejar el triunfo.'),
  ('5° Básico', 'Orientación', 'OA11', 'Practicar actividades físicas y/o deportivas, demostrando comportamientos seguros y un manejo adecuado de los materiales y los procedimientos, como: · realizar un calentamiento específico individual o grupal · usar ropa adecuada para la actividad · cuidar sus pertenencias · manipular de forma segura los implementos y las instalaciones Historia, Geografía y Ciencias Sociales relevante en ella, y al observar cómo interactúan entre ante alcanzar una mejor comprensión de ellos, comenzará a reconocer los vínculos y las relaciones su rol en ella. Esta asignatura está con- que conforman la sociedad. A la vez, podrá apreciar cuábito escolar, por disciplinas que estu- les son las dinámicas que han permitido a su comunidad o como individuo y como miembro de la adaptarse al entorno natural y transformarlo. versas perspectivas, entre las que se inla Historia y la Geografía, la Economía, En este sentido, en los primeros niveles, los OA de la Sociología y la Ciencia Política. El trabajo asignatura privilegian el conocimiento, por parte de los disciplinas permite al alumno desarro- estudiantes, de la sociedad en que se desenvuelven, s, habilidades y actitudes necesarias para lo que requiere que identifiquen los grupos a los que pleja realidad social contemporánea y pertenecen (familia, escuela, comunidad, región, país, desenvolverse como un ciudadano capaz humanidad), las principales instituciones y las costumable y críticamente en la sociedad, y bres, normas y valores de su entorno, entre otros. s desafíos del mundo globalizado. En este proceso de desarrollo de la propia identidad, ásica, un objetivo central de esta resulta fundamental que reconozcan que cada ser humalos estudiantes adquieran un sentido no es único y que todas las personas son diferentes, pero pertenencia a la sociedad. Saber quién que, a su vez, podemos encontrar muchos elementos munidad y consolidar los lazos con ella en común que son los que nos permiten sentirnos parte damentales para el desarrollo integral de comunidades específicas (familia, localidad, región, adica la base que permite a los alumnos país, etc.). El respeto y la valoración de sí mismos, de la tura, apropiarse de ella y participar diversidad humana y de los aspectos que nos cohesionan n. Esa cultura adquirirá un significado como sociedad, se desarrollan inicialmente en la interactomen conciencia de que también ción con el propio entorno, y su alcance y profundidad se stintas, y perciban la diversidad inheren- van ampliando en la relación con los otros focos que se manos y a la naturaleza y las diferentes plantean a continuación. os se relacionan entre sí. F o r m ación del p en s a m ien t o h i s t óric o ruyen en torno a los siguientes énfasis: periencia de vivir en sociedad está contextualizada en el tiempo; en tanto que seres humanos, nuestra existencia el ento r no se desenvuelve en el devenir de la historia. En este sena a entender la realidad cuando tido, la construcción gradual del pensamiento histórico no natural y social. Al distinguir los constituye un fundamento esencial de esta asignatura y os y actores (personas e instituciones) es una herramienta necesaria para que los estudiantes de su vida cotidiana y cumplen un rol puedan desarrollar una visión crítica y comprensiva de su'),
  ('5° Básico', 'Tecnología', 'OA1', 'Escuchar y demostrar comprensión de información explícita en textos adaptados y auténticos simples, tanto no literarios (textos expositivos, diálogos) como literarios (rimas, canciones, cuentos), que estén enunciados en forma clara, tengan repetición de palabras y apoyo visual y gestual, y estén relacionados con las funciones del año y con los siguientes temas: · temas de la vida cotidiana: la escuela, la casa, la familia, la ropa, la comida, el clima · temas del contexto inmediato de los estudiantes, como experiencias personales e información de interés relativa a eventos y aspectos de su entorno y de nuestro país · temas de otras asignaturas, como alimentación equilibrada y variada (Ciencias Naturales) y descripción de lugares y clima (Geografía) · temas de actualidad e interés global, como cultura de otros países, cuidado del medioambiente y avances tecnológicos (redes sociales, medios de comunicación)'),
  ('5° Básico', 'Tecnología', 'OA2', 'Identificar en los textos escuchados: · tema e ideas generales · información específica asociada a personas, lugares y tiempo · palabras, familias de palabras, expresiones de uso frecuente y vocabulario temático · sonidos y repetición de sonidos para comenzar a familiarizarse con los sonidos del inglés'),
  ('5° Básico', 'Tecnología', 'OA3', 'Elaborar un producto tecnológico para resolver problemas y aprovechar oportunidades, seleccionando y demostrando dominio en el uso de: · técnicas y herramientas para medir, marcar, cortar, unir, pegar, mezclar, lijar, serrar, perforar y pintar, entre otras · materiales como papeles, cartones, maderas, fibras, plásticos, cerámicos, metales, desechos, entre otros'),
  ('5° Básico', 'Tecnología', 'OA4', 'Probar y evaluar la calidad de los trabajos propios o de otros, de forma individual o en equipos, aplicando criterios de funcionamiento, técnicos, medioambientales, estéticos y de seguridad, y dialogando sobre sus resultados e ideas de mejoramiento. ra organizar y comunicar los resultados de investigaciones e as con diferentes propósitos, mediante: resentación para mostrar imágenes, diagramas y textos, · hojas de cálculo para elaborar tablas de doble entrada y elaborar gráficos de barra y línea, entre otros'),
  ('5° Básico', 'Tecnología', 'OA5', 'Leer y demostrar comprensión de textos adaptados y auténticos simples no literarios, que contengan palabras de uso frecuente, familias de palabras, repetición de palabras y frases, estén acompañados de abundante apoyo visual y estén relacionados con los temas y las siguientes funciones del año: · saludar y despedirse · solicitar y entregar información personal y de temas familiares · agradecer, disculparse y pedir permiso · seguir y dar instrucciones · describir personas, objetos y su posición, lugares, acciones cotidianas y clima · expresar gustos, preferencias, cantidades y posesiones'),
  ('5° Básico', 'Tecnología', 'OA6', 'Leer comprensivamente textos no literarios, como notas, postales, invitaciones, tarjetas de saludo, menús, recetas, diálogos, instrucciones o emails, identificando: · propósito del texto · ideas generales · información explícita · palabras clave, expresiones de uso común asociadas a las funciones del nivel (por ejemplo: I’m sorry, excuse me) y vocabulario temático'),
  ('5° Básico', 'Tecnología', 'OA7', 'Leer comprensivamente textos literarios adaptados y auténticos simples, como rimas, canciones y cuentos, que contengan palabras de uso frecuente, familias de palabras, repetición de palabras y frases y estén acompañados de abundante apoyo visual, identificando: · tema general del texto · personajes, lugares y tiempo · secuencia de eventos (beginning – middle – end) · vocabulario temático y expresiones de uso común'),
  ('5° Básico', 'Tecnología', 'OA8', 'Reaccionar a los textos leídos, expresando preferencias o haciendo conexiones con experiencias personales, en forma oral, escrita o mediante ilustraciones.'),
  ('5° Básico', 'Tecnología', 'OA9', 'Usar las siguientes estrategias para apoyar la comprensión de los textos leídos, tanto en formato digital como impreso: · prelectura: hacer predicciones, basándose en conocimientos previos y elementos visuales · lectura: usar organizadores, como títulos, subtítulos, ilustraciones e imágenes · poslectura: organizar información en diagramas, releer'),
  ('5° Básico', 'Tecnología', 'OA10', 'Reproducir y producir monólogos, canciones, rimas y diálogos para comenzar a identificar y familiarizarse con los sonidos propios del idioma.'),
  ('5° Básico', 'Tecnología', 'OA11', 'Expresarse oralmente, ya sea en diálogos, presentaciones o actividades grupales, con apoyo de lenguaje visual y/o digital, en torno a los temas del año.'),
  ('5° Básico', 'Tecnología', 'OA12', 'Participar en diálogos con pares y profesores al realizar las siguientes funciones: · saludar y despedirse; por ejemplo: hello/good morning, goodbye · dar instrucciones; por ejemplo: sit down, close the door · agradecer, disculparse y pedir permiso; por ejemplo: thank you, sorry, may I...? · describir acciones cotidianas; por ejemplo: I run, I sleep · identificar y describir objetos, personas y lugares en su apariencia; por ejemplo: the... is big, it is black · agregar información; por ejemplo: it is big and black; this is my bag and that is your bag · describir el clima; por ejemplo: today is sunny/cloudy · expresar gustos y preferencias; por ejemplo: I like/don’t like... · describir posesiones; por ejemplo: this/that is my/your...; I/They have... · expresar cantidad numérica hasta el 20 · identificar y expresar cantidades; por ejemplo: there is a/an/one...; there are two/twenty... It is a/an... · solicitar y dar información; por ejemplo: How old/What/ Where is/are...?; there is/are...; it/this/the... is/are...; Is/Are he/they...? yes/no; Is he your father? Yes, he is/ No, he isn’t · identificar y describir posición de objetos; por ejemplo: the... is on/in/under the... · dar información general sobre un tema conocido; por ejemplo: the/he/they... is/are/have/eat/read · re-contar cuentos con apoyo de ilustraciones; por ejemplo: the...run/play/ have...; there is/ are... Inglés 5º básico 281'),
  ('5° Básico', 'Tecnología', 'OA13', 'Demostrar conocimiento y uso del vocabulario aprendido: vocabulario temático de uso cotidiano · palabras de uso frecuente · expresiones de uso común asociadas a las funciones del nivel (por ejemplo: · Excuse me, How old...?)'),
  ('5° Básico', 'Tecnología', 'OA14', 'Completar y escribir, de acuerdo a un modelo y con apoyo de lenguaje visual, textos no literarios (como postales, mini libros, listas de compras) y textos literarios (como rimas, tiras cómicas) con el propósito de compartir información en torno a los temas del año.'),
  ('5° Básico', 'Tecnología', 'OA15', 'Escribir para realizar las siguientes funciones: · describir acciones cotidianas; por ejemplo: I run, I sleep · expresar gustos y preferencias; por ejemplo: I like/don’t like · identificar y expresar cantidades; por ejemplo: there is a/an/one...; there are two/twenty...; It is a/an... · agregar información; por ejemplo: it is big and black · describir posesiones; por ejemplo: this is my/your... ...; I/They have... · expresar cantidad numérica hasta el 12 · identificar y describir objetos, personas y lugares por su apariencia; por ejemplo: the... is big; it is black · describir posición de objetos; por ejemplo: the... is on/in/under the... · dar información general sobre un tema conocido; por ejemplo: the...is/are/ have/eat/ read...; he/they is/are/have/eat/read... · describir el clima; por ejemplo: today is sunny/cloudy · solicitar y dar información; por ejemplo: What/ Where is/are...?; there is/are...; it/this/ the... is/are...; Is this...? Yes, it is/No, it isn’t; Is he your father? Yes, he is/No, he isn’t'),
  ('5° Básico', 'Tecnología', 'OA16', 'Utilizar los pasos del proceso de escritura (organización de ideas, escritura, corrección y publicación), recurriendo a herramientas como diccionario en línea y procesador de texto para: · escribir oraciones simples y párrafos breves de acuerdo a un modelo y con la ayuda del docente · demostrar conocimiento y uso de vocabulario temático de uso cotidiano, palabras de uso frecuente y expresiones de uso común asociadas a las funciones del nivel (por ejemplo: Excuse me, I’m sorry, How old...?)'),
  ('6° Básico', 'Artes Visuales', 'OA1', 'Crear trabajos de arte y diseños a partir de sus propias ideas y de la observación del: · entorno cultural: el hombre contemporáneo y la ciudad · entorno artístico: el arte contemporáneo y el arte en el espacio público (murales y esculturas)'),
  ('6° Básico', 'Artes Visuales', 'OA2', 'Aplicar y combinar elementos del lenguaje visual (incluidos los de niveles anteriores) en trabajos de arte y diseños con diferentes propósitos expresivos y creativos: · color (gamas y contrastes) · volumen (lleno y vacío)'),
  ('6° Básico', 'Artes Visuales', 'OA3', 'Crear trabajos de arte y diseños a partir de diferentes desafíos y temas del entorno cultural y artístico, demostrando dominio en el uso de: · materiales de modelado, de reciclaje, naturales, papeles, cartones, pegamentos, lápices, pinturas e imágenes digitales · herramientas para dibujar, pintar, cortar, unir, modelar y tecnológicas (rodillos de grabado, sierra de calar, mirete, cámara de video y proyector multimedia, entre otros) · procedimientos de pintura, grabado, escultura, instalación, técnicas mixtas, arte digital, fotografía, video, murales, entre otros'),
  ('6° Básico', 'Artes Visuales', 'OA4', 'Analizar e interpretar obras de arte y objetos en relación con la aplicación del lenguaje visual, contextos, materiales, estilos u otros. (Observar anualmente al menos 50 obras de arte chileno, latinoamericano y universal).'),
  ('6° Básico', 'Artes Visuales', 'OA5', 'Evaluar críticamente trabajos de arte y diseños personales y de sus pares, considerando: · expresión de emociones y problemáticas sociales · uso de materiales y procedimientos · aplicación de elementos del lenguaje visual · propósitos expresivos quellas disciplinas que aplicar una mirada científica a su aproximación a la natula naturaleza, como la raleza. En esta línea, la asignatura promueve una actitud la Botánica, la Geología de respeto hacia las pruebas o evidencias, un contacto estas disciplinas abor- reflexivo con el mundo natural y una actitud flexible para enos naturales: los reconsiderar ideas carentes de sustento empírico1. y sus distintas formas de materia, la energía y sus Actualmente, existe consenso respecto de la importancia ar, sus componentes de iniciar en forma temprana la educación científica en diversas dinámicas. El el ciclo escolar, tanto por su valor formativo como por ermite, por un lado, su capacidad para potenciar la disposición de los niños a y holística de la naturaleza, hacerse preguntas y buscar explicaciones sobre la natuantes procesos de trans- raleza y el entorno. En efecto, la ciencia es, esencialmenescuela para adquirir competencias que preparen a los a perspectiva episte- niños para desenvolverse en la sociedad actual2. científico. En esta, os en el entorno Para que este proceso sea exitoso, es fundamental que ediante diversas meto- los estudiantes se aproximen a las grandes ideas de la y que son sometidas ciencia, cuya comprensión les permita dotar de senl mundo. El estudio de tido a los fenómenos del mundo que los rodea. Estas eso de razonamiento ideas no se limitan a ofrecer explicaciones casuísticas nferencias, explicaciones y sobre preguntas que surgen en la vida cotidiana, sino encias registradas. Estos que identifican, de forma abstracta, relaciones entre cuerpo de conocimiento fenómenos y propiedades observadas3. La comprensión aturales a lo largo de de estas ideas facilita la predicción de fenómenos, la truyen en un determinado evaluación crítica de la evidencia científica y la toma tico. En este sentido, el de conciencia de la estrecha relación entre ciencia y definición, dinámico, sociedad. En este aspecto, es importante que, paulatipre está la posibilidad namente, los estudiantes puedan trabajar con diversas licaciones refuten a las fuentes de información, de modo que conozcan el múltiples ámbitos de la naturaleza. les permite despertar Asimismo, es imprescindible que los alumnos comcer el mundo que lo plementen la comprensión de las grandes ideas con el etodologías para estu- desarrollo de un modelo de habilidades de investigación studiante la posibilidad de científica, que los faculte para emprender proyectos de'),
  ('6° Básico', 'Ciencias Naturales', 'OA1', 'Explicar, a partir de una investigación experimental, los requerimientos de agua, dióxido de carbono y energía lumínica para la producción de azúcar y la liberación de oxígeno en la fotosíntesis, comunicando sus resultados y los aportes de científicos en este campo a lo largo del tiempo.'),
  ('6° Básico', 'Ciencias Naturales', 'OA2', 'Representar, por medio de modelos, la transferencia de energía y materia desde los organismos fotosintéticos a otros seres vivos por medio de cadenas y redes alimentarias en diferentes ecosistemas.'),
  ('6° Básico', 'Ciencias Naturales', 'OA3', 'Analizar los efectos de la actividad humana sobre las redes alimentarias. C uer p o h u m an o y s alud'),
  ('6° Básico', 'Ciencias Naturales', 'OA4', 'Identificar y describir las funciones de las principales estructuras del sistema reproductor humano femenino y masculino.'),
  ('6° Básico', 'Ciencias Naturales', 'OA5', 'Describir y comparar los cambios que se producen en la pubertad en mujeres y hombres, reconociéndola como una etapa del desarrollo humano.'),
  ('6° Básico', 'Ciencias Naturales', 'OA6', 'Reconocer los beneficios de realizar actividad física en forma regular y de cuidar la higiene corporal en el período de la pubertad.'),
  ('6° Básico', 'Ciencias Naturales', 'OA7', 'Investigar y comunicar los efectos nocivos de algunas drogas para la salud, proponiendo conductas de protección.'),
  ('6° Básico', 'Ciencias Naturales', 'OA8', 'Explicar que la energía es necesaria para que los objetos cambien y los seres vivos realicen sus procesos vitales, y que la mayoría de los recursos energéticos proviene directa o indirectamente del Sol, dando ejemplos de ello.'),
  ('6° Básico', 'Ciencias Naturales', 'OA9', 'Investigar en forma experimental la transformación de la energía de una forma a otra, dando ejemplos y comunicando sus conclusiones.'),
  ('6° Básico', 'Ciencias Naturales', 'OA10', 'Demostrar, por medio de la investigación experimental, que el calor fluye de un objeto caliente a uno frío hasta que ambos alcanzan la misma temperatura.'),
  ('6° Básico', 'Ciencias Naturales', 'OA11', 'Clasificar los recursos naturales energéticos en no renovables y renovables y proponer medidas para el uso responsable de la energía.'),
  ('6° Básico', 'Ciencias Naturales', 'OA12', 'Explicar, a partir de modelos, que la materia está formada por partículas en movimiento en sus estados sólido, líquido y gaseoso.'),
  ('6° Básico', 'Ciencias Naturales', 'OA13', 'Demostrar, mediante la investigación experimental, los cambios de estado de la materia, como fusión, evaporación, ebullición, condensación, solidificación y sublimación.'),
  ('6° Básico', 'Ciencias Naturales', 'OA14', 'Diferenciar entre calor y temperatura, considerando que el calor es una forma de energía y la temperatura es la medida de lo caliente de un objeto.'),
  ('6° Básico', 'Ciencias Naturales', 'OA15', 'Medir e interpretar la información obtenida al calentar y enfriar el agua, considerando las transformaciones de un estado a otro.'),
  ('6° Básico', 'Ciencias Naturales', 'OA16', 'Describir las características de las capas de la Tierra (atmósfera, litósfera e hidrósfera) que posibilitan el desarrollo de la vida y proveen recursos para el ser humano, y proponer medidas de protección de dichas capas.'),
  ('6° Básico', 'Ciencias Naturales', 'OA17', 'Investigar experimentalmente la formación del suelo, sus propiedades (como color, textura y capacidad de retención de agua) y la importancia de protegerlo de la contaminación, comunicando sus resultados.'),
  ('6° Básico', 'Ciencias Naturales', 'OA18', 'Explicar las consecuencias de la erosión sobre la superficie de la Tierra, identificando los agentes que la provocan, como el viento, el agua y las actividades humanas.'),
  ('6° Básico', 'Historia, Geografía y Cs. Sociales', 'OA1', 'Explicar los múltiples antecedentes de la independencia de las colonias americanas y reconocer que la independencia de Chile se enmarca en un proceso continental.'),
  ('6° Básico', 'Historia, Geografía y Cs. Sociales', 'OA2', 'Explicar el desarrollo del proceso de independencia de Chile, considerando actores y bandos que se enfrentaron, hombres y mujeres destacados, avances y retrocesos de la causa patriota, y algunos acontecimientos significativos, como la celebración del cabildo abierto de 1810 y la formación de la Primera Junta Nacional de Gobierno, la elección del primer Congreso Nacional, las batallas de Rancagua, Chacabuco y Maipú, y la Declaración de la Independencia, entre otros.'),
  ('6° Básico', 'Historia, Geografía y Cs. Sociales', 'OA3', 'Describir algunos hitos y procesos de la organización de la república, incluyendo las dificultades y los desafíos que implicó organizar en Chile una nueva forma de gobierno, el surgimiento de grupos con diferentes ideas políticas (conservadores y liberales), las características de la Constitución de 1833 y el impacto de las reformas realizadas por los liberales en la segunda mitad del siglo XIX.'),
  ('6° Básico', 'Historia, Geografía y Cs. Sociales', 'OA4', 'Investigar sobre algunos aspectos culturales del siglo XIX, como los avances en educación y la fundación de instituciones, el aporte de intelectuales y científicos nacionales (por ejemplo, Diego Barros Arana, Benjamín Vicuña Mackenna, José Victorino Lastarria) y extranjeros (por ejemplo, Andrés Bello, Claudio Gay, Charles Darwin y María Graham), las primeras mujeres en obtener títulos universitarios y el impacto en la sociedad de la llegada del ferrocarril y de otros avances tecnológicos, entre otros.'),
  ('6° Básico', 'Historia, Geografía y Cs. Sociales', 'OA5', 'Describir cómo se conformó el territorio de Chile durante el siglo XIX, considerando colonizaciones europeas, la incorporación de Isla de Pascua, la ocupación de la Araucanía, la Guerra del Pacífico y diversos conflictos bélicos, entre otros factores.'),
  ('6° Básico', 'Historia, Geografía y Cs. Sociales', 'OA6', 'Caracterizar los principales aspectos que definieron el período de riqueza aportada por la explotación del salitre, considerando la expansión económica y el inicio de la “cuestión social”.'),
  ('6° Básico', 'Historia, Geografía y Cs. Sociales', 'OA7', 'Explicar y dar ejemplos de la progresiva democratización de la sociedad durante el siglo XX, considerando el acceso creciente al voto, la participación de la mujer en la vida pública y el acceso a la educación y a la cultura, entre otros. iales 6º Básico 177'),
  ('6° Básico', 'Historia, Geografía y Cs. Sociales', 'OA8', 'Comparar diferentes visiones sobre el quiebre de la democracia en Chile, el régimen o dictadura militar y el proceso de recuperación de la democracia a fines del siglo XX, considerando los distintos actores, experiencias y puntos de vista, y el consenso actual con respecto al valor de la democracia.'),
  ('6° Básico', 'Historia, Geografía y Cs. Sociales', 'OA9', 'Explicar y dar ejemplos de aspectos que se mantienen y aspectos que han cambiado o se han desarrollado en la sociedad chilena a lo largo de su historia.'),
  ('6° Básico', 'Historia, Geografía y Cs. Sociales', 'OA10', 'Identificar elementos constitutivos del territorio nacional, considerando la localización de Chile en el mundo y su carácter tricontinental.'),
  ('6° Básico', 'Historia, Geografía y Cs. Sociales', 'OA11', 'Caracterizar geográficamente las regiones político-administrativas del país, destacando los rasgos físicos (como clima, relieve, hidrografía y vegetación) y humanos (como volumen y distribución de la población y actividades económicas) que les dan unidad.'),
  ('6° Básico', 'Historia, Geografía y Cs. Sociales', 'OA12', 'Comparar diversos ambientes naturales en Chile (desértico, altiplánico, costero, mediterráneo, andino, frío y lluvioso, patagónico y polar), considerando como criterios las oportunidades y las dificultades que presentan y cómo las personas las han aprovechado y superado para vivir y desarrollarse.'),
  ('6° Básico', 'Historia, Geografía y Cs. Sociales', 'OA13', 'Explicar las principales características físicas, humanas y económicas de su región y de su localidad.'),
  ('6° Básico', 'Historia, Geografía y Cs. Sociales', 'OA14', 'Explicar cómo han influido los desastres naturales en el desarrollo de Chile durante su historia reciente, dando ejemplos de nivel nacional y regional (sismos, volcanismo, sequía, inundaciones y derrumbes, entre otros).'),
  ('6° Básico', 'Historia, Geografía y Cs. Sociales', 'OA15', 'Explicar algunos elementos fundamentales de la organización democrática de Chile, incluyendo: · la división de poderes del Estado · la representación mediante cargos de elección popular (concejales, alcaldes, diputados, senadores y Presidente) · la importancia de la participación ciudadana'),
  ('6° Básico', 'Historia, Geografía y Cs. Sociales', 'OA16', 'Reconocer que la Constitución Política de Chile establece la organización política del país y garantiza los derechos y las libertades de las personas, instaurando un sistema democrático.'),
  ('6° Básico', 'Historia, Geografía y Cs. Sociales', 'OA17', 'Comprender que todas las personas tienen derechos que deben ser respetados por los pares, la comunidad y el Estado, lo que constituye la base para vivir en una sociedad justa, y dar como ejemplo algunos artículos de la Constitución y de la Declaración Universal de los Derechos Humanos.'),
  ('6° Básico', 'Historia, Geografía y Cs. Sociales', 'OA18', 'Explicar que los derechos generan deberes y responsabilidades en las personas e instituciones, y lo importante que es cumplirlos para la convivencia social y el bien común.'),
  ('6° Básico', 'Historia, Geografía y Cs. Sociales', 'OA19', 'Proponer y fundamentar distintas formas en que la sociedad puede proteger a las personas de situaciones en las que no se respetan sus derechos.'),
  ('6° Básico', 'Historia, Geografía y Cs. Sociales', 'OA20', 'Demostrar actitudes cívicas con acciones en su vida diaria, como: respetar a todas las personas (ejemplos: actuar considerando la igualdad de · derechos, escuchar respetuosamente opiniones distintas, etc.) contribuir a la buena convivencia (ejemplos: proponer posibles soluciones · frente a un problema, usar el diálogo para plantear ideas a sus pares, alcanzar acuerdos, cooperar activamente en el logro de metas comunes, etc.) actuar con honestidad y responsabilidad (ejemplos: hablar con la verdad, acú tuar de acuerdo a sus convicciones y de las responsabilidades que se deriven, cumplir las responsabilidades asumidas, evitar la copia textual y el plagio, etc.) cuidar y valorar el patrimonio y el medioambiente (ejemplos: impulsar y parú ticipar en campañas de reciclaje, realizar acciones en la casa y en la escuela para ahorrar luz, agua y gas, etc.)'),
  ('6° Básico', 'Historia, Geografía y Cs. Sociales', 'OA21', 'Trabajar en equipo de manera efectiva para llevar a cabo una investigación u otro proyecto, asignando y asumiendo roles, cumpliendo las responsabilidades asignadas y los tiempos acordados, escuchando los argumentos de los demás, manifestando opiniones fundamentadas y llegando a puntos de vista en común.'),
  ('6° Básico', 'Historia, Geografía y Cs. Sociales', 'OA22', 'Participar en su comunidad, tomando parte en elecciones para una directiva de curso, evaluando las propuestas realizadas por los diferentes aspirantes y considerando la importancia de elegir personas responsables.'),
  ('6° Básico', 'Historia, Geografía y Cs. Sociales', 'OA23', 'Participar, mediante acciones concretas, en proyectos que impliquen aportes dentro de la escuela, la comunidad y la sociedad, como voluntariado y ayuda social, entre otros, ateniéndose a un plan y un presupuesto.'),
  ('6° Básico', 'Historia, Geografía y Cs. Sociales', 'OA24', 'Opinar y argumentar con fundamentos sobre temas de la asignatura u otros. ria, Geografía y Ciencias Sociales 6º Básico 179'),
  ('6° Básico', 'Historia, Geografía y Cs. Sociales', 'OA25', 'Evaluar posibles soluciones frente a un problema o proyecto y justificar su elección.'),
  ('6° Básico', 'Historia, Geografía y Cs. Sociales', 'OA26', 'Informarse y opinar sobre temas relevantes y de su interés en el país y el mundo (política, medioambiente, deporte, arte y música, entre otros) por medio de periódicos y TICs.'),
  ('6° Básico', 'Lenguaje y Comunicación', 'OA1', 'Leer de manera fluida textos variados apropiados a su edad: · pronunciando las palabras con precisión · respetando la prosodia indicada por todos los signos de puntuación · decodificando de manera automática la mayoría de las palabras del texto'),
  ('6° Básico', 'Lenguaje y Comunicación', 'OA2', 'Comprender textos, aplicando estrategias de comprensión lectora; por ejemplo: · relacionar la información del texto con sus experiencias y conocimientos · releer lo que no fue comprendido · formular preguntas sobre lo leído y responderlas · organizar la información en esquemas o mapas conceptuales · resumir'),
  ('6° Básico', 'Lenguaje y Comunicación', 'OA3', 'Leer y familiarizarse con un amplio repertorio de literatura para aumentar su conocimiento del mundo, desarrollar su imaginación y reconocer su valor social y cultural; por ejemplo: · poemas · cuentos folclóricos y de autor · fábulas · leyendas · mitos · novelas · historietas · otros'),
  ('6° Básico', 'Lenguaje y Comunicación', 'OA4', 'Analizar aspectos relevantes de las narraciones leídas para profundizar su comprensión: · identificando las acciones principales del relato y explicando cómo influyen en el desarrollo de la historia · explicando las actitudes y reacciones de los personajes de acuerdo con sus motivaciones y las situaciones que viven · describiendo el ambiente y las costumbres representadas en el texto y explicando su influencia en las acciones del relato · relacionando el relato, si es pertinente, con la época y el lugar en que se ambienta · interpretando el lenguaje figurado presente en el texto · expresando opiniones sobre las actitudes y acciones de los personajes y fundamentándolas con ejemplos del texto 6º básico 337 legando a conclusiones sustentadas en la información del texto omparando textos de autores diferentes y justificando su preferencia por lguno'),
  ('6° Básico', 'Lenguaje y Comunicación', 'OA5', 'Analizar aspectos relevantes de diversos poemas para profundizar su comprensión: · explicando cómo el lenguaje poético que emplea el autor apela a los sentidos, sugiere estados de ánimo y crea imágenes en el lector · identificando personificaciones, comparaciones e hipérboles y explicando su significado dentro del poema · analizando cómo los efectos sonoros (aliteración y onomatopeya) utilizados por el poeta refuerzan lo dicho'),
  ('6° Básico', 'Lenguaje y Comunicación', 'OA6', 'Leer independientemente y comprender textos no literarios (cartas, biografías, relatos históricos, libros y artículos informativos, noticias, etc.) para ampliar su conocimiento del mundo y formarse una opinión: · extrayendo información explícita e implícita · haciendo inferencias a partir de la información del texto y de sus experiencias y conocimientos · relacionando la información de imágenes, gráficos, tablas, mapas o diagramas, con el texto en el cual están insertos · interpretando expresiones en lenguaje figurado · comparando información entre dos textos del mismo tema · formulando una opinión sobre algún aspecto de la lectura · fundamentando su opinión con información del texto o sus conocimientos previos'),
  ('6° Básico', 'Lenguaje y Comunicación', 'OA7', 'Evaluar críticamente la información presente en textos de diversa procedencia: · determinando quién es el emisor, cuál es su propósito y a quién dirige el mensaje · evaluando si un texto entrega suficiente información para responder una determinada pregunta o cumplir un propósito · comparando la información que se entrega sobre una misma noticia en distintas fuentes'),
  ('6° Básico', 'Lenguaje y Comunicación', 'OA8', 'Sintetizar, registrar y ordenar las ideas principales de textos leídos para satisfacer propósitos como estudiar, hacer una investigación, recordar detalles, etc.'),
  ('6° Básico', 'Lenguaje y Comunicación', 'OA9', 'Desarrollar el gusto por la lectura, leyendo habitualmente diversos textos.'),
  ('6° Básico', 'Lenguaje y Comunicación', 'OA10', 'Asistir habitualmente a la biblioteca para satisfacer diversos propósitos (seleccionar textos, investigar sobre un tema, informarse sobre actualidad, etc.), adecuando su comportamiento y cuidando el material para permitir el trabajo y la lectura de los demás.'),
  ('6° Básico', 'Lenguaje y Comunicación', 'OA11', 'Buscar y comparar información sobre un tema, utilizando fuentes como internet, enciclopedias, libros, prensa, etc., para llevar a cabo una investigación.'),
  ('6° Básico', 'Lenguaje y Comunicación', 'OA12', 'Aplicar estrategias para determinar el significado de palabras nuevas: · claves contextuales · raíces y afijos · preguntar a otro · diccionarios, enciclopedias e internet'),
  ('6° Básico', 'Lenguaje y Comunicación', 'OA13', 'Escribir frecuentemente, para desarrollar la creatividad y expresar sus ideas, textos como poemas, diarios de vida, cuentos, anécdotas, cartas, blogs, etc.'),
  ('6° Básico', 'Lenguaje y Comunicación', 'OA14', 'Escribir creativamente narraciones (relatos de experiencias personales, noticias, cuentos, etc.) que: · tengan una estructura clara · utilicen conectores adecuados · tengan coherencia en sus oraciones · incluyan descripciones y diálogo (si es pertinente) que desarrollen la trama, los personajes y el ambiente'),
  ('6° Básico', 'Lenguaje y Comunicación', 'OA15', 'Escribir artículos informativos para comunicar información sobre un tema: · organizando el texto en una estructura clara · desarrollando una idea central por párrafo · agregando las fuentes utilizadas'),
  ('6° Básico', 'Lenguaje y Comunicación', 'OA16', 'Escribir frecuentemente para compartir impresiones sobre sus lecturas, desarrollando un tema relevante del texto leído y fundamentando sus comentarios con ejemplos.'),
  ('6° Básico', 'Lenguaje y Comunicación', 'OA17', 'Planificar sus textos: · estableciendo propósito y destinatario · generando ideas a partir de sus conocimientos e investigación · organizando las ideas que compondrán su escrito municación 6º básico 339'),
  ('6° Básico', 'Lenguaje y Comunicación', 'OA18', 'Escribir, revisar y editar sus textos para satisfacer un propósito y transmitir sus ideas con claridad. Durante este proceso: · agregan ejemplos, datos y justificaciones para profundizar las ideas · emplean un vocabulario preciso y variado, y un registro adecuado · releen a medida que escriben · aseguran la coherencia y agregan conectores · editan, en forma independiente, aspectos de ortografía y presentación · utilizan las herramientas del procesador de textos para buscar sinónimos, corregir ortografía y gramática, y dar formato (cuando escriben en computador)'),
  ('6° Básico', 'Lenguaje y Comunicación', 'OA19', 'Incorporar de manera pertinente en la escritura el vocabulario nuevo extraído de textos escuchados o leídos.'),
  ('6° Básico', 'Lenguaje y Comunicación', 'OA20', 'Ampliar su capacidad expresiva, utilizando los recursos que ofrece el lenguaje para expresar un mismo mensaje de diversas maneras; por ejemplo: · sinónimos, hipónimos e hiperónimos · locuciones · comparaciones · otros'),
  ('6° Básico', 'Lenguaje y Comunicación', 'OA21', 'Utilizar correctamente los participios irregulares (por ejemplo, roto, abierto, dicho, escrito, muerto, puesto, vuelto) en sus producciones escritas.'),
  ('6° Básico', 'Lenguaje y Comunicación', 'OA22', 'Escribir correctamente para facilitar la comprensión por parte del lector, aplicando todas las reglas de ortografía literal, acentual y puntual aprendidas en años anteriores, además de: · escritura de los verbos haber, tener e ir, en los tiempos más utilizados · coma en frases explicativas · coma en presencia de conectores que la requieren · acentuación de pronombres interrogativos y exclamativos'),
  ('6° Básico', 'Lenguaje y Comunicación', 'OA23', 'Comprender y disfrutar versiones completas de obras de la literatura, narradas o leídas por un adulto, como: · cuentos folclóricos y de autor · poemas · mitos y leyendas · capítulos de novelas'),
  ('6° Básico', 'Lenguaje y Comunicación', 'OA24', 'Comprender textos orales (explicaciones, instrucciones, noticias, documentales, entrevistas, testimonios, relatos, reportajes, etc.) para obtener información y desarrollar su curiosidad por el mundo: · relacionando las ideas escuchadas con sus experiencias personales y sus conocimientos previos · extrayendo y registrando la información relevante reguntas al profesor o a los compañeros para comprender o idea, o aclarar el significado de una palabra nformación dentro del texto o con otros textos fundamentando una opinión sobre lo escuchado o diferentes puntos de vista'),
  ('6° Básico', 'Lenguaje y Comunicación', 'OA25', 'Evaluar críticamente mensajes publicitarios: · identificando al emisor · explicando cuál es la intención del emisor · identificando a quién está dirigido el mensaje (a niñas, a usuarios del metro, a adultos mayores, etc.) y fundamentando cómo llegaron a esa conclusión'),
  ('6° Básico', 'Lenguaje y Comunicación', 'OA26', 'Apreciar obras de teatro, películas o representaciones: · discutiendo aspectos relevantes de la historia · describiendo cómo los actores cambian sus tonos de voz y su gestualidad para expresar diversas emociones · identificando algunos recursos que buscan provocar un efecto en la audiencia (efectos de sonido, música, efectos de iluminación, etc.)'),
  ('6° Básico', 'Lenguaje y Comunicación', 'OA27', 'Dialogar para compartir y desarrollar ideas y buscar acuerdos: · manteniendo el foco en un tema · complementando las ideas de otro y ofreciendo sugerencias · aceptando sugerencias · haciendo comentarios en los momentos adecuados · mostrando acuerdo o desacuerdo con respeto · fundamentando su postura'),
  ('6° Básico', 'Lenguaje y Comunicación', 'OA28', 'Interactuar de acuerdo con las convenciones sociales en diferentes situaciones: · presentarse a sí mismo y a otros · saludar · preguntar · expresar opiniones, sentimientos e ideas · otras situaciones que requieran el uso de fórmulas de cortesía, como por favor, gracias, perdón, permiso'),
  ('6° Básico', 'Lenguaje y Comunicación', 'OA29', 'Expresarse de manera clara y efectiva en exposiciones orales para comunicar temas de su interés: · presentando las ideas de manera coherente y cohesiva · fundamentando sus planteamientos con ejemplos y datos · organizando las ideas en introducción, desarrollo y cierre · usando elementos de cohesión para relacionar cada parte de la exposición · utilizando un vocabulario variado y preciso y un registro formal adecuado a la situación comunicativa aje y Comunicación 6º básico 341 · reemplazando algunas construcciones sintácticas familiares por otras más variadas · conjugando correctamente los verbos · utilizando correctamente los participios irregulares · pronunciando claramente y usando un volumen audible, entonación, pausas y énfasis adecuados · usando gestos y posturas acordes a la situación · usando material de apoyo (power point, papelógrafo, objetos, etc.) de manera efectiva · exponiendo sin leer de un texto escrito'),
  ('6° Básico', 'Lenguaje y Comunicación', 'OA30', 'Incorporar de manera pertinente en sus intervenciones orales el vocabulario nuevo extraído de textos escuchados o leídos.'),
  ('6° Básico', 'Lenguaje y Comunicación', 'OA31', 'Producir textos orales espontáneos o planificados de diverso tipo para desarrollar su capacidad expresiva: · poemas · narraciones (contar una historia, describir una actividad, relatar noticias, testimonios, etc.) · dramatizaciones'),
  ('6° Básico', 'Matemática', 'OA1', 'Demostrar que comprenden los factores y los múltiplos: determinando los múltiplos y los factores de números naturales menores de · 100 · identificando números primos y compuestos · resolviendo problemas que involucran múltiplos'),
  ('6° Básico', 'Matemática', 'OA2', 'Realizar cálculos que involucren las cuatro operaciones en el contexto de la resolución de problemas, utilizando la calculadora en ámbitos superiores a 10 000.'),
  ('6° Básico', 'Matemática', 'OA3', 'Demostrar que comprenden el concepto de razón de manera concreta, pictórica y simbólica, en forma manual y/o usando software educativo.'),
  ('6° Básico', 'Matemática', 'OA4', 'Demostrar que comprenden el concepto de porcentaje de manera concreta, pictórica y simbólica, de forma manual y/o usando software educativo.'),
  ('6° Básico', 'Matemática', 'OA5', 'Demostrar que comprenden las fracciones y los números mixtos: · identificando y determinando equivalencias entre fracciones impropias y números mixtos, usando material concreto y representaciones pictóricas de manera manual y/o con software educativo · representando estos números en la recta numérica'),
  ('6° Básico', 'Matemática', 'OA6', 'Resolver adiciones y sustracciones de fracciones propias e impropias y números mixtos con numeradores y denominadores de hasta dos dígitos.'),
  ('6° Básico', 'Matemática', 'OA7', 'Demostrar que comprenden la multiplicación y la división de decimales por números naturales de un dígito, múltiplos de 10 y decimales hasta la milésima de manera concreta, pictórica y simbólica.'),
  ('6° Básico', 'Matemática', 'OA8', 'Resolver problemas rutinarios y no rutinarios que involucren adiciones y sustracciones de fracciones propias, impropias, números mixtos o decimales hasta la milésima.'),
  ('6° Básico', 'Matemática', 'OA9', 'Demostrar que comprenden la relación entre los valores de una tabla y aplicarla en la resolución de problemas sencillos: · identificando patrones entre los valores de la tabla · formulando una regla con lenguaje matemático'),
  ('6° Básico', 'Matemática', 'OA10', 'Representar generalizaciones de relaciones entre números naturales, usando expresiones con letras y ecuaciones.'),
  ('6° Básico', 'Matemática', 'OA11', 'Resolver ecuaciones de primer grado con una incógnita, utilizando estrategias como: · usar una balanza · usar la descomposición y la correspondencia 1 a 1 entre los términos en cada lado de la ecuación y aplicando procedimientos formales de resolución.'),
  ('6° Básico', 'Matemática', 'OA12', 'Construir y comparar triángulos de acuerdo a la medida de sus lados y/o sus ángulos con instrumentos geométricos o software geométrico.'),
  ('6° Básico', 'Matemática', 'OA13', 'Demostrar que comprenden el concepto de área de una superficie en cubos y paralelepípedos, calculando el área de sus redes (plantillas) asociadas.'),
  ('6° Básico', 'Matemática', 'OA14', 'Realizar teselados de figuras 2D, usando traslaciones, reflexiones y rotaciones.'),
  ('6° Básico', 'Matemática', 'OA15', 'Construir ángulos agudos, obtusos, rectos, extendidos y completos con instrumentos geométricos o software geométrico.'),
  ('6° Básico', 'Matemática', 'OA16', 'Identificar los ángulos que se forman entre dos rectas que se cortan (pares de ángulos opuestos por el vértice y pares de ángulos complementarios).'),
  ('6° Básico', 'Matemática', 'OA17', 'Demostrar de manera concreta, pictórica y simbólica que la suma de los ángulos interiores de un triángulo es 180º y de un cuadrilátero es 360o.'),
  ('6° Básico', 'Matemática', 'OA18', 'Calcular la superficie de cubos y paralelepípedos, expresando el resultado en cm2 y m2.'),
  ('6° Básico', 'Matemática', 'OA19', 'Calcular el volumen de cubos y paralelepípedos, expresando el resultado en cm3, m3 y mm3.'),
  ('6° Básico', 'Matemática', 'OA20', 'Estimar y medir ángulos, usando el transportador y expresando las mediciones en grados.'),
  ('6° Básico', 'Matemática', 'OA21', 'Calcular ángulos en rectas paralelas cortadas por una transversal y en triángulos.'),
  ('6° Básico', 'Matemática', 'OA22', 'Comparar distribuciones de dos grupos, provenientes de muestras aleatorias, usando diagramas de puntos y de tallo y hojas.'),
  ('6° Básico', 'Matemática', 'OA23', 'Conjeturar acerca de la tendencia de resultados obtenidos en repeticiones de un mismo experimento con dados, monedas u otros, de manera manual y/o usando software educativo.'),
  ('6° Básico', 'Matemática', 'OA24', 'Leer e interpretar gráficos de barra doble y circulares y comunicar sus conclusiones. Glosario 255 Diagrama que permite exhibir rápidamente datos sobre una recta Ejemplo: Temperaturas máximas en el mes de octubre x x x x x x x x x x x x x x x x x x x x x x x x x x x x x 19 20 21 22 23 24 25 26 27 Temperatura en oC Representación gráfica que permite mostrar datos en orden de valor de posición Ejemplo: Los números de dos cifras se pueden organizar usando un diagrama de tallo y hojas: el dígito de las decenas es un tallo y el de las unidades es una hoja. En el caso de los números 24 26 28 30 35 38 39 41 45 47: Tallo Hoja 2 4 6 8 3 0 5 8 9 4 1 5 7 Ejemplo: 5 · (3 +2) = 5 · 3 + 5 · 2 d e u n Ejemplo: Ecuaciones con una incógnita que requieren solo una operación para resolverlas: 1) 8 + 5 = 2) + 5 =15 3) 8 + =15 Ejemplo: 7 + 5 ante 7, 8, 9, 10, 11, 12 =› 7 + 5 = 12 Ejemplo: 15 - 4 14, 13, 12, 11 =› 15 – 4 = 11 Ejemplo: 7 +5= 7 + 3 = 10 10 + 2 = 12 Ejemplo: 7+9= 7 + 7 + 2 = 16 Ejemplo: En una adición o una sustracción, se suma o resta tanto como sea necesario para llegar a la decena más cercana y después se suma o resta lo que falta: 48 – 27 = 35 + 17 = 48 – 8 = 40 35 + 5 = 40 40 – 19 = 21 40 + 12 = 52 48 – 27 = 21 35 + 17 = 52 Glosario 257 Ejemplo: i tade s ” 33 – 16 = se considera el doble de 16, que es 32 32 + 1 – 16 = se descompone 33 en 32 + 1 32 – 16 + 1 = 16 + 1 = 17 Ejemplo: s ” 19 + 22 = 20 – 1 + 22 = 20 + 22 – 1 = 41 Ejemplo: o s ” 18 + 46 = se redondea 18 a 20 para facilitar el cálculo 20 2 + 46 = se expresa 18 como 20 - 2 20 + 46 – 2 = 64 Ejemplo: e s tar” 47 – 29 = 29 + = 47 se usa la reversibilidad de las operaciones 29 + 18 = 47 Ejemplo: ición” En una adición o una sustracción, se suma o resta tanto como sea necesario para llegar a la decena más cercana y después se suma o resta lo que falta: 48 – 27 = 35 + 17 = 48 – 20 = 28 35 + 10 = 45 28 – 7 = 21 45 + 7 = 52 48 – 27 = 21 35 + 17 = 52 Ejemplo: 25 · 8 = 50 · 4 = 200 b land o y En una multiplicación de dos factores, uno de ellos se dobla y el otro 2” se reduce a la mitad. Ejemplo: 25 · 8 = 50 · 4 =100 · 2 = 200 nte En una multiplicación de dos factores, uno de ellos se dobla más de s ” una vez y el otro se reduce a la mitad más de una vez. Ejemplo: 8 · 75 = 2 · 4 · 25 · 3 = 2 · 100 · 3 = 200 · 3 = 600 En una multiplicación de dos factores, ambos se factorizan. Ejemplo: 70 · 90 = (7 · 9) · 10 · 10 = 6 300 uan d o En una multiplicación de dos factores, en que uno de ellos o ambos son múltiplos de 10, se multiplican los números que quedan, sin considerar los ceros, y posteriormente se agregan. Ejemplo 1: y u s ar la 92 · 7 = (90+2) · 7 = 90 · 7 + 90 · 2 = 630 + 14 = 644 ri b u t i va” En una multiplicación de dos factores, uno de ellos se descompone en dos sumandos y posteriormente se aplica la propiedad distributiva. Ejemplo 2 : 7 · 4 = (3 + 4) · 4 = 3 ·4 +4·4 rica Ejemplo: 3 + 5 (cifras y signos) Glosario 259 o ne s ” Los números 7, 8 y 15 de la suma 7 + 8 = 15 están relacionadas de la siguiente manera: 7 + 8 i da d ” 8 + 7 15 - 8 15 - 7 “familia de operaciones” 7 + 8 = 15 8 + 7 = 15 15 – 8 = 7 15 – 7 = 8 Ejemplo: 4 325 = 4 000 + 300 + 20 + 5 A Ejemplo: 4 325 = 4 · 1 000 + 3 · 100 + 2 · 10 + 5 · 1 s 2 Ejemplo: 5 Fracciones cuyo numerador es menor que el denominador. ias 7 Ejemplo: 5 Fracciones cuyo numerador es mayor que el denominador. o d o El todo se toma como la unidad o el total de partes. Una fracción expresa un valor con relación a ese todo. 3 Ejemplo: La fracción significa que se tomaron 3 partes de un total 4 de 4 partes iguales. les no Ejemplo: 0,53 Decimal cuya parte no entera no tiene período sas Ejemplo: 7 · 5 = 35 y 35 : 5 = 7 licación stica Es una pregunta que tiene como propósito de recopilar información. Ejemplo: ¿Cuántas veces fuiste al cine en este mes? ¿Cuántos hermanos tienes? r ios Problemas familiares para los estudiantes, que están diseñados normalmente como ejercicios para practicar determinados conceptos y procedimientos. Su resolución implica seleccionar y aplicar conceptos y procedimientos aprendidos. Glosario 261 r ios Problemas poco o nada familiares para los estudiantes. Aun cuando su resolución requiere aplicar conceptos y procedimientos aprendidos, estos problemas hacen demandas cognitivas superiores a las que se necesitan para resolver problemas de rutina. Esto puede obedecer a la novedad y la complejidad de la situación, a que pueden tener más de una solución o a que cualquier solución puede involucrar varios pasos y que, además, pueden involucrar diferentes áreas de la matemática. Ejemplo: A Pedro le gustan los dulces (nivel 3º/4º básico) A Pedro le gustan mucho los dulces. Para su cumpleaños le regalaron una caja con 28 dulces. Cada día Pedro come el doble de dulces que el día anterior. Después de tres días, los ha comido todos. ¿Cuántos dulces ha comido Pedro en cada uno de los tres días? Explique su resolución. iva d e Ejemplo: 30 + 40 + 7 = (30 + 40) + 7 = 30 + (40 + 7) = 77 (sumar según conveniencia para facilitar una operación) a del aprendizaje del idioma cognitivas que les permitan organizar e internalizar la odos los ámbitos. Es una he- información a la que acceden a través del idioma. global y una vía de acceso a una amplia gama de informa- Diversos estudios acerca de la enseñanza y el aprendizaje actuales, que permite enfrentar de un idioma destacan la importancia de considerar las y la sociedad. Además de ser particularidades del contexto en que se enseña la lengua con otras realidades, apren- y las diversas características de los aprendices y, de acueromprender y apreciar la propia do a ello, tomar las opciones metodológicas más adecuaarrollo de habilidades cognitivas. das dentro de los conocimientos existentes.2 Considerando lo anterior, la presente propuesta de base curricular país, el idioma inglés es defi- toma principalmente los lineamientos del Enfoque anjera, ya que no se emplea Comunicativo para la enseñanza del inglés (Communicaón entre sus habitantes y tive Language Teaching) y lo complementa con aportes de acceso inmediato a su uso otros enfoques que ponen el énfasis en la comunicación. s. Lo anterior representa un gran idioma, tanto en relación con De acuerdo con el Enfoque Comunicativo, el idioma deja s como con el desarrollo de la de considerarse como un listado de contenidos gramatio.1 cales a enseñar y se convierte en un medio para comunicar significados y en una herramienta de interacción, en la el propósito de la asignatura que el mensaje y el uso del lenguaje son relevantes y los es que los alumnos apren- temas son significativos e interesantes para los alumnos. en como una herramienta para Asimismo, se enfatiza el desarrollo de las cuatro habilines comunicativas simples de dades del idioma inglés para que los estudiantes puedan almente, para acceder a nuevos comunicarse en forma efectiva y significativa, en diferenjes y responder a las deman- tes situaciones y con diversos propósitos comunicativos. l a través de los medios y'),
  ('6° Básico', 'Música', 'OA1', 'Describir la música escuchada e interpretada, basándose en los elementos del lenguaje musical (reiteraciones, contrastes, pulsos, acentos, patrones rítmicos y melódicos, diseños melódicos, variaciones, dinámica, tempo, secciones A-AB-ABAotras, preguntas-respuestas y texturas) y su propósito expresivo.'),
  ('6° Básico', 'Música', 'OA2', 'Expresar, mostrando grados crecientes de elaboración y detalle, las sensaciones, emociones e ideas que les sugiere la música escuchada e interpretada, usando diversos medios expresivos (verbal, corporal, musical, visual).'),
  ('6° Básico', 'Música', 'OA3', 'Escuchar música en forma abundante de diversos contextos y culturas, poniendo énfasis en: · Tradición escrita (docta) - música de compositores chilenos y del mundo (por ejemplo, La voz de las calles de P. H. Allende, Evocaciones Huilliches de Carlos Isamitt, Fanfarria para el hombre común de A. Copland) · Tradición oral (folclor, música de pueblos originarios) - música chilena y sus orígenes (por ejemplo, música mapuche, Rolando Alarcón, Grupo Cuncumén) · Popular (jazz, rock, fusión, etc.) - música chilena y sus influencias (por ejemplo: Los porfiados de la Cueca y La Ley) (Escuchar apreciativamente al menos 15 músicas variadas de corta y mediana duración)'),
  ('6° Básico', 'Música', 'OA4', 'Cantar al unísono y a más voces y tocar instrumentos de percusión, melódicos (metalófono, flauta dulce u otros) y/o armónicos (guitarra, teclado, otros).'),
  ('6° Básico', 'Música', 'OA5', 'Improvisar y crear ideas musicales con un propósito dado y con un adecuado dominio del lenguaje musical.'),
  ('6° Básico', 'Música', 'OA6', 'Presentar su trabajo musical al curso y la comunidad, en forma individual y grupal, con responsabilidad, dominio y musicalidad. a relación entre las obras interpretadas y/o escuchadas, con elementos del n que surgen.'),
  ('6° Básico', 'Música', 'OA8', 'Reflexionar sobre sus fortalezas y las áreas en que pueden mejorar la audición, la interpretación y la creación, propia y de otros, con respeto y autocrítica.'),
  ('6° Básico', 'Tecnología', 'OA1', 'Escuchar y demostrar comprensión de información explícita en textos adaptados y auténticos simples, tanto no literarios (textos expositivos, diálogos) como literarios (rimas, poemas, canciones, cuentos) que estén enunciados en forma clara, tengan repetición de palabras y apoyo visual y gestual, y estén relacionados con las funciones del año y los siguientes temas: · la comida y la bebida, la salud, lugares de la ciudad, ocupaciones, el mundo natural, viajes y medios de transporte · temas relacionados con el contexto inmediato de los estudiantes, como experiencias personales pasadas, sentimientos, historias ficticias e información de interés relativa a eventos y aspectos de su entorno y de nuestro país · temas de otras asignaturas: hábitos de limpieza e higiene, beneficios de actividad física, alimentación saludable (Ciencias Naturales); características geográficas como relieve y clima de Chile (Geografía) · temas de actualidad e interés global, como cultura de otros países, cuidado del medioambiente, avances tecnológicos (redes sociales, medios de comunicación)'),
  ('6° Básico', 'Tecnología', 'OA2', 'Identificar en los textos escuchados: · tema e ideas generales · información específica asociada a personas, lugares, tiempo y acciones · palabras, familias de palabras, expresiones de uso frecuente y vocabulario temático · repetición de sonidos y sonidos propios del idioma inglés que interfieren con la comunicación, como los sonidos ch/sh en palabras como chip/ship; b/v en palabras como boat/vote'),
  ('6° Básico', 'Tecnología', 'OA3', 'Elaborar un producto tecnológico para resolver problemas y aprovechar oportunidades, seleccionando y demostrando dominio en el uso de: · técnicas y herramientas para medir, marcar, cortar, unir, pegar, perforar, mezclar, lijar, serrar y pintar, entre otras · materiales como papeles, cartones, maderas, fibras, plásticos, cerámicos, metales, desechos, entre otros'),
  ('6° Básico', 'Tecnología', 'OA4', 'Probar y evaluar la calidad de los trabajos propios o de otros, de forma individual o en equipos, aplicando criterios de funcionamiento, técnicos, medioambientales, estéticos y de seguridad, dialogando sobre sus resultados y aplicando correcciones según corresponda. ra organizar y comunicar los resultados de investigaciones e as con diferentes propósitos, mediante: resentación para mostrar imágenes, diagramas y textos, · hojas de cálculo para elaborar tablas de doble entrada y diseñar gráficos de barra simple y doble, circulares y de línea, entre otros'),
  ('6° Básico', 'Tecnología', 'OA5', 'Leer y demostrar comprensión de textos adaptados y auténticos simples, no literarios, que contengan palabras de uso frecuente, familias de palabras y repetición de frases, y estén acompañados de apoyo visual y relacionados con los temas y las siguientes funciones del año: · expresar habilidad e inhabilidad · dar direcciones e indicar posición · solicitar y contrastar información · decir y preguntar la hora · referirse a acciones cotidianas que ocurren al momento de hablar y en el pasado · describir personas y acciones y cómo estas se realizan · expresar cantidades, necesidad y posesiones'),
  ('6° Básico', 'Tecnología', 'OA6', 'Leer comprensivamente textos no literarios, como notas, postales, invitaciones, tarjetas de saludo, menús, recetas, instrucciones, avisos publicitarios, emails, diálogos o textos expositivos, identificando: · propósito del texto · ideas generales · información explícita · palabras clave, expresiones de uso común asociadas a las funciones del nivel (por ejemplo: have lunch, catch a cold) y vocabulario temático'),
  ('6° Básico', 'Tecnología', 'OA7', 'Leer comprensivamente textos literarios adaptados y auténticos simples, como rimas, poemas, tiras cómicas y cuentos, que contengan palabras de uso frecuente, familias de palabras, repetición de frases y estén acompañados de apoyo visual, identificando: · tema general del texto · personajes, lugares, tiempo y acciones · secuencia de eventos (beginning – middle – end) · vocabulario temático y expresiones de uso común'),
  ('6° Básico', 'Tecnología', 'OA8', 'Reaccionar a los textos leídos, expresando opiniones y sentimientos o haciendo conexiones con experiencias personales, en forma oral o escrita.'),
  ('6° Básico', 'Tecnología', 'OA9', 'Usar las siguientes estrategias para apoyar la comprensión de los textos leídos, tanto en formato digital como impreso: · prelectura: hacer predicciones, basándose en conocimientos previos, elementos visuales y contextuales · lectura: usar organizadores, como títulos, subtítulos, ilustraciones, imágenes y notas · poslectura: organizar información en diagramas, releer, usar el texto leído como modelo para la expresión escrita'),
  ('6° Básico', 'Tecnología', 'OA10', 'Reproducir y producir textos orales, como monólogos, canciones, poemas, adivinanzas y diálogos, para identificar y familiarizarse con los sonidos propios del idioma, como, ch/sh en palabras como chip/ship; b/v en palabras como boat/ vote.'),
  ('6° Básico', 'Tecnología', 'OA11', 'Expresarse oralmente, ya sea en diálogos, presentaciones o actividades grupales, con apoyo visual y/o digital, en torno a los temas del año.'),
  ('6° Básico', 'Tecnología', 'OA12', 'Participar en diálogos con pares y profesores al realizar las siguientes funciones: · expresar habilidad e inhabilidad; por ejemplo: I can/can’t · describir posición y dar indicaciones de dirección y su secuencia; por ejemplo: The zoo is in front of the park; turn right/left, then go straight · describir personas en cuanto a personalidad o estado; por ejemplo: he is quiet/friendly; I feel sad/angry/tired · contrastar información; por ejemplo: it can run but it can’t jump; there is cheese but there isn’t bread · expresar necesidad; por ejemplo: I have to... · pedir y decir la hora; por ejemplo: What time is it? It’s 4 o’clock · describir y preguntar por acciones que ocurren al momento de hablar; por ejemplo: He is/isn’t reading; Is he reading? Yes, he is/No, he isn’t; Are they playing? Yes, they are/No, they aren’t · expresar cantidad y números hasta el 50; por ejemplo: there is/are a/many/a lot of...child/children; there are 30 cars · describir acciones que ocurren en el pasado; por ejemplo: I was/made/did/ felt... · describir acciones y cómo se realizan; por ejemplo: he reads fast/very slowly · expresar posesión; por ejemplo: it is his/her/our car; this is Pedro’s pet · formular y responder preguntas; por ejemplo: Who...?/How much/many...?/ Can...?/ Where...? · dar información general sobre un tema conocido; por ejemplo: the/he/they... is/are/have/eat/read · re-contar cuentos con apoyo de ilustraciones; por ejemplo: the...run/play/ have...; there is/are... Inglés 6º básico 287'),
  ('6° Básico', 'Tecnología', 'OA13', 'Demostrar conocimiento y uso del vocabulario aprendido: vocabulario temático · palabras de uso frecuente · expresiones de uso común asociadas a las funciones del nivel (por ejemplo: · have lunch, catch a cold)'),
  ('6° Básico', 'Tecnología', 'OA14', 'Escribir, de acuerdo a un modelo y con apoyo de lenguaje visual, textos no literarios (como email, postal, agenda, invitación) y textos literarios (como cuentos, rimas, tiras cómicas) con el propósito de compartir información en torno a los temas del año.'),
  ('6° Básico', 'Tecnología', 'OA15', 'Escribir para realizar las siguientes funciones: · indicar posición; por ejemplo: The zoo is in front of the park · describir personas en cuanto a personalidad o estado; por ejemplo: he is quiet/friendly; I feel sad/happy/angry · contrastar información; por ejemplo: it can fly but it can’t swim · expresar necesidad; por ejemplo: I have to... · describir y preguntar por acciones que ocurren al momento de hablar; por ejemplo: He is/isn’t reading; Is he reading? Yes, he is/No, he isn’t; Are they playing? Yes, they are/No, they aren’t · expresar cantidad e identificar sustantivos plurales irregulares; por ejemplo: there is/are a/many/a lot of...child/children · describir acciones que ocurren en el pasado; por ejemplo: I was/made/did/ felt... · describir acciones y cómo estas se realizan; por ejemplo: he reads fast/very slowly · expresar posesión; por ejemplo: it is his/her/our car; this is Pedro’s pet · expresar cantidad numérica hasta el 20 · formular y responder preguntas; por ejemplo: Who...?/How much/many...?/ Can...?/ Where...?'),
  ('7° Básico', 'Artes Visuales', 'OA1', 'Crear trabajos visuales basados en las percepciones, sentimientos e ideas generadas a partir de la observación de manifestaciones estéticas referidas a diversidad cultural, género e íconos sociales, patrimoniales y contemporáneos.'),
  ('7° Básico', 'Artes Visuales', 'OA2', 'Crear trabajos visuales a partir de intereses personales, experimentando con materiales sustentables en dibujo, pintura y escultura.'),
  ('7° Básico', 'Artes Visuales', 'OA3', 'Crear trabajos visuales a partir de la imaginación, experimentando con medios digitales de expresión contemporáneos como fotografía y edición de imágenes.'),
  ('7° Básico', 'Artes Visuales', 'OA4', 'Interpretar manifestaciones visuales patrimoniales y contemporáneas atendiendo a criterios como las características del medio de expresión, la materialidad y el lenguaje visual.'),
  ('7° Básico', 'Artes Visuales', 'OA5', 'Interpretar relaciones entre el propósito expresivo del trabajo artístico personal y de sus pares y la utilización del lenguaje visual.'),
  ('7° Básico', 'Artes Visuales', 'OA6', 'Caracterizar y apreciar espacios de difusión de las artes visuales contemplando los medios de expresión presentes, el espacio, el montaje y el público, entre otros.'),
  ('7° Básico', 'Ciencias Naturales', 'OA1', 'Explicar los aspectos biológicos, afectivos y sociales que se integran en la sexualidad, considerando: • Los cambios físicos que ocurren durante la pubertad. • La relación afectiva entre dos personas en la intimidad y el respeto mutuo. • La responsabilidad individual.'),
  ('7° Básico', 'Ciencias Naturales', 'OA2', 'Explicar la formación de un nuevo individuo, considerando: • El ciclo menstrual (días fértiles, menstruación y ovulación). • La participación de espermatozoides y ovocitos. • Métodos de control de la natalidad. • La paternidad y la maternidad responsables.'),
  ('7° Básico', 'Ciencias Naturales', 'OA3', 'Describir, por medio de la investigación, las características de infecciones de transmisión sexual (ITS), como sida y herpes, entre otros, considerando sus: • Mecanismos de transmisión. • Medidas de prevención. • Síntomas generales. • Consecuencias y posibles secuelas. *Experimental(es), no experimental(es) o documental(es), entre otras. 145'),
  ('7° Básico', 'Ciencias Naturales', 'OA4', 'Desarrollar modelos que expliquen las barreras defensivas (primaria, secundaria y terciaria) del cuerpo humano, considerando: • Agentes patógenos como Escherichia coli y el virus de la gripe. • Uso de vacunas contra infecciones comunes (influenza y meningitis, entre otras). • Alteraciones en sus respuestas, como en las alergias, las enfermedades autoinmunes y los rechazos a trasplantes de órganos.'),
  ('7° Básico', 'Ciencias Naturales', 'OA5', 'Comparar, usando modelos, microorganismos como virus, bacterias y hongos, en relación con: • Características estructurales (tamaño, forma y componentes). • Características comunes de los seres vivos (alimentación, reproducción, respiración, etc.). • Efectos sobre la salud humana (positivos y negativos).'),
  ('7° Básico', 'Ciencias Naturales', 'OA6', 'Investigar y explicar el rol de microorganismos (bacterias y hongos) en la biotecnología, como en la: • Descontaminación ambiental. • Producción de alimentos y fármacos. • Obtención del cobre. • Generación de metano. Física'),
  ('7° Básico', 'Ciencias Naturales', 'OA7', 'Planificar y conducir una investigación experimental para proveer evidencias que expliquen los efectos de las fuerzas gravitacional, de roce y elástica, entre otras, en situaciones cotidianas.'),
  ('7° Básico', 'Ciencias Naturales', 'OA8', 'Explorar y describir cualitativamente la presión, considerando sus efectos en: • Sólidos, como en herramientas mecánicas. • Líquidos, como en máquinas hidráulicas. • Gases, como en la atmósfera.'),
  ('7° Básico', 'Ciencias Naturales', 'OA9', 'Explicar, con el modelo de la tectónica de placas, los patrones de distribución de la actividad geológica (volcanes y sismos), los tipos de interacción entre las placas (convergente, divergente y transformante) y su importancia en la teoría de la deriva continental.'),
  ('7° Básico', 'Ciencias Naturales', 'OA10', 'Explicar, sobre la base de evidencias y por medio de modelos, la actividad volcánica y sus consecuencias en la naturaleza y la sociedad.'),
  ('7° Básico', 'Ciencias Naturales', 'OA11', 'Crear modelos que expliquen el ciclo de las rocas, la formación y modificación de las rocas ígneas, metamórficas y sedimentarias, en función de la temperatura, la presión y la erosión.'),
  ('7° Básico', 'Ciencias Naturales', 'OA12', 'Demostrar, por medio de modelos, que comprenden que el clima en la Tierra, tanto local como global, es dinámico y se produce por la interacción de múltiples variables, como la presión, la temperatura y la humedad atmosférica, la circulación de la atmósfera y del agua, la posición geográfica, la rotación y la traslación de la Tierra. Química'),
  ('7° Básico', 'Ciencias Naturales', 'OA13', 'Investigar experimentalmente y explicar el comportamiento de gases ideales en situaciones cotidianas, considerando: • Factores como presión, volumen y temperatura. • Las leyes que los modelan. • La teoría cinético-molecular.'),
  ('7° Básico', 'Ciencias Naturales', 'OA14', 'Investigar experimentalmente y explicar la clasificación de la materia en sustancias puras y mezclas (homogéneas y heterogéneas), los procedimientos de separación de mezclas (decantación, filtración, tamizado y destilación), considerando su aplicación industrial en la metalurgia, la minería y el tratamiento de aguas servidas, entre otros.'),
  ('7° Básico', 'Ciencias Naturales', 'OA15', 'Investigar experimentalmente los cambios de la materia y argumentar con evidencia empírica que estos pueden ser físicos o químicos. 147'),
  ('7° Básico', 'Educación Física', 'OA1', 'Aplicar, combinar y ajustar las habilidades motrices específicas de locomoción, manipulación y estabilidad en, al menos: • Un deporte individual (atletismo, gimnasia artística, entre otros). • Un deporte de oposición (tenis, bádminton, entre otros). • Un deporte de colaboración (escalada, remo, entre otros). • Un deporte de oposición/colaboración (básquetbol, hándbol, hockey, entre otros). • Una danza (folclórica, moderna, entre otras).'),
  ('7° Básico', 'Educación Física', 'OA2', 'Seleccionar y aplicar estrategias y tácticas específicas para la resolución de problemas durante la práctica de juegos o deportes; por ejemplo: ubicar la pelota lejos de un contrincante, utilizar los espacios para recibir un objeto sin oponentes, aplicar un sistema de juego (uno contra uno, tres contra tres, etc.), entre otros.'),
  ('7° Básico', 'Educación Física', 'OA3', 'Desarrollar la resistencia cardiovascular, la fuerza muscular, la velocidad y la flexibilidad para alcanzar una condición física saludable, considerando: • Frecuencia. • Intensidad. • Tiempo de duración. • Tipo de ejercicio (correr, andar en bicicleta, realizar trabajo de fuerza, ejercicios de flexibilidad, entre otros).'),
  ('7° Básico', 'Educación Física', 'OA4', 'Practicar regularmente una variedad de actividades físicas alternativas y/o deportivas, en diferentes entornos, aplicando conductas de autocuidado y seguridad, como realizar al menos 30 minutos diarios de actividades físicas de su interés; evitar el consumo de drogas, tabaco y alcohol; ejecutar un calentamiento; aplicar reglas y medidas de seguridad; hidratarse con agua de forma permanente; entre otras.'),
  ('7° Básico', 'Educación Física', 'OA5', 'Participar en una variedad actividades físicas y/o deportivas de su interés y que se desarrollan en su comunidad escolar y/o en su entorno; por ejemplo: • Integrarse en talleres extraprogramáticos de actividades físicas y/o deportivas que se desarrollan en su comunidad y/o entorno. • Asumir variados roles en la participación y promoción de una vida activa. • Utilizar los entornos cercanos para realizar alguna actividad física y/o deportiva (plazas, parques, entre otros).'),
  ('7° Básico', 'Historia, Geografía y Cs. Sociales', 'OA1', 'Explicar el proceso de hominización, reconociendo las principales etapas de la evolución de la especie humana, la influencia de factores geográficos, su dispersión en el planeta y las distintas teorías del poblamiento americano.'),
  ('7° Básico', 'Historia, Geografía y Cs. Sociales', 'OA2', 'Explicar que el surgimiento de la agricultura, la domesticación de animales, la sedentarización, la acumulación de bienes y el desarrollo del comercio fueron procesos de larga duración que revolucionaron la forma en que los seres humanos se relacionaron con el espacio geográfico.'),
  ('7° Básico', 'Historia, Geografía y Cs. Sociales', 'OA3', 'Explicar que, en las primeras civilizaciones, la formación de estados organizados y el ejercicio del poder estuvieron marcados por la centralización de la administración, la organización en torno a ciudades, la estratificación social, la formación de sistemas religiosos y el desarrollo de técnicas de contabilidad y escritura.'),
  ('7° Básico', 'Historia, Geografía y Cs. Sociales', 'OA4', 'Caracterizar el surgimiento de las primeras civilizaciones ( por ejemplo, sumeria, egipcia, china, india, minoica, fenicia, olmeca y chavín, entre otras), reconociendo que procesos similares se desarrollaron en distintos lugares y tiempos. 191'),
  ('7° Básico', 'Historia, Geografía y Cs. Sociales', 'OA5', 'Caracterizar el mar Mediterráneo como ecúmene y como espacio de circulación e intercambio, e inferir cómo sus características geográficas (por ejemplo, clima, relieve, recursos naturales, entre otros) influyeron en el desarrollo de la ciudad-estado griega y de la república romana.'),
  ('7° Básico', 'Historia, Geografía y Cs. Sociales', 'OA6', 'Analizar las principales características de la democracia en Atenas, considerando el contraste con otras formas de gobierno del mundo antiguo, y su importancia para el desarrollo de la vida política actual y el reconocimiento de los derechos de los ciudadanos.'),
  ('7° Básico', 'Historia, Geografía y Cs. Sociales', 'OA7', 'Relacionar las principales características de la civilización romana (derecho, organización burocrática y militar, infraestructura, esclavitud, entre otras) con la extensión territorial de su imperio, la relación con los pueblos conquistados, el proceso de romanización y la posterior expansión del cristianismo.'),
  ('7° Básico', 'Historia, Geografía y Cs. Sociales', 'OA8', 'Analizar, apoyándose en fuentes, el canon cultural que se constituyó en la Antigüedad clásica, considerando la centralidad del ser humano y la influencia de esta cultura en diversos aspectos de las sociedades del presente (por ejemplo, escritura alfabética, filosofía, ciencias, historia, noción de sujeto de derecho, relaciones de género, ideal de belleza, deporte, teatro, poesía y artes, entre otros). La Edad Media y el nacimiento de la civilización europea'),
  ('7° Básico', 'Historia, Geografía y Cs. Sociales', 'OA9', 'Explicar que la civilización europea se conforma a partir de la fragmentación de la unidad imperial de Occidente y la confluencia de las tradiciones grecorromana, judeocristiana y germana, e identificar a la Iglesia Católica como el elemento que articuló esta síntesis y que legitimó el poder político.'),
  ('7° Básico', 'Historia, Geografía y Cs. Sociales', 'OA10', 'Caracterizar algunos rasgos distintivos de la sociedad medieval, como la visión cristiana del mundo, el orden estamental, las relaciones de fidelidad, los roles de género, la vida rural y el declive de la vida urbana.'),
  ('7° Básico', 'Historia, Geografía y Cs. Sociales', 'OA11', 'Analizar ejemplos de relaciones de influencia, convivencia y conflicto entre el mundo europeo, el bizantino y el islámico durante la Edad Media, considerando la división del cristianismo y las relaciones de frontera entre la cristiandad y el islam en la península ibérica, entre otros.'),
  ('7° Básico', 'Historia, Geografía y Cs. Sociales', 'OA12', 'Analizar las transformaciones que se producen en Europa a partir del siglo XII, considerando el renacimiento de la vida urbana, los cambios demográficos, las innovaciones tecnológicas, el desarrollo del comercio y el surgimiento de las universidades. Civilizaciones americanas'),
  ('7° Básico', 'Historia, Geografía y Cs. Sociales', 'OA13', 'Identificar las principales características de las civilizaciones maya y azteca, considerando las tecnologías utilizadas para transformar el territorio que habitaban (urbanización, canales, acueductos y calzadas, formas de cultivo, entre otras) y el desarrollo de una red comercial que vinculaba al área mesoamericana.'),
  ('7° Básico', 'Historia, Geografía y Cs. Sociales', 'OA14', 'Caracterizar el Imperio inca, y analizar los factores que posibilitaron la dominación y unidad del imperio (por ejemplo, red de caminos y sistema de comunicaciones, sistemas de cultivo, organización social, administración, ejército, mita y yanaconaje, sometimiento de pueblos y lengua oficial, entre otros).'),
  ('7° Básico', 'Historia, Geografía y Cs. Sociales', 'OA15', 'Describir las principales características culturales de las civilizaciones maya, azteca e inca (por ejemplo, arte, lengua, tradiciones, relaciones de género, sistemas de medición del tiempo, ritos funerarios y creencias religiosas), e identificar aquellos elementos que persisten hasta el presente.'),
  ('7° Básico', 'Historia, Geografía y Cs. Sociales', 'OA16', 'Reconocer en expresiones culturales latinoamericanas del presente la confluencia del legado de múltiples civilizaciones, como la maya, azteca, inca, griega, romana y europea. ormación ciudadana: el legado del mundo antiguo'),
  ('7° Básico', 'Historia, Geografía y Cs. Sociales', 'OA17', 'Identificar los principios, mecanismos e instituciones que permitieron que en Atenas y en Roma se limitara el ejercicio del poder y se respetaran los derechos ciudadanos (por ejemplo, a través del equilibrio de poderes, del principio de elegibilidad, de la temporalidad de los cargos, de la ley y una cultura de la legalidad, de las magistraturas y del Senado romano, entre otros), reconociendo elementos de continuidad y de cambio con la actualidad.'),
  ('7° Básico', 'Historia, Geografía y Cs. Sociales', 'OA18', 'Comparar los conceptos de ciudadanía, democracia, derecho, república, municipio y gremio del mundo clásico y medieval con la sociedad contemporánea.'),
  ('7° Básico', 'Historia, Geografía y Cs. Sociales', 'OA19', 'Reconocer el valor de la diversidad como una forma de enriquecer culturalmente a las sociedades, identificando, a modo de ejemplo, los aportes que las distintas culturas existentes en el mundo antiguo y medieval (árabes, judeocristianos, germanos, eslavos, etc.) hicieron a las sociedades europeas, considerando el lenguaje, la religión y las ciencias, entre otros.'),
  ('7° Básico', 'Historia, Geografía y Cs. Sociales', 'OA20', 'Reconocer distintas formas de convivencia y conflicto entre culturas en las civilizaciones estudiadas, y debatir sobre la importancia que tienen el respeto, la tolerancia y las estrategias de resolución pacífica de conflictos, entre otros, para la convivencia entre distintos pueblos y culturas. er humano y medio'),
  ('7° Básico', 'Historia, Geografía y Cs. Sociales', 'OA21', 'Reconocer procesos de adaptación y transformación que se derivan de la relación entre el ser humano y el medio, e identificar factores que inciden en el asentamiento de las sociedades humanas (por ejemplo, disponibilidad de recursos, cercanía a zonas fértiles, fragilidad del medio ante la acción humana, o la vulnerabilidad de la población ante las amenazas del entorno).'),
  ('7° Básico', 'Historia, Geografía y Cs. Sociales', 'OA22', 'Reconocer y explicar formas en que la acción humana genera impactos en el medio y formas en las que el medio afecta a la población, y evaluar distintas medidas para propiciar efectos positivos y mitigar efectos negativos sobre ambos.'),
  ('7° Básico', 'Historia, Geografía y Cs. Sociales', 'OA23', 'Investigar sobre problemáticas medioambientales relacionadas con fenómenos como el calentamiento global, los recursos energéticos, la sobrepoblación, entre otros, y analizar y evaluar su impacto a escala local. 193'),
  ('7° Básico', 'Inglés', 'OA1', 'Demostrar comprensión de ideas generales e información explícita en textos orales adaptados y auténticos simples, literarios y no literarios, en diversos formatos audiovisuales (como exposiciones orales, conversaciones, descripciones, instrucciones, procedimientos, narraciones, rimas, juegos de palabras, canciones), acerca de temas variados (experiencias personales, temas de otras asignaturas, del contexto inmediato, de actualidad e interés global o de otras culturas) y que contienen las funciones del año1.'),
  ('7° Básico', 'Inglés', 'OA2', 'Identificar palabras y frases clave, expresiones de uso frecuente, vocabulario temático, conectores (first, second, next, finally, or, because, before, after, too when, while), sonidos /z/, /s/ (zoo/sad), sonido inicial /h/(hot/hour), y los sonidos /g/ (go/ago/egg) y / / (jacket/general/age) en textos orales en diversos formatos o al participar en interacciones cotidianas y conversaciones en la clase.'),
  ('7° Básico', 'Inglés', 'OA3', 'Identificar en los textos escuchados: • Tema e ideas generales. • Información específica y detalles relevantes asociados a personas y sus acciones, lugares, tiempo, hablantes y situaciones. • Pasos en instrucciones y procedimientos, secuencia de eventos, diferencia entre hecho y opinión, y relaciones de causa-efecto.'),
  ('7° Básico', 'Inglés', 'OA4', 'Identificar y usar estrategias para apoyar la comprensión de los textos escuchados: • Hacer predicciones. • Escuchar con un propósito. • Usar conocimientos previos. • Focalizar la atención en palabras y/o expresiones clave. • Utilizar apoyos como imágenes y gestos del hablante. • Preguntar para clarificar o corroborar información en interacciones. • Confirmar predicciones. • Resumir alguna idea con apoyo.'),
  ('7° Básico', 'Inglés', 'OA5', 'Presentar información en forma oral, usando recursos multimodales que refuercen el mensaje en forma creativa, acerca de temas variados (como experiencias personales, temas de otras asignaturas, otras culturas, problemas globales y textos leídos o escuchados), demostrando: • Conocimiento del contenido y coherencia en la organización de ideas. • Uso apropiado de las funciones del lenguaje y de vocabulario del nivel. • Uso apropiado de sonidos del idioma como /z//s/(zoo/sad), sonido inicial /h/ (hot/hour) y los sonidos /g/ (go/ago/egg) y / / (jacket/general/age). • Tener conciencia de audiencia, contexto y propósito.'),
  ('7° Básico', 'Inglés', 'OA6', 'Participar en interacciones y exposiciones, recurriendo a las siguientes estrategias para expresarse con claridad y fluidez: • Antes de hablar: practicar presentación, repetir, predecir vocabulario clave y expresiones de uso común (chunks), preparar apoyo organizacional y visual. • Al hablar: usar gestos y rellenos temporales (por ejemplo: well…; okay; so…), parafrasear y usar sinónimos, activar uso de conectores, solicitar ayuda. • Después de hablar: registrar errores y corregirlos con ayuda de la o el docente y recursos.'),
  ('7° Básico', 'Inglés', 'OA8', 'Demostrar conocimiento y uso del lenguaje en conversaciones, discusiones y exposiciones por medio de las siguientes funciones: • Expresar cantidades, contar y enumerar; por ejemplo: there is /are many/ much/eighty/a hundred/some people/water; too. • Identificar y describir objetos, deportes y hobbies; por ejemplo: these/those cars are fast; it’s a plastic bottle. • Expresarse sobre actividades; por ejemplo: riding/skating is cool/boring. • Describir estado de ánimo; por ejemplo: he looks tired/hungry/nervous/good; I ‘m angry about/with… • Expresar sugerencias, obligación y prohibición; por ejemplo: I must practice; you mustn’t ride without a helmet; we could..; Don’t … • Expresar intenciones y necesidades; por ejemplo: we need/want/forget to recycle. • Demostrar posesión; por ejemplo: they are the students’ instruments. • Expresarse con claridad usando palabras y expresiones de uso común, sinónimos, palabras compuestas; por ejemplo: afraid of flying, give advice on…; laugh at..; ask for….; take a break; have fun/a good time; I want/don’t want…; see you later/soon; make a mistake/ plans/friends; for example; outdoor. • Señalar tiempo, el grado y el modo en que ocurren las acciones; por ejemplo: he won the race yesterday; she sings quietly; they run very fast; every week; a bit/ little, very…; suddenly. • Formular preguntas y justificar una opinión; por ejemplo: Why do you like football? I like football because it’s a team sport. 229 cto; por ejemplo: an ice cream melts if you heat it. preguntas sobre rutinas y acciones presentes y pasadas; d he cook? Yes/No, he does/doesn’t/did/didn’t. lo: I like that film too; Do you want the book or the magazine?; finally; he felt nervous before/after the test. e interrumpen u ocurren simultáneamente en el pasado; aying football in the yard, when it started to rain; while he listening to music.'),
  ('7° Básico', 'Inglés', 'OA9', 'Demostrar comprensión de ideas generales e información explícita en textos adaptados y auténticos simples, en formato impreso o digital, acerca de temas variados (como experiencias personales, temas de otras asignaturas, del contexto inmediato, de actualidad e interés global o de otras culturas) y que contienen las funciones del año.'),
  ('7° Básico', 'Inglés', 'OA10', 'Demostrar comprensión de textos no literarios (como descripciones, instrucciones, procedimientos, avisos publicitarios, emails, diálogos, páginas web, biografías, gráficos) al identificar: • Ideas generales, información específica y detalles. • Relaciones de adición y secuencia entre ideas, diferencia hecho-opinión y causa-efecto. • Palabras y frases clave, expresiones de uso frecuente y vocabulario temático. • Conectores (first, second, finally, next, or, when, while, before, after, too, because) y palabras derivadas de otras por medio del prefijo un- y de los sufijos –ing, -ly.'),
  ('7° Básico', 'Inglés', 'OA11', 'Demostrar comprensión de textos literarios (como canciones o poemas, tiras cómicas, cuentos breves y simples y novelas adaptadas) al identificar: • El tema como idea general, personajes y sus acciones, entorno (tiempo, lugar), trama (inicio, desarrollo, final). • Palabras y frases clave, expresiones de uso frecuente, vocabulario temático.'),
  ('7° Básico', 'Inglés', 'OA12', 'Identificar y usar estrategias para apoyar la comprensión de los textos leídos: • Prelectura: leer con un propósito, hacer predicciones, usar conocimientos previos. • Lectura: hacer lectura rápida y lectura focalizada, visualizar, identificar elementos organizacionales del texto (título, subtítulo, imágenes). • Postlectura: confirmar predicciones, usar organizadores gráficos, releer, recontar con apoyo, preguntar para confirmar información.'),
  ('7° Básico', 'Inglés', 'OA13', 'Escribir historias e información relevante, usando recursos multimodales que refuercen el mensaje en forma creativa en textos variados, acerca de temas como: • Experiencias personales. • Contenidos interdisciplinarios. • Problemas globales. • Cultura de otros países. • Textos leídos.'),
  ('7° Básico', 'Inglés', 'OA14', 'Escribir una variedad de textos breves, como cuentos, correos electrónicos, folletos, rimas, descripciones, utilizando los pasos del proceso de escritura (organizar ideas, redactar, revisar, editar, publicar), con ayuda de la o el docente, de acuerdo a un modelo y a un criterio de evaluación, recurriendo a herramientas como el procesador de textos y diccionario en línea.'),
  ('7° Básico', 'Inglés', 'OA15', 'Escribir para informar, expresar opiniones y narrar, usando: • Palabras, oraciones y estructuras aprendidas. • Conectores aprendidos. • Correcta ortografía de mayoría de palabras aprendidas de uso muy frecuente. • Puntuación apropiada (punto, coma, signos de interrogación).'),
  ('7° Básico', 'Inglés', 'OA16', 'Demostrar conocimiento y uso del lenguaje en sus textos escritos por medio de las siguiente funciones: • Expresar cantidades, contar y enumerar; por ejemplo: there is /are many/ much/a hundred/eighty/some people/water; too. • Identificar y describir objetos, deportes y pasatiempos; por ejemplo: these/ those cars are fast; it’s a plastic bottle. • Expresarse sobre actividades; por ejemplo: riding/skating is cool/boring. • Expresar obligación y prohibición; por ejemplo: I must practice; you mustn’t ride without a helmet. • Expresarse con claridad usando palabras y expresiones de uso común, sinónimos, palabras compuestas; por ejemplo: afraid of flying; angry about/ with…, give advice on…; have fun/a good time; I want/don’t want…; see you later/ soon; make a mistake/plans/friends; for example; suddenly; outdoor. • Señalar el tiempo, el grado y el modo en que ocurren las acciones; por ejemplo: he won the race yesterday; she sings quietly/softly/loudly; they run very fast; every week; very… • Formular preguntas y justificar respuestas; por ejemplo: Why do you like football? I like football because it’s a team sport. • Explicar causa y efecto; por ejemplo: an ice cream melts if you heat it. • Formular y responder preguntas sobre rutinas y acciones presentes y pasadas; por ejemplo: Does/did he cook? Yes/No, he does/doesn’t/did/didn’t. • Describir acciones que interrumpen u ocurren simultáneamente en el pasado; por ejemplo: I was playing football, when it started to rain; while he was cycling, she was listening to music; I saw a shark while I was swimming. • Unir ideas; por ejemplo: first, second, next, finally; he felt nervous before/after the test; it’s too dangerous to visit. 231'),
  ('7° Básico', 'Lenguaje y Comunicación', 'OA1', 'Leer habitualmente para aprender y recrearse, y seleccionar textos de acuerdo con sus preferencias y propósitos.'),
  ('7° Básico', 'Lenguaje y Comunicación', 'OA2', 'Reflexionar sobre las diferentes dimensiones de la experiencia humana, propia y ajena, a partir de la lectura de obras literarias y otros textos que forman parte de nuestras herencias culturales, abordando los temas estipulados para el curso y las obras sugeridas para cada uno1.'),
  ('7° Básico', 'Lenguaje y Comunicación', 'OA3', 'Analizar las narraciones leídas para enriquecer su comprensión, considerando, cuando sea pertinente: • El o los conflictos de la historia. • El papel que juega cada personaje en el conflicto y cómo sus acciones afectan a otros personajes. • El efecto de ciertas acciones en el desarrollo de la historia. • Cuándo habla el narrador y cuándo hablan los personajes. • La disposición temporal de los hechos. • Elementos en común con otros textos leídos en el año.'),
  ('7° Básico', 'Lenguaje y Comunicación', 'OA4', 'Analizar los poemas leídos para enriquecer su comprensión, considerando, cuando sea pertinente: • Cómo el lenguaje poético que emplea el autor apela a los sentidos, sugiere estados de ánimo y crea imágenes. • El significado o el efecto que produce el uso de lenguaje figurado en el poema. • El efecto que produce el ritmo y la sonoridad del poema al leerlo en voz alta. • Elementos en común con otros textos leídos en el año.'),
  ('7° Básico', 'Lenguaje y Comunicación', 'OA5', 'Leer y comprender romances y obras de la poesía popular, considerando sus características y el contexto en el que se enmarcan.'),
  ('7° Básico', 'Lenguaje y Comunicación', 'OA6', 'Leer y comprender relatos mitológicos, considerando sus características y el contexto en el que se enmarcan.'),
  ('7° Básico', 'Lenguaje y Comunicación', 'OA7', 'Formular una interpretación de los textos literarios, considerando: • Su experiencia personal y sus conocimientos. • Un dilema presentado en el texto y su postura personal acerca del mismo. • La relación de la obra con la visión de mundo y el contexto histórico en el que se ambienta y/o en el que fue creada.'),
  ('7° Básico', 'Lenguaje y Comunicación', 'OA8', 'Analizar y evaluar textos con finalidad argumentativa, como columnas de opinión, cartas y discursos, considerando: • La postura del autor y los argumentos e información que la sostienen. • La diferencia entre hecho y opinión. • Su postura personal frente a lo leído y argumentos que la sustentan.'),
  ('7° Básico', 'Lenguaje y Comunicación', 'OA9', 'Analizar y evaluar textos de los medios de comunicación, como noticias, reportajes, cartas al director, textos publicitarios o de las redes sociales, considerando: • Los propósitos explícitos e implícitos del texto. • Una distinción entre los hechos y las opiniones expresados. • Presencia de estereotipos y prejuicios. • El análisis e interpretación de imágenes, gráficos, tablas, mapas o diagramas, y su relación con el texto en el que están insertos. • Los efectos que puede tener la información divulgada en los hombres o las mujeres aludidos en el texto.'),
  ('7° Básico', 'Lenguaje y Comunicación', 'OA10', 'Leer y comprender textos no literarios para contextualizar y complementar las lecturas literarias realizadas en clases.'),
  ('7° Básico', 'Lenguaje y Comunicación', 'OA11', 'Aplicar estrategias de comprensión de acuerdo con sus propósitos de lectura: • Resumir. • Formular preguntas. • Analizar los distintos tipos de relaciones que establecen las imágenes o el sonido con el texto escrito (en textos multimodales). • Identificar los elementos del texto que dificultan la comprensión (pérdida de los referentes, vocabulario desconocido, inconsistencias entre la información del texto y los propios conocimientos) y buscar soluciones.'),
  ('7° Básico', 'Lenguaje y Comunicación', 'OA12', 'Expresarse en forma creativa por medio de la escritura de textos de diversos géneros (por ejemplo, cuentos, crónicas, diarios de vida, cartas, poemas, etc.), escogiendo libremente: • El tema. • El género. • El destinatario. 51'),
  ('7° Básico', 'Lenguaje y Comunicación', 'OA13', 'Escribir, con el propósito de explicar un tema, textos de diversos géneros (por ejemplo, artículos, informes, reportajes, etc.), caracterizados por: • Una presentación clara del tema. • La presencia de información de distintas fuentes. • La inclusión de hechos, descripciones, ejemplos o explicaciones que desarrollen el tema. • Una progresión temática clara, con especial atención al empleo de recursos anafóricos. • El uso de imágenes u otros recursos gráficos pertinentes. • Un cierre coherente con las características del género. • El uso de referencias según un formato previamente acordado.'),
  ('7° Básico', 'Lenguaje y Comunicación', 'OA14', 'Escribir, con el propósito de persuadir, textos breves de diversos géneros (por ejemplo, cartas al director, editoriales, críticas literarias, etc.), caracterizados por: • La presentación de una afirmación referida a temas contingentes o literarios. • La presencia de evidencias e información pertinente. • La mantención de la coherencia temática.'),
  ('7° Básico', 'Lenguaje y Comunicación', 'OA15', 'Planificar, escribir, revisar, reescribir y editar sus textos en función del contexto, el destinatario y el propósito: • Recopilando información e ideas y organizándolas antes de escribir. • Adecuando el registro, específicamente el vocabulario (uso de términos técnicos, frases hechas, palabras propias de las redes sociales, términos y expresiones propios del lenguaje hablado), el uso de la persona gramatical y la estructura del texto, al género discursivo, contexto y destinatario. • Incorporando información pertinente. • Asegurando la coherencia y la cohesión del texto. • Cuidando la organización a nivel oracional y textual. • Usando conectores adecuados para unir las secciones que componen el texto. • Usando un vocabulario variado y preciso. • Reconociendo y corrigiendo usos inadecuados, especialmente de pronombres personales y reflejos, conjugaciones verbales, participios irregulares, y concordancia sujeto–verbo, artículo–sustantivo y sustantivo–adjetivo. • Corrigiendo la ortografía y mejorando la presentación. • Usando eficazmente las herramientas del procesador de textos.'),
  ('7° Básico', 'Lenguaje y Comunicación', 'OA16', 'Aplicar los conceptos de oración, sujeto y predicado con el fin de revisar y mejorar sus textos: • Produciendo consistentemente oraciones completas. • Conservando la concordancia entre sujeto y predicado. • Ubicando el sujeto, para determinar de qué o quién se habla.'),
  ('7° Básico', 'Lenguaje y Comunicación', 'OA17', 'Usar en sus textos recursos de correferencia léxica: • Empleando adecuadamente la sustitución léxica, la sinonimia y la hiperonimia. • Reflexionando sobre las relaciones de sinonimia e hiperonimia y su papel en la redacción de textos cohesivos y coherentes.'),
  ('7° Básico', 'Lenguaje y Comunicación', 'OA18', 'Utilizar adecuadamente, al narrar, los tiempos verbales del indicativo, manteniendo una adecuada secuencia de tiempos verbales.'),
  ('7° Básico', 'Lenguaje y Comunicación', 'OA19', 'Escribir correctamente para facilitar la comprensión al lector: • Aplicando todas las reglas de ortografía literal y acentual. • Verificando la escritura de las palabras cuya ortografía no está sujeta a reglas. • Usando correctamente punto, coma, raya y dos puntos.'),
  ('7° Básico', 'Lenguaje y Comunicación', 'OA20', 'Comprender, comparar y evaluar textos orales y audiovisuales tales como exposiciones, discursos, documentales, noticias, reportajes, etc., considerando: • Su postura personal frente a lo escuchado y argumentos que la sustenten. • Los temas, conceptos o hechos principales. • Una distinción entre los hechos y las opiniones expresados. • Diferentes puntos de vista expresados en los textos. • Las relaciones que se establecen entre imágenes, texto y sonido. • Relaciones entre lo escuchado y otras manifestaciones artísticas. • Relaciones entre lo escuchado y los temas y obras estudiados durante el curso.'),
  ('7° Básico', 'Lenguaje y Comunicación', 'OA21', 'Dialogar constructivamente para debatir o explorar ideas: • Manteniendo el foco. • Demostrando comprensión de lo dicho por el interlocutor. • Fundamentando su postura de manera pertinente. • Formulando preguntas o comentarios que estimulen o hagan avanzar la discusión o profundicen un aspecto del tema. • Negociando acuerdos con los interlocutores. • Considerando al interlocutor para la toma de turnos.'),
  ('7° Básico', 'Lenguaje y Comunicación', 'OA22', 'Expresarse frente a una audiencia de manera clara y adecuada a la situación, para comunicar temas de su interés: • Presentando información fidedigna y que denota una investigación previa. • Siguiendo una progresión temática clara. • Dando ejemplos y explicando algunos términos o conceptos clave para la comprensión de la información. • Usando un vocabulario variado y preciso y evitando el uso de muletillas. • Usando material visual que apoye lo dicho y se relacione directamente con lo que se explica.'),
  ('7° Básico', 'Lenguaje y Comunicación', 'OA23', 'Usar conscientemente los elementos que influyen y configuran los textos orales: • Comparando textos orales y escritos para establecer las diferencias, considerando el contexto y el destinatario. • Demostrando dominio de los distintos registros y empleándolos adecuadamente según la situación. • Utilizando estrategias que permiten cuidar la relación con el otro, especialmente al mostrar desacuerdo. • Utilizando un volumen, una velocidad y una dicción adecuados al propósito y a la situación. 53'),
  ('7° Básico', 'Lenguaje y Comunicación', 'OA24', 'Realizar investigaciones sobre diversos temas para complementar sus lecturas o responder interrogantes relacionadas con el lenguaje y la literatura: • Delimitando el tema de investigación. • Utilizando los principales sistemas de búsqueda de textos en la biblioteca e internet. • Usando los organizadores y la estructura textual para encontrar información de manera eficiente. • Evaluando si los textos entregan suficiente información para responder una determinada pregunta o cumplir un propósito. • Organizando en categorías la información encontrada en las fuentes investigadas. • Registrando la información bibliográfica de las fuentes consultadas. • Elaborando un texto oral o escrito bien estructurado que comunique sus hallazgos.'),
  ('7° Básico', 'Lenguaje y Comunicación', 'OA25', 'Sintetizar, registrar y ordenar las ideas principales de textos escuchados o leídos para satisfacer propósitos como estudiar, hacer una investigación, recordar detalles, etc.'),
  ('7° Básico', 'Matemática', 'OA1', 'Mostrar que comprenden la adición y la sustracción de números enteros: • Representando los números enteros en la recta numérica. • Representándolas de manera concreta, pictórica y simbólica. • Dándole significado a los símbolos + y – según el contexto (por ejemplo: un movimiento en una dirección seguido de un movimiento equivalente en la posición opuesta no representa ningún cambio de posición). • Resolviendo problemas en contextos cotidianos.'),
  ('7° Básico', 'Matemática', 'OA2', 'Explicar la multiplicación y la división de fracciones positivas: • Utilizando representaciones concretas, pictóricas y simbólicas. • Relacionándolas con la multiplicación y la división de números decimales.'),
  ('7° Básico', 'Matemática', 'OA3', 'Resolver problemas que involucren la multiplicación y la división de fracciones y de decimales positivos de manera concreta, pictórica y simbólica (de forma manual y/o con software educativo).'),
  ('7° Básico', 'Matemática', 'OA4', 'Mostrar que comprenden el concepto de porcentaje: • Representándolo de manera pictórica. • Calculando de varias maneras. • Aplicándolo a situaciones sencillas.'),
  ('7° Básico', 'Matemática', 'OA5', 'Utilizar potencias de base 10 con exponente natural: • Usando los términos potencia, base, exponente, elevado. • Definiendo y usando el exponente 0 en el sistema decimal. • Expresando números naturales en notación científica (sistema decimal). • Resolviendo problemas, usando la notación científica. 107'),
  ('7° Básico', 'Matemática', 'OA6', 'Utilizar el lenguaje algebraico para generalizar relaciones entre números, para establecer y formular reglas y propiedades y construir ecuaciones.'),
  ('7° Básico', 'Matemática', 'OA7', 'Reducir expresiones algebraicas, reuniendo términos semejantes para obtener expresiones de la forma ax+ by + cz a, b, c, ∈ Z.'),
  ('7° Básico', 'Matemática', 'OA8', 'Mostrar que comprenden las proporciones directas e inversas: • Realizando tablas de valores para relaciones proporcionales. • Graficando los valores de la tabla. • Explicando las características de la gráfica. • Resolviendo problemas de la vida diaria y de otras asignaturas.'),
  ('7° Básico', 'Matemática', 'OA9', 'Modelar y resolver problemas diversos de la vida diaria y de otras asignaturas que involucran ecuaciones e inecuaciones lineales de la forma: • ax + b = c; x/a =b a, b y c ∈ N; a ≠ 0 • ax + b < c; ax + b > c ; x/a < b; x/a > b a, b y c ∈N; a ≠ 0 Geometría'),
  ('7° Básico', 'Matemática', 'OA10', 'Descubrir relaciones que involucran ángulos exteriores o interiores de diferentes polígonos.'),
  ('7° Básico', 'Matemática', 'OA11', 'Mostrar que comprenden el círculo: • Describiendo las relaciones entre el radio, el diámetro y el perímetro del círculo. • Estimando de manera intuitiva el perímetro y el área de un círculo. • Aplicando las aproximaciones del perímetro y del área en la resolución de problemas geométricos de otras asignaturas y de la vida diaria. • Identificándolo como lugar geométrico.'),
  ('7° Básico', 'Matemática', 'OA12', 'Construir objetos geométricos de manera manual y/o con software educativo: • Líneas, como las perpendiculares, las paralelas, las bisectrices y alturas en triángulos y cuadriláteros. • Puntos, como el punto medio, el centro de gravedad, el centro del círculo inscrito y del circunscrito de un triángulo. • Triángulos y cuadriláteros congruentes.'),
  ('7° Básico', 'Matemática', 'OA13', 'Desarrollar y aplicar la fórmula del área de triángulos, paralelogramos y trapecios.'),
  ('7° Básico', 'Matemática', 'OA14', 'Identificar puntos en el plano cartesiano, usando pares ordenados y vectores de forma concreta (juegos) y pictórica. robabilidad y estadística'),
  ('7° Básico', 'Matemática', 'OA15', 'Estimar el porcentaje de algunas características de una población desconocida por medio del muestreo.'),
  ('7° Básico', 'Matemática', 'OA16', 'Representar datos obtenidos en una muestra mediante tablas de frecuencias absolutas y relativas, utilizando gráficos apropiados, de manera manual y/o con software educativo.'),
  ('7° Básico', 'Matemática', 'OA17', 'Mostrar que comprenden las medidas de tendencia central y el rango: • Determinando las medidas de tendencia central para realizar inferencias sobre la población. • Determinando la medida de tendencia central adecuada para responder un problema planteado. • Utilizándolos para comparar dos poblaciones. • Determinando el efecto de un dato que es muy diferente a los otros.'),
  ('7° Básico', 'Matemática', 'OA18', 'Explicar las probabilidades de eventos obtenidos por medio de experimentos de manera manual y/o con software educativo: • Estimándolas de manera intuitiva. • Utilizando frecuencias relativas. • Relacionándolas con razones, fracciones o porcentaje.'),
  ('7° Básico', 'Matemática', 'OA19', 'Comparar las frecuencias relativas de un evento obtenidas al repetir un experimento de forma manual y/o con software educativo, con la probabilidad obtenida de manera teórica, usando diagramas de árbol, tablas o gráficos. 109'),
  ('7° Básico', 'Música', 'OA1', 'Reconocer sentimientos, sensaciones e ideas al escuchar manifestaciones y obras musicales de Chile y el mundo presentes en la tradición oral, escrita y popular, y manifestarlos mediante medios verbales, visuales, sonoros y corporales.'),
  ('7° Básico', 'Música', 'OA2', 'Identificar conscientemente los elementos del lenguaje musical y los procedimientos compositivos evidentes en la música escuchada, interpretada y creada.'),
  ('7° Básico', 'Música', 'OA3', 'Cantar y tocar repertorio diverso, desarrollando habilidades tales como precisión rítmica y melódica, expresividad, consciencia de fraseo y dinámica, entre otras, y fortaleciendo el interés por el hacer musical individual y grupal.'),
  ('7° Básico', 'Música', 'OA4', 'Interpretar a una y más voces repertorio diverso, incorporando como apoyo el uso de medios de registro y transmisión.'),
  ('7° Básico', 'Música', 'OA5', 'Improvisar y crear música dando énfasis a ambientaciones sonoras libres, acompañamientos rítmicos, melódicos o armónicos simples.'),
  ('7° Básico', 'Música', 'OA6', 'Reconocer fortalezas y áreas de crecimiento personal en la audición, interpretación, creación y reflexión.'),
  ('7° Básico', 'Música', 'OA7', 'Reconocer el rol de la música en la sociedad, considerando sus propias experiencias musicales, contextos en que surge y las personas que la cultivan.'),
  ('7° Básico', 'Orientación', 'OA1', 'Construir en forma individual y colectiva representaciones positivas de sí mismos, incorporando sus características, motivaciones, intereses y capacidades, y considerando las experiencias de cambio asociadas a la pubertad y adolescencia.'),
  ('7° Básico', 'Orientación', 'OA2', 'Analizar, considerando sus experiencias e inquietudes, la importancia que tiene para el desarrollo personal la integración de las distintas dimensiones de la sexualidad, el cuidado del cuerpo y la intimidad, discriminando formas de relacionarse en un marco de respeto y utilizando fuentes de información apropiadas para su desarrollo personal.'),
  ('7° Básico', 'Orientación', 'OA3', 'Identificar situaciones que puedan exponer a las y los adolescentes al consumo de sustancias nocivas para el organismo, conductas sexuales riesgosas, conductas violentas, entre otras problemáticas, reconociendo la importancia de desarrollar estrategias para enfrentarlas, y contar con recursos tales como la comunicación asertiva y la ayuda de personas significativas y/o especializadas, dentro o fuera del establecimiento.'),
  ('7° Básico', 'Orientación', 'OA4', 'Integrar a su vida cotidiana acciones que favorezcan el bienestar y la vida saludable en el plano personal y en la comunidad escolar, optando por una alimentación saludable y un descanso apropiado, realizando actividad física o practicando deporte, resguardando la intimidad e integridad del cuerpo e incorporando medidas de seguridad en el uso de redes sociales, entre otros.'),
  ('7° Básico', 'Orientación', 'OA5', 'Analizar sus relaciones, presenciales o virtuales por medio de las redes sociales, y las de su entorno inmediato atendiendo a los derechos de las personas involucradas, considerando los principios de igualdad, dignidad, inclusión y no discriminación, identificando circunstancias en las que no se ha actuado conforme a estos derechos y reconociendo el impacto en el bienestar de quienes se vean involucrados.'),
  ('7° Básico', 'Orientación', 'OA6', 'Resolver conflictos y desacuerdos mediante el diálogo, la escucha empática y la búsqueda de soluciones en forma respetuosa y sin violencia, reconociendo que el conflicto es una oportunidad de aprendizaje y desarrollo inherente a las relaciones humanas.'),
  ('7° Básico', 'Orientación', 'OA7', 'Reconocer intereses, inquietudes, problemas o necesidades compartidas con sus grupos de pertenencia, ya sea dentro del curso u otros espacios de participación, y colaborar para alcanzar metas comunes valorando el trabajo en equipo y los aportes de cada uno de sus miembros.'),
  ('7° Básico', 'Orientación', 'OA8', 'Elaborar acuerdos orientados al logro de fines compartidos por el curso utilizando los espacios de participación disponibles, como Consejo de curso, asambleas, encuentros u otros, contribuyendo democráticamente mediante el diálogo, el debate y el reconocimiento de representantes democráticamente electos, y respetando la diversidad de opiniones y el derecho de hombres y mujeres.'),
  ('7° Básico', 'Orientación', 'OA9', 'Reconocer sus intereses, motivaciones, necesidades y capacidades, comprendiendo la relevancia del aprendizaje escolar sistemático tanto para la exploración y desarrollo de estos como para la elaboración de sus proyectos personales.'),
  ('7° Básico', 'Orientación', 'OA10', 'Gestionar de manera autónoma sus propios procesos de aprendizaje escolar por medio del establecimiento de metas progresivas de aprendizaje, la definición de líneas de acción para lograrlas, el monitoreo de logros y la redefinición de acciones que resulten necesarias. 353'),
  ('7° Básico', 'Tecnología', 'OA1', 'Identificar necesidades personales o grupales del entorno cercano que impliquen soluciones de reparación, adaptación o mejora, reflexionando acerca de sus posibles aportes.'),
  ('7° Básico', 'Tecnología', 'OA2', 'Diseñar e implementar soluciones que respondan a las necesidades de reparación, adaptación o mejora de objetos o entornos, haciendo uso eficiente de recursos materiales, energéticos y digitales.'),
  ('7° Básico', 'Tecnología', 'OA3', 'Evaluar soluciones implementadas como respuesta a las necesidades de reparación, adaptación o mejora de objetos o entornos, aplicando criterios propios y técnicos.'),
  ('7° Básico', 'Tecnología', 'OA4', 'Comunicar el diseño, la planificación u otros procesos de la resolución de necesidades de reparación, adaptación o mejora de objetos o entornos, utilizando herramientas TIC y considerando el objetivo, la audiencia y aspectos éticos.'),
  ('7° Básico', 'Tecnología', 'OA5', 'Contrastar soluciones tecnológicas existentes de reparación, adaptación o mejora, identificando las necesidades a las que respondieron y el contexto en que fueron desarrolladas.'),
  ('7° Básico', 'Tecnología', 'OA6', 'Caracterizar algunos de los efectos que han tenido las soluciones tecnológicas existentes de reparación, adaptación o mejora, considerando aspectos sociales y ambientales.'),
  ('8° Básico', 'Artes Visuales', 'OA1', 'Crear proyectos visuales basados en la valoración crítica de manifestaciones estéticas referidas a problemáticas sociales y juveniles, en el espacio público y en diferentes contextos.'),
  ('8° Básico', 'Artes Visuales', 'OA2', 'Crear trabajos y proyectos visuales basados en sus imaginarios personales, investigando el manejo de materiales sustentables en procedimientos de grabado y pintura mural.'),
  ('8° Básico', 'Artes Visuales', 'OA3', 'Crear proyectos visuales basados en imaginarios personales, investigando en medios contemporáneos como libros de artista y arte digital.'),
  ('8° Básico', 'Artes Visuales', 'OA4', 'Realizar juicios críticos de manifestaciones visuales considerando las condiciones contextuales de su creador y utilizando criterios estéticos pertinentes.'),
  ('8° Básico', 'Artes Visuales', 'OA5', 'Realizar juicios críticos de trabajos y proyectos visuales personales y de sus pares, fundamentados en criterios referidos al contexto, la materialidad, el lenguaje visual y el propósito expresivo.'),
  ('8° Básico', 'Artes Visuales', 'OA6', 'Implementar propuestas de difusión hacia la comunidad de trabajos y proyectos de arte, en el contexto escolar o local, de forma directa o virtual, contemplando las manifestaciones visuales a exponer, el espacio, el montaje, el público y el aporte a la comunidad, entre otros. 333 Anexo e e 335 Objetivos de Aprendizaje 8° básico 1° medio 2° medio (OA 1) (OA 1) (OA 1) visuales basados visuales con diversos visuales basados en en la apreciación propósitos, basados la valoración crítica y el análisis de en la apreciación y de manifestaciones manifestaciones reflexión acerca de estéticas referidas a estéticas referidas la arquitectura, los problemáticas sociales a la relación entre espacios y el diseño y juveniles, en el personas, naturaleza urbano, en diferentes espacio público y en y medioambiente, en medios y contextos. diferentes contextos. diferentes contextos. es (OA 2) (OA 2) (OA 2) Crear trabajos visuales Crear trabajos y Crear trabajos y a partir de diferentes proyectos visuales proyectos visuales desafíos creativos, basados en sus basados en diferentes experimentando imaginarios desafíos creativos, con materiales personales, investigando el sustentables en investigando el manejo de materiales técnicas de impresión, manejo de materiales sustentables en procedimientos de escultura y diseño. grabado y pintura mural. (OA 3) (OA 3) (OA 3) Crear trabajos Crear proyectos Crear proyectos visuales a partir de visuales basados visuales basados diferentes desafíos en imaginarios en diferentes creativos, usando personales, desafíos creativos, medios de expresión investigando utilizando medios contemporáneos en medios contemporáneos como la instalación. contemporáneos como video y como libros de artista multimedia. e Objetivos de Aprendizaje 8° básico 1° medio 2° medio (OA 4) (OA 4) (OA 4) Analizar Realizar juicios críticos Argumentar juicios manifestaciones de manifestaciones críticos referidos a la s visuales patrimoniales visuales, valoración de diversas y contemporáneas, comprendiendo manifestaciones contemplando las condiciones visuales, configurando criterios como contextuales de su una selección personal el contexto, la creador y utilizando de criterios estéticos. materialidad, el criterios estéticos lenguaje visual y el pertinentes. (OA 5) (OA 5) (OA 5) aciones Evaluar trabajos Realizar juicios Argumentar visuales personales críticos de trabajos evaluaciones y juicios rabajo y de sus pares, y proyectos visuales críticos, valorando el nal considerando criterios personales y de sus trabajo visual personal y como la materialidad, pares, fundamentados y de sus pares, y del el lenguaje visual y el en criterios referidos seleccionando criterios . propósito expresivo. al contexto, la de análisis según materialidad, el el tipo de trabajo lenguaje visual y el o proyecto visual propósito expresivo. apreciado. (OA 6) (OA 6) (OA 6) usión espacios de difusión de difusión hacia propuestas de difusión suales de las artes visuales, la comunidad de hacia la comunidad de os considerando los trabajos y proyectos trabajos y proyectos sión medios de expresión de arte, en el contexto de arte, en el contexto spacio, presentes, el espacio, escolar y local, de escolar y local, de público el montaje, el público forma directa o virtual forma directa o virtual, comunidad. las manifestaciones manifestaciones visuales a exponer, el visuales a exponer, el espacio, el montaje, espacio, el montaje, el público y el aporte el público y el aporte a la comunidad, entre a la comunidad, entre otros. otros. 337'),
  ('8° Básico', 'Ciencias Naturales', 'OA1', 'Explicar cómo el sistema nervioso coordina las acciones del organismo para adaptarse a estímulos del ambiente por medio de señales transmitidas por neuronas a lo largo del cuerpo, e investigar y comunicar sus cuidados, como las horas de sueño, el consumo de drogas, café y alcohol, y la prevención de traumatismos.'),
  ('8° Básico', 'Ciencias Naturales', 'OA2', 'Analizar e interpretar datos para proveer de evidencias que apoyen que la diversidad de organismos es el resultado de la evolución, considerando: • Evidencias de la evolución (como el registro fósil, las estructuras anatómicas homólogas, la embriología y las secuencias de ADN). • Los postulados de la teoría de la selección natural. • Los aportes de científicos como Darwin y Wallace a las teorías evolutivas. *Experimental(es), no experimental(es) o documental(es), entre otras. 157'),
  ('8° Básico', 'Ciencias Naturales', 'OA3', 'Explicar, basándose en evidencias, que la clasificación de la diversidad de organismos se construye a través del tiempo sobre la base de criterios taxonómicos que permiten organizarlos en grupos y subgrupos, identificando sus relaciones de parentesco con ancestros comunes.'),
  ('8° Básico', 'Ciencias Naturales', 'OA4', 'Investigar y explicar cómo se organizan e interactúan los seres vivos en diversos ecosistemas, a partir de ejemplos de Chile, considerando: • Los niveles de organización de los seres vivos (como organismo, población, comunidad, ecosistema). • Las interacciones biológicas (como depredación, competencia, comensalismo, mutualismo, parasitismo).'),
  ('8° Básico', 'Ciencias Naturales', 'OA5', 'Explicar, basándose en evidencias, la interacción de sistemas del cuerpo humano organizados por estructuras especializadas que contribuyen a su equilibrio, considerando: • La digestión de los alimentos por medio de la acción de enzimas digestivas y su absorción o paso a la sangre. • El rol del sistema circulatorio en el transporte de sustancias como nutrientes, gases, desechos metabólicos y anticuerpos. • El proceso de ventilación pulmonar e intercambio gaseoso a nivel alveolar. • El rol del sistema excretor en relación con la filtración de la sangre, la regulación de la cantidad de agua en el cuerpo y la eliminación de desechos. • La prevención de enfermedades debido al consumo excesivo de sustancias, como tabaco, alcohol, grasas y sodio, que se relacionan con estos sistemas.'),
  ('8° Básico', 'Ciencias Naturales', 'OA6', 'Investigar y argumentar, basándose en evidencias, que el material genético se transmite de generación en generación en organismos como plantas y animales, considerando: • La comparación de la mitosis y la meiosis. • Las causas y consecuencias de anomalías y pérdida de control de la división celular (tumor, cáncer, trisomía, entre otros).'),
  ('8° Básico', 'Ciencias Naturales', 'OA7', 'Analizar y evaluar, basándose en evidencias, los factores que contribuyen a mantener un cuerpo saludable, proponiendo un plan que considere: • Una alimentación balanceada. • Un ejercicio físico regular. • Evitar consumo de alcohol, tabaco y drogas. Física'),
  ('8° Básico', 'Ciencias Naturales', 'OA8', 'Explicar y evaluar los efectos de acciones humanas (conservación ambiental, cultivos, forestación y deforestación, entre otras) y de fenómenos naturales (sequías, erupciones volcánicas, entre otras) en relación con: • El equilibrio de los ecosistemas. • La disponibilidad de recursos naturales renovables y no renovables. • Las posibles medidas para un desarrollo sustentable. Física'),
  ('8° Básico', 'Ciencias Naturales', 'OA9', 'Demostrar que comprenden, por medio de la creación de modelos y experimentos, que las ondas transmiten energía y que se pueden reflejar, refractar y absorber, explicando y considerando: • Sus características (amplitud, frecuencia, longitud de onda y velocidad de propagación, entre otras). • Los criterios para clasificarlas (mecánicas, electromagnéticas, transversales, longitudinales, superficiales).'),
  ('8° Básico', 'Ciencias Naturales', 'OA10', 'Explicar fenómenos del sonido perceptibles por las personas, como el eco, la resonancia y el efecto Doppler, entre otros, utilizando el modelo ondulatorio y por medio de la experimentación, considerando sus: • Características y cualidades (intensidad, tono, timbre y rapidez). • Emisiones (en cuerdas vocales, en parlantes e instrumentos musicales). • Consecuencias (contaminación y medio de comunicación ). • Aplicaciones tecnológicas (ecógrafo, sonar y estetoscopio, entretención, entre otras).'),
  ('8° Básico', 'Ciencias Naturales', 'OA11', 'Desarrollar modelos e investigaciones experimentales que expliquen el calor como un proceso de transferencia de energía térmica entre dos o más cuerpos que están a diferentes temperaturas, o entre una fuente térmica y un objeto, considerando: • Las formas en que se propaga (conducción, convección y radiación). • Los efectos que produce (cambio de temperatura, deformación y cambio de estado, entre otros). • La cantidad de calor cedida y absorbida en un proceso térmico. • Objetos tecnológicos que protegen de altas o bajas temperaturas a seres vivos y objetos. • Su diferencia con la temperatura (a nivel de sus partículas). • Mediciones de temperatura, usando termómetro y variadas escalas, como Celsius, Kelvin y Fahrenheit, entre otras. ímica'),
  ('8° Básico', 'Ciencias Naturales', 'OA12', 'Explorar y describir el funcionamiento del oído y del ojo humano, considerando: • La recepción de ondas sonoras y luminosas. • El espectro sonoro y de la luz visible. • Sus capacidades, limitaciones y consecuencias sociales. • La tecnología correctiva (lentes y audífonos).'),
  ('8° Básico', 'Ciencias Naturales', 'OA13', 'Describir el origen y la propagación, por medio del modelo ondulatorio, de la energía liberada en un sismo, considerando: • Los parámetros que las describen (epicentro, hipocentro, área de ruptura, magnitud e intensidad). • Los tipos de ondas sísmicas (primarias, secundarias y superficiales). • Su medición y registro (sismógrafo y escalas sísmicas). • Sus consecuencias directas e indirectas en la superficie de la Tierra (como tsunamis) y en la sociedad. • Su importancia en geología, por ejemplo, en el estudio de la estructura interna de la Tierra.'),
  ('8° Básico', 'Ciencias Naturales', 'OA14', 'Crear modelos que expliquen los fenómenos astronómicos del sistema solar relacionados con: • Los movimientos del sistema Tierra-luna y los fenómenos de luz y sombra, como las fases lunares y los eclipses. • Los movimientos de la tierra respecto del sol y sus consecuencias, como las estaciones climáticas. • La comparación de los distintos planetas con la Tierra en cuanto a su distancia al sol, su tamaño, su período orbital, su atmósfera y otros.'),
  ('8° Básico', 'Ciencias Naturales', 'OA15', 'Describir y comparar diversas estructuras cósmicas, como meteoros, asteroides, cometas, satélites, planetas, estrellas, nebulosas, galaxias y cúmulo de galaxias, considerando: • Sus tamaños y formas. • Sus posiciones en el espacio. • Temperatura, masa, color y magnitud, entre otros.'),
  ('8° Básico', 'Ciencias Naturales', 'OA16', 'Investigar y explicar sobre la investigación astronómica en Chile y el resto del mundo, considerando aspectos como: • El clima y las ventajas que ofrece nuestro país para la observación astronómica. • La tecnología utilizada (telescopios, radiotelescopios y otros instrumentos astronómicos). • La información que proporciona la luz y otras radiaciones emitidas por los astros. • Los aportes de científicas chilenas y científicos chilenos. 159'),
  ('8° Básico', 'Ciencias Naturales', 'OA17', 'Investigar experimentalmente y explicar, usando evidencias, que la fermentación, la combustión provocada por un motor y un calefactor, y la oxidación de metales, entre otras, son reacciones químicas presentes en la vida diaria, considerando: • La producción de gas, la formación de precipitados, el cambio de temperatura, color y olor, y la emisión de luz, entre otros. • La influencia de la cantidad de sustancia, la temperatura, el volumen y la presión en ellas. • Su representación simbólica en ecuaciones químicas. • Su impacto en los seres vivos y el entorno.'),
  ('8° Básico', 'Ciencias Naturales', 'OA18', 'Desarrollar modelos que expliquen la estereoquímica e isomería de compuestos orgánicos como la glucosa, identificando sus propiedades y su utilidad para los seres vivos. 165 Anexo Glosario habilidades científicas 167 de objetos, fenómenos o procesos presentes en el estudio de las a relación entre ellas y el todo. jetos, conceptos o procesos para identificar similitudes y/o os, sobre la base de determinados criterios. nes, preguntas y predicciones científicas para explicarlas o a verbal, escrita o gráfica. Comunicar puede implicar el uso de TIC agramas, dibujos, maquetas, gráficos y tablas, entre otros. Requiere ción y creatividad. inicial de la investigación basándose en la evidencia obtenida, rtunidades de investigación. eleccionar y ajustar representaciones concretas, mentales, gráficas y sus relaciones. Los modelos pueden ser fórmulas, dibujos, positivos y negativos de las etapas de la investigación científica ropio y de los compañeros o las compañeras. respuesta a un problema sobre la base de evidencias provenientes ico o un experimento. interrogantes que nacen de la observación o la experimentación, rar nueva información. s que interactúan en un problema científico y clasificarlos en dientes y controlados. o a los datos, objetos o procesos científicos en estudio, mediante apropiado para la ciencia escolar. nto de actividades para responder interrogantes o resolver comprobar, demostrar y/o crear conocimientos a través de loración, la experimentación y la documentación, entre otras. ientífica se puede clasificar de acuerdo a distintos criterios. e evidencia se puede desarrollar investigación experimental, documental y/o bibliográfica. ente. álisis y comprensión. ibliográfica: cuando se busca información existente sobre un lema o fenómeno. Se utilizan diversas fuentes de información, istas, documentales y sitios web, entre otras. ades de medida estandarizada (metros, grados Celsius, etc.). e otras. ficas. s y/o cotidi