-- Objetivos de Aprendizaje MINEDUC — 1° a 8° Básico
--
-- Fuente: los PDF oficiales de Bases Curriculares, extraídos directamente con
-- backend/scripts/extract_curriculum_oa.py:
--   academia/content/articles-22394_bases.pdf  (1º a 6º básico)
--   academia/content/articles-37136_bases.pdf  (7º básico a 2º medio, 2015)
--
-- NO se reutilizó academia/content/curriculum_reference.md, que fue la fuente
-- de la migración 004: esa extracción arrastraba 51 descripciones truncadas de
-- 281 (18%), OA fusionados en una sola fila, 2 duplicados y un "OA0" que no
-- existe. Anclar la IA a objetivos cortados a media frase es peor que no
-- anclarla.
--
-- Filtros de calidad aplicados (ver es_valido() en el script): se descartan las
-- descripciones de menos de 30 caracteres, las truncadas, las que son
-- referencias bibliográficas —el parser cruza a esa sección en 6º Lenguaje,
-- 6º Ciencias y 8º Inglés—, las que traen tracking tipográfico del PDF
-- ("O b s er var y p regun tar") y las que no empiezan con verbo en
-- infinitivo, que es como se redacta todo OA del currículum chileno.
--
-- Las viñetas del PDF se normalizaron a "·".
-- grade_level y subject usan exactamente los strings de GRADE_LEVELS/SUBJECTS
-- en frontend/src/types/index.ts, para cruzar sin tabla de mapeo.
--
-- Idempotente: el DELETE limpia las filas basura que cargó una versión previa
-- de esta migración y el ON CONFLICT actualiza las descripciones.

-- Filas sin ninguna versión válida en el PDF: eran bibliografía.
DELETE FROM curriculum_oa WHERE (grade_level, subject, code) IN (
  ('8° Básico', 'Inglés', 'OA17'),
  ('8° Básico', 'Inglés', 'OA18'),
  ('8° Básico', 'Inglés', 'OA19'),
  ('8° Básico', 'Inglés', 'OA20'),
  ('8° Básico', 'Inglés', 'OA21'),
  ('8° Básico', 'Inglés', 'OA23'),
  ('8° Básico', 'Inglés', 'OA24')
);

ON CONFLICT (grade_level, subject, code)
DO UPDATE SET description = EXCLUDED.description;
